public class BeamItem : System.ComponentModel.INotifyPropertyChanged
{
    private bool _isSelected;
    private string _name = string.Empty;
    private double _width;
    private double _height;
    private double _length;
    private string _rebar = string.Empty;

    public bool IsSelected
    {
        get => _isSelected;
        set { _isSelected = value; OnPropertyChanged(nameof(IsSelected)); }
    }

    public string Name
    {
        get => _name;
        set { _name = value; OnPropertyChanged(nameof(Name)); }
    }

    public double Width
    {
        get => _width;
        set { _width = value; OnPropertyChanged(nameof(Width)); }
    }

    public double Height
    {
        get => _height;
        set { _height = value; OnPropertyChanged(nameof(Height)); }
    }

    public double Length
    {
        get => _length;
        set { _length = value; OnPropertyChanged(nameof(Length)); }
    }

    public string Rebar
    {
        get => _rebar;
        set { _rebar = value; OnPropertyChanged(nameof(Rebar)); }
    }

    public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
    protected void OnPropertyChanged(string name) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(name));
}


public class BoqGroupItem
{
    public string Category { get; set; } = string.Empty;
    public string ItemCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Unit { get; set; } = string.Empty;
    public double Quantity { get; set; }
    public double UnitPrice { get; set; }
    public double Amount => Quantity * UnitPrice;
    public string Status { get; set; } = "APPROVED";
}

public class RebarScheduleItem
{
    public string BarMark { get; set; } = string.Empty;
    public string Diameter { get; set; } = string.Empty;
    public int Quantity { get; set; }
    public string Spacing { get; set; } = "-";
    public double Length { get; set; }
    public double Weight { get; set; }
}

public class MasterStructureItem
{
    public string MemberId { get; set; } = string.Empty;
    public string FloorLevel { get; set; } = string.Empty;
    public string Section { get; set; } = string.Empty;
    public double SpanLength { get; set; }
    public double ConcreteVolume { get; set; }
    public double TotalRebarWeight { get; set; }
    public string Status { get; set; } = "APPROVED";
    public ObservableCollection<RebarScheduleItem> RebarList { get; set; } = new();
}

public class ElementSafetyItem
{
    public string ElementId { get; set; } = string.Empty;
    public string Type { get; set; } = string.Empty;
    public double Capacity { get; set; }
    public double AppliedLoad { get; set; }
    public double StressRatio => Math.Round(AppliedLoad / (Capacity > 0 ? Capacity : 1), 2);
    public double StressPercent { get => Math.Min(100.0, Math.Round(StressRatio * 100, 1)); set { } }
    public string Status => StressRatio > 1.0 ? "OVERLOAD" : StressRatio > 0.85 ? "WARNING" : "APPROVED";
    public string DiagnosticMessage => StressRatio > 1.0 ? $"EXCEEDS CAPACITY by {(StressRatio - 1.0):P0}! Reinforcement or section resize required." :
                                       StressRatio > 0.85 ? "High stress utilization (>85%). Verification recommended." : "Stress within allowable limits (Eurocode 2 / ACI 318).";
}

public class ShowcaseItem : System.ComponentModel.INotifyPropertyChanged
{
    private static int _nextIconAccentIndex;
    private static readonly string[] IconAccentKeys =
    [
        "CONCOST.Brush.Info",
        "CONCOST.Brush.Success",
        "CONCOST.Brush.Warning",
        "CONCOST.Brush.Danger",
        "CONCOST.Brush.TextSecondary"
    ];

    private readonly Func<object> _contentFactory;
    private object? _content;
    private readonly string _iconAccentKey;

    public string Name { get; set; } = string.Empty;
    public string Category { get; set; } = "Controls";
    public IconKind Icon { get; set; } = IconKind.Folder;
    public Brush IconAccent => (Brush)(Application.Current.TryFindResource(_iconAccentKey) ?? SystemColors.ControlTextBrush);
    public string Description { get; set; } = string.Empty;
    public object Content => _content ??= _contentFactory();
    public string DisplayName
    {
        get
        {
            var localization = LocalizationManager.Current;
            var itemName = localization.GetString($"Showcase.Item.{Name}", Name);
            if (!string.Equals(itemName, Name, StringComparison.Ordinal))
                return itemName;

            // Keep public WPF control/type names in English in the Vietnamese UI.
            if (localization.Culture.TwoLetterISOLanguageName.Equals("vi", StringComparison.OrdinalIgnoreCase))
                return Name;

            return localization.GetString($"Showcase.Component.{Name}", Name);
        }
    }
    public string DisplayCategory => Category switch
    {
        "Basic Controls" => LocalizationManager.Current.GetString("Showcase.Category.Basic", Category),
        "Custom Controls" => LocalizationManager.Current.GetString("Showcase.Category.Custom", Category),
        "Getting Started" => LocalizationManager.Current.GetString("Showcase.Category.GettingStarted", Category),
        _ => Category
    };
    public string DisplayDescription => LocalizationManager.Current.GetString($"Showcase.Description.{Name}", Description);

    public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;

    public ShowcaseItem(string name, string category, IconKind icon, string description, Func<object> contentFactory)
    {
        Name = name;
        Category = category;
        Icon = icon;
        Description = description;
        _contentFactory = contentFactory;
        _iconAccentKey = IconAccentKeys[Interlocked.Increment(ref _nextIconAccentIndex) % IconAccentKeys.Length];
        LocalizationManager.Current.PropertyChanged += OnLocalizationChanged;
    }

    public void RefreshContent() => _content = null;

    private void OnLocalizationChanged(object? sender, System.ComponentModel.PropertyChangedEventArgs e)
    {
        if (e.PropertyName is nameof(LocalizationManager.Culture) or "Item[]")
        {
            PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(DisplayName)));
            PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(DisplayCategory)));
            PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(DisplayDescription)));
        }
    }
}

public partial class ShowcaseViewModel : ObservableObject
{
    private bool _isDarkMode;
    private string _searchText = string.Empty;
    private string _selectedCategory = "All";
    private ShowcaseItem? _selectedItem;

    public ObservableCollection<ShowcaseItem> AllItems { get; } = new();
    public ObservableCollection<ShowcaseItem> FilteredItems { get; } = new();
    public string CatalogCountText => $"{AllItems.Count} {LocalizationManager.Current.GetString("Showcase.Catalog.Items", "items")}";

    public bool IsDarkMode
    {
        get => _isDarkMode;
        set
        {
            if (SetProperty(ref _isDarkMode, value))
            {
                ThemeManager.Current.Theme = value ? AppTheme.Dark : AppTheme.Light;
            }
        }
    }

    public string SearchText
    {
        get => _searchText;
        set
        {
            if (SetProperty(ref _searchText, value))
            {
                ApplyFilter();
            }
        }
    }

    public string SelectedCategory
    {
        get => _selectedCategory;
        set
        {
            if (SetProperty(ref _selectedCategory, value))
            {
                ApplyFilter();
            }
        }
    }

    public ShowcaseItem? SelectedItem
    {
        get => _selectedItem;
        set => SetProperty(ref _selectedItem, value);
    }

    public RelayCommand<string> SetAccentCommand { get; }
    public RelayCommand<string> SetCategoryCommand { get; }
    public RelayCommand ShowToastCommand { get; }

    public ShowcaseViewModel()
    {
        SetAccentCommand = new RelayCommand<string>(hex =>
        {
            if (!string.IsNullOrEmpty(hex))
                ThemeManager.Current.AccentColor = ColorHelper.FromHex(hex);
        });

        SetCategoryCommand = new RelayCommand<string>(cat =>
        {
            if (!string.IsNullOrEmpty(cat))
                SelectedCategory = cat;
        });

        ShowToastCommand = new RelayCommand(() => ToastService.Success(
            LocalizationManager.Current.GetString("Showcase.Toast.Message", "Action executed successfully!"),
            LocalizationManager.Current.GetString("Showcase.Toast.Title", "CONCOST UI")));

        InitShowcaseItems();
        ApplyFilter();
        SelectedItem = FilteredItems.FirstOrDefault(x => x.Name == "Overview") ?? FilteredItems.FirstOrDefault();
        LocalizationManager.Current.PropertyChanged += OnLocalizationChanged;
    }

    private void OnLocalizationChanged(object? sender, System.ComponentModel.PropertyChangedEventArgs e)
    {
        if (e.PropertyName != nameof(LocalizationManager.Culture))
            return;

        ApplyFilter();
        OnPropertyChanged(nameof(CatalogCountText));
        if (SelectedItem?.Name is "Overview" or "Documentation")
        {
            SelectedItem.RefreshContent();
            OnPropertyChanged(nameof(SelectedItem));
        }
    }

    private void OpenControl(string? name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return;

        var item = AllItems.FirstOrDefault(x => x.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
        if (item is null)
            return;

        SearchText = string.Empty;
        SelectedCategory = "All";
        SelectedItem = item;
    }

    private void BrowseCategory(string? category)
    {
        if (string.IsNullOrWhiteSpace(category))
            return;

        SearchText = string.Empty;
        SelectedCategory = category;
    }

