                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Solid & Semantic Appearances
        var solidPanel = new StackPanel();
        var solidWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var solidDisabledWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var types = new[] { ("Default", "CONCOST.Button.Secondary"), ("Primary", "CONCOST.Button.Primary"), ("Success", "CONCOST.Button.Success"), ("Info", "CONCOST.Button.Info"), ("Warning", "CONCOST.Button.Warning"), ("Danger", "CONCOST.Button.Danger") };

        foreach (var (lbl, styleKey) in types)
        {
            solidWp.Children.Add(new Button { Content = lbl, Style = (System.Windows.Style)App.Current.Resources[styleKey], Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 110 });
            solidDisabledWp.Children.Add(new Button { Content = $"{lbl} (Off)", Style = (System.Windows.Style)App.Current.Resources[styleKey], IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 110 });
        }
        solidPanel.Children.Add(new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        solidPanel.Children.Add(solidWp);
        solidPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        solidPanel.Children.Add(solidDisabledWp);

        string solidXaml =
@"<Button Content=""Default"" Style=""{DynamicResource CONCOST.Button.Secondary}"" Width=""110"" />
<Button Content=""Primary"" Style=""{DynamicResource CONCOST.Button.Primary}"" Width=""110"" />
<Button Content=""Success"" Style=""{DynamicResource CONCOST.Button.Success}"" Width=""110"" />
<Button Content=""Info"" Style=""{DynamicResource CONCOST.Button.Info}"" Width=""110"" />
<Button Content=""Warning"" Style=""{DynamicResource CONCOST.Button.Warning}"" Width=""110"" />
<Button Content=""Danger"" Style=""{DynamicResource CONCOST.Button.Danger}"" Width=""110"" />";

        AddCardSection("1. Solid Semantic Appearances", solidPanel, solidXaml);

        // Section 2: Outline & Ghost Appearances
        var outlinePanel = new StackPanel();
        var outlineWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var outlineDisabledWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var outlineTypes = new[] { ("Default", "CONCOST.Button.Secondary"), ("Primary", "CONCOST.Button.Outline.Primary"), ("Success", "CONCOST.Button.Outline.Success"), ("Info", "CONCOST.Button.Outline.Info"), ("Warning", "CONCOST.Button.Outline.Warning"), ("Danger", "CONCOST.Button.Outline.Danger") };

        foreach (var (lbl, styleKey) in outlineTypes)
        {
            outlineWp.Children.Add(new Button { Content = lbl, Style = (System.Windows.Style)App.Current.Resources[styleKey], Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 110 });
            outlineDisabledWp.Children.Add(new Button { Content = $"{lbl} (Off)", Style = (System.Windows.Style)App.Current.Resources[styleKey], IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 110 });
        }
        outlinePanel.Children.Add(new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        outlinePanel.Children.Add(outlineWp);
        outlinePanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        outlinePanel.Children.Add(outlineDisabledWp);

        string outlineXaml =
@"<Button Content=""Default"" Style=""{DynamicResource CONCOST.Button.Secondary}"" Width=""110"" />
<Button Content=""Primary"" Style=""{DynamicResource CONCOST.Button.Outline.Primary}"" Width=""110"" />
<Button Content=""Success"" Style=""{DynamicResource CONCOST.Button.Outline.Success}"" Width=""110"" />
<Button Content=""Info"" Style=""{DynamicResource CONCOST.Button.Outline.Info}"" Width=""110"" />
<Button Content=""Warning"" Style=""{DynamicResource CONCOST.Button.Outline.Warning}"" Width=""110"" />
<Button Content=""Danger"" Style=""{DynamicResource CONCOST.Button.Outline.Danger}"" Width=""110"" />";

        AddCardSection("2. Outline & Bordered Variants", outlinePanel, outlineXaml);

        // Section 3: Buttons with Vector Icons
        var iconPanel = new StackPanel();
        var iconWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var iconDisabledWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var iconBtns = new[] {
            ("Add Element", IconKind.Add, "CONCOST.Button.Primary"),
            ("Edit Section", IconKind.Edit, "CONCOST.Button.Secondary"),
            ("Save Model", IconKind.Save, "CONCOST.Button.Success"),
            ("Refresh Data", IconKind.Refresh, "CONCOST.Button.Info"),
            ("Delete Beam", IconKind.Delete, "CONCOST.Button.Danger")
        };

        foreach (var (lbl, icon, styleKey) in iconBtns)
        {
            var btn = new Button { Content = lbl, Style = (System.Windows.Style)App.Current.Resources[styleKey], Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btn, icon);
            iconWp.Children.Add(btn);

            var btnDis = new Button { Content = $"{lbl} (Off)", Style = (System.Windows.Style)App.Current.Resources[styleKey], IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btnDis, icon);
            iconDisabledWp.Children.Add(btnDis);
        }

        iconPanel.Children.Add(new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        iconPanel.Children.Add(iconWp);
        iconPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        iconPanel.Children.Add(iconDisabledWp);

        string iconXaml =
@"<Button Content=""Add Element"" Style=""{DynamicResource CONCOST.Button.Primary}"" attached:IconElement.Kind=""Add"" Width=""140"" />
<Button Content=""Edit Section"" Style=""{DynamicResource CONCOST.Button.Secondary}"" attached:IconElement.Kind=""Edit"" Width=""140"" />
<Button Content=""Save Model"" Style=""{DynamicResource CONCOST.Button.Success}"" attached:IconElement.Kind=""Save"" Width=""140"" />
<Button Content=""Refresh Data"" Style=""{DynamicResource CONCOST.Button.Info}"" attached:IconElement.Kind=""Refresh"" Width=""140"" />
<Button Content=""Delete Beam"" Style=""{DynamicResource CONCOST.Button.Danger}"" attached:IconElement.Kind=""Delete"" Width=""140"" />";

        AddCardSection("3. Action Buttons with Vector Icons", iconPanel, iconXaml);

        // Section 4: Pure Icon-Only Buttons (No Text: Square, Rounded, Circle & Ghost)
        var iconOnlyPanel = new StackPanel();
        var iconOnlyWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var iconOnlyDisabledWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var iconOnlyVariants = new[] {
            (IconKind.Add, "CONCOST.Button.Icon", "Add Item"),
            (IconKind.Edit, "CONCOST.Button.Icon.Primary", "Edit Record"),
            (IconKind.Save, "CONCOST.Button.Icon.Circle", "Save Changes"),
            (IconKind.Refresh, "CONCOST.Button.Icon.Primary.Circle", "Refresh Data"),
            (IconKind.Delete, "CONCOST.Button.Icon.Ghost", "Remove Item"),
            (IconKind.Settings, "CONCOST.Button.Icon.Ghost", "Settings")
        };

        foreach (var (icon, styleKey, tooltip) in iconOnlyVariants)
        {
            var btn = new Button
            {
                Style = (System.Windows.Style)App.Current.Resources[styleKey],
                ToolTip = tooltip,
                Margin = new System.Windows.Thickness(0, 0, 12, 8)
            };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btn, icon);
            iconOnlyWp.Children.Add(btn);

            var btnDis = new Button
            {
                Style = (System.Windows.Style)App.Current.Resources[styleKey],
                ToolTip = $"{tooltip} (Off)",
                Margin = new System.Windows.Thickness(0, 0, 12, 8),
                IsEnabled = false
            };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btnDis, icon);
            iconOnlyDisabledWp.Children.Add(btnDis);
        }

        iconOnlyPanel.Children.Add(new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        iconOnlyPanel.Children.Add(iconOnlyWp);
        iconOnlyPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        iconOnlyPanel.Children.Add(iconOnlyDisabledWp);

        string iconOnlyXaml =
@"<Button Style=""{DynamicResource CONCOST.Button.Icon}"" attached:IconElement.Kind=""Add"" ToolTip=""Add Item"" />
<Button Style=""{DynamicResource CONCOST.Button.Icon.Primary}"" attached:IconElement.Kind=""Edit"" ToolTip=""Edit Record"" />
<Button Style=""{DynamicResource CONCOST.Button.Icon.Circle}"" attached:IconElement.Kind=""Save"" ToolTip=""Save Changes"" />
<Button Style=""{DynamicResource CONCOST.Button.Icon.Primary.Circle}"" attached:IconElement.Kind=""Refresh"" ToolTip=""Refresh Data"" />
<Button Style=""{DynamicResource CONCOST.Button.Icon.Ghost}"" attached:IconElement.Kind=""Delete"" ToolTip=""Remove Item"" />
<Button Style=""{DynamicResource CONCOST.Button.Icon.Ghost}"" attached:IconElement.Kind=""Settings"" ToolTip=""Settings"" />";

        AddCardSection("4. Icon-Only Buttons", iconOnlyPanel, iconOnlyXaml);

        return mainSp;
    }

    private object CreateTextBoxDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrWhiteSpace(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid { Height = 34, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tagIcon = new CONCOST.UI.Icons.Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var langLabel = new TextBlock { Text = "XAML Code Example", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);
                codeBoxInner.Children.Add(codeTopBar);

                var div = new Border { Height = 1 };
                div.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(div);

                var codePresenter = new TextBlock
                {
                    Text = xamlSnippet.Trim(),
                    FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New, Segoe UI Mono, monospace"),
                    FontSize = 12,
                    LineHeight = 19,
                    Padding = new System.Windows.Thickness(14, 12, 14, 12),
                    TextWrapping = System.Windows.TextWrapping.Wrap
                };
                codePresenter.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBoxInner.Children.Add(codePresenter);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == System.Windows.Visibility.Visible
                        ? System.Windows.Visibility.Collapsed
                        : System.Windows.Visibility.Visible;
                    codeBtn.Content = codeBox.Visibility == System.Windows.Visibility.Visible ? "Hide XAML" : "View XAML";
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // ====================================================================================
        // SECTION 1: Visual Style Presets (Default 6px · Round Pill · Underline · Filled · Ghost)
        // ====================================================================================
        var sec1 = new StackPanel();

        var grid1 = new Grid();
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        grid1.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(14) });
        grid1.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        grid1.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(14) });
        grid1.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });

        // Row 0: Default & Round
        var tbDef = new TextBox { Text = "Default 6px Rounded Style" };
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(tbDef, "Enter project name...");
        CONCOST.UI.AttachedProperties.InfoElement.SetShowClearButton(tbDef, true);

        var tbRnd = new TextBox { Text = "Round Pill 17px Style" };
        tbRnd.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Round");
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(tbRnd, "Search elements...");
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tbRnd, IconKind.Search);
        CONCOST.UI.AttachedProperties.InfoElement.SetShowClearButton(tbRnd, true);

        Grid.SetRow(tbDef, 0); Grid.SetColumn(tbDef, 0); grid1.Children.Add(tbDef);
        Grid.SetRow(tbRnd, 0); Grid.SetColumn(tbRnd, 2); grid1.Children.Add(tbRnd);

        // Row 1: Underline & Filled
        var tbUnd = new TextBox { Text = "Underline Flat Material Style" };
        tbUnd.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Underline");
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(tbUnd, "Input parameter...");

        var tbFil = new TextBox { Text = "Filled Surface Tint Style" };
        tbFil.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Filled");
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(tbFil, "Filled container...");

        Grid.SetRow(tbUnd, 2); Grid.SetColumn(tbUnd, 0); grid1.Children.Add(tbUnd);
        Grid.SetRow(tbFil, 2); Grid.SetColumn(tbFil, 2); grid1.Children.Add(tbFil);

        // Row 2: Ghost Borderless & Read-Only
        var tbGho = new TextBox { Text = "Ghost Borderless Style (DataGrid / Table Cells)" };
        tbGho.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Ghost");
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(tbGho, "Click to edit cell...");

        var tbReadOnly = new TextBox { Text = "Read-Only Specification Field (Locked)", IsReadOnly = true };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tbReadOnly, IconKind.Lock);

        Grid.SetRow(tbGho, 4); Grid.SetColumn(tbGho, 0); grid1.Children.Add(tbGho);
        Grid.SetRow(tbReadOnly, 4); Grid.SetColumn(tbReadOnly, 2); grid1.Children.Add(tbReadOnly);

        sec1.Children.Add(grid1);

        AddCardSection("1. Visual Style Presets  (Default 6px · Round Pill · Underline · Filled · Ghost)", sec1,
@"<!-- Default 6px Rounded TextBox -->
<TextBox Text=""Default Rounded""
         attached:InfoElement.Placeholder=""Enter project name...""
         attached:InfoElement.ShowClearButton=""True"" />

<!-- Round Pill 17px Radius Style (Search & Filters) -->
<TextBox Text=""Round Pill""
         Style=""{StaticResource CONCOST.TextBox.Round}""
         attached:IconElement.Kind=""Search""
         attached:InfoElement.ShowClearButton=""True"" />

<!-- Underline Flat Material Style -->
<TextBox Text=""Underline Flat""
         Style=""{StaticResource CONCOST.TextBox.Underline}"" />

<!-- Filled Surface Background Style -->
<TextBox Text=""Filled Surface""
         Style=""{StaticResource CONCOST.TextBox.Filled}"" />

<!-- Ghost Borderless Style (In-Place Table Cell Editing) -->
<TextBox Text=""Ghost Borderless""
         Style=""{StaticResource CONCOST.TextBox.Ghost}"" />");

        // ====================================================================================
        // SECTION 2: Sizing Scale & Typography Hierarchy (Small 28px · Medium 34px · Large 42px)
        // ====================================================================================
        var sec2 = new StackPanel();

        var row2 = new Grid();
        row2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        row2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        row2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        row2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        row2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var tbSm = new TextBox { Text = "Small 28px Compact" };
        tbSm.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Small");
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tbSm, IconKind.Search);
        CONCOST.UI.AttachedProperties.InfoElement.SetShowClearButton(tbSm, true);

        var tbMd = new TextBox { Text = "Medium 34px Standard" };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tbMd, IconKind.Edit);
        CONCOST.UI.AttachedProperties.InfoElement.SetShowClearButton(tbMd, true);

        var tbLg = new TextBox { Text = "Large 42px Prominent" };
        tbLg.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Large");
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tbLg, IconKind.Folder);
        CONCOST.UI.AttachedProperties.InfoElement.SetShowClearButton(tbLg, true);

        Grid.SetColumn(tbSm, 0); row2.Children.Add(tbSm);
        Grid.SetColumn(tbMd, 2); row2.Children.Add(tbMd);
        Grid.SetColumn(tbLg, 4); row2.Children.Add(tbLg);
        sec2.Children.Add(row2);

        AddCardSection("2. Sizing Scale & Typography Hierarchy  (Small 28px · Medium 34px · Large 42px)", sec2,
@"<!-- Small Size: 28px height, 12px font, 13px icon -->
<TextBox Text=""Small Size""
         Style=""{StaticResource CONCOST.TextBox.Small}""
         attached:IconElement.Kind=""Search"" />

<!-- Medium Size: 34px height (Default standard) -->
<TextBox Text=""Medium Standard""
         attached:IconElement.Kind=""Edit"" />

<!-- Large Size: 42px height, 16px font, 18px icon -->
<TextBox Text=""Large Prominent""
         Style=""{StaticResource CONCOST.TextBox.Large}""
         attached:IconElement.Kind=""Folder"" />");

        // ====================================================================================
        // SECTION 3: Vector Icons, Prefix Labels & Suffix Units
        // ====================================================================================
        var sec3 = new StackPanel();

        var grid3 = new Grid();
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid3.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        grid3.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(14) });
