        grid4.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        grid4.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(14) });
        grid4.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });

        // Positive Decimal
        var tbFilter1 = new TextBox { Text = "550.5" };
        CONCOST.UI.AttachedProperties.TextBoxHelper.SetInputType(tbFilter1, TextBoxInputType.PositiveDecimal);
        CONCOST.UI.AttachedProperties.InfoElement.SetPrefix(tbFilter1, "h = ");
