        Grid.SetRow(tbFilter3, 2); Grid.SetColumn(tbFilter3, 0); grid4.Children.Add(tbFilter3);
        Grid.SetRow(tbFilter4, 2); Grid.SetColumn(tbFilter4, 2); grid4.Children.Add(tbFilter4);
