        Card CreateKPISummaryCard()
        {
            var card = new Card
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Card.Base"],
                Header = "Project Structural Quantity Takeoff Summary",
                Icon = IconKind.Layers,
                Width = 520,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                Margin = new System.Windows.Thickness(0)
            };

            var grid = new Grid();
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

            Border CreateMetricCell(string label, string value, string badgeText, Brush badgeBg, Brush badgeFg)
            {
                var b = new Border
                {
                    Background = (Brush)App.Current.Resources["CONCOST.Brush.SurfaceSecondary"],
                    CornerRadius = new System.Windows.CornerRadius(8),
                    Padding = new System.Windows.Thickness(12, 10, 12, 10),
                    Margin = new System.Windows.Thickness(0, 0, 8, 0)
                };
                var spInner = new StackPanel();
                var lbl = new TextBlock { Text = label, FontSize = 11, Foreground = (Brush)App.Current.Resources["CONCOST.Brush.TextSecondary"], Margin = new System.Windows.Thickness(0, 0, 0, 4) };
                var val = new TextBlock { Text = value, FontSize = 15, FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
                val.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");

                var badge = new Border
                {
                    Background = badgeBg,
                    CornerRadius = new System.Windows.CornerRadius(4),
                    Padding = new System.Windows.Thickness(6, 2, 6, 2),
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Left
                };
                badge.Child = new TextBlock { Text = badgeText, FontSize = 10.5, FontWeight = System.Windows.FontWeights.Normal, Foreground = badgeFg };

                spInner.Children.Add(lbl);
                spInner.Children.Add(val);
                spInner.Children.Add(badge);
                b.Child = spInner;
                return b;
            }

            var bSuccessBg = new SolidColorBrush(Color.FromArgb(28, 16, 185, 129));
            var bSuccessFg = new SolidColorBrush(Color.FromRgb(5, 150, 105));
            var bPrimaryBg = new SolidColorBrush(Color.FromArgb(28, 255, 121, 0));
            var bPrimaryFg = new SolidColorBrush(Color.FromRgb(255, 121, 0));
            var bBlueBg = new SolidColorBrush(Color.FromArgb(28, 37, 99, 235));
            var bBlueFg = new SolidColorBrush(Color.FromRgb(37, 99, 235));

            var cell1 = CreateMetricCell("Total Concrete", "1,420 m³", "B25 / B30 Grade", bPrimaryBg, bPrimaryFg);
            Grid.SetColumn(cell1, 0);
            grid.Children.Add(cell1);

            var cell2 = CreateMetricCell("Total Rebar", "168.5 Tons", "CB400 / CB500", bBlueBg, bBlueFg);
            Grid.SetColumn(cell2, 1);
            grid.Children.Add(cell2);

            var cell3 = CreateMetricCell("Formwork Area", "5,280 m²", "98% Optimized", bSuccessBg, bSuccessFg);
            Grid.SetColumn(cell3, 2);
            grid.Children.Add(cell3);

            card.Content = grid;
            return card;
        }

