    private object CreateDataGridDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrWhiteSpace(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid { Height = 34, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tagIcon = new CONCOST.UI.Icons.Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var langLabel = new TextBlock { Text = "XAML Code Example", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);
                codeBoxInner.Children.Add(codeTopBar);

                var div = new Border { Height = 1 };
                div.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(div);

                var codePresenter = new TextBlock
                {
                    Text = xamlSnippet.Trim(),
                    FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New, Segoe UI Mono, monospace"),
                    FontSize = 12,
                    LineHeight = 19,
                    Padding = new System.Windows.Thickness(14, 12, 14, 12),
                    TextWrapping = System.Windows.TextWrapping.Wrap
                };
                codePresenter.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBoxInner.Children.Add(codePresenter);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == System.Windows.Visibility.Visible
                        ? System.Windows.Visibility.Collapsed
                        : System.Windows.Visibility.Visible;
                    codeBtn.Content = codeBox.Visibility == System.Windows.Visibility.Visible ? "Hide XAML" : "View XAML";
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        var sampleBeams = new ObservableCollection<BeamItem>
        {
            new() { Name = "D1 - Girder Span A-B", Width = 300, Height = 600, Length = 6000, Rebar = "4D20 + 2D18" },
            new() { Name = "D2 - Secondary Beam 1-2", Width = 200, Height = 400, Length = 4500, Rebar = "3D16" },
            new() { Name = "D3 - Balcony Cantilever", Width = 250, Height = 500, Length = 1800, Rebar = "4D18" },
            new() { Name = "D4 - Pitch Roof Girder", Width = 300, Height = 700, Length = 7200, Rebar = "6D22" }
        };

        var editTextBoxStyle = (System.Windows.Style)App.Current.Resources["CONCOST.DataGrid.EditingTextBox"];

        // ==============================================================================?
        // SECTION 1: Standard Floating Card Rows (Interactive Selection)
        // ==============================================================================?
        var dg1 = new DataGrid { ItemsSource = sampleBeams, Height = 210 };
        dg1.Columns.Add(new DataGridTextColumn { Header = "Element Name", Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(2, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg1.Columns.Add(new DataGridTextColumn { Header = "Width b (mm)", Binding = new System.Windows.Data.Binding("Width"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg1.Columns.Add(new DataGridTextColumn { Header = "Depth h (mm)", Binding = new System.Windows.Data.Binding("Height"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg1.Columns.Add(new DataGridTextColumn { Header = "Rebar Layout", Binding = new System.Windows.Data.Binding("Rebar"), Width = new DataGridLength(1.5, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });

        AddCardSection("1. Floating Row Cards Style (Standard 40px Height)", dg1,
@"<!-- Standard DataGrid with Floating Card Rows -->
<DataGrid ItemsSource=""{Binding BeamList}"" Height=""210"">
    <DataGrid.Columns>
        <DataGridTextColumn Header=""Element Name"" Binding=""{Binding Name}"" Width=""2*"" />
        <DataGridTextColumn Header=""Width b (mm)"" Binding=""{Binding Width}"" Width=""*"" />
        <DataGridTextColumn Header=""Depth h (mm)"" Binding=""{Binding Height}"" Width=""*"" />
        <DataGridTextColumn Header=""Rebar Layout"" Binding=""{Binding Rebar}"" Width=""1.5*"" />
    </DataGrid.Columns>
</DataGrid>");

        var checkColumnStyle = (System.Windows.Style)App.Current.Resources["CONCOST.DataGrid.CheckBox"];

        // ==============================================================================?
        // SECTION 2: Interactive CheckBox & Selection Columns
        // ==============================================================================?
        var dg2 = new DataGrid { ItemsSource = sampleBeams, Height = 210 };
        dg2.Columns.Add(new DataGridCheckBoxColumn
        {
            Header = "Select",
            Binding = new System.Windows.Data.Binding("IsSelected") { Mode = System.Windows.Data.BindingMode.TwoWay },
            Width = new DataGridLength(65),
            ElementStyle = checkColumnStyle,
            EditingElementStyle = checkColumnStyle
        });
        dg2.Columns.Add(new DataGridTextColumn { Header = "Element", Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(2, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg2.Columns.Add(new DataGridTextColumn { Header = "Length L (mm)", Binding = new System.Windows.Data.Binding("Length"), Width = new DataGridLength(1.2, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg2.Columns.Add(new DataGridTextColumn { Header = "Rebar Layout", Binding = new System.Windows.Data.Binding("Rebar"), Width = new DataGridLength(1.5, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });

        AddCardSection("2. Interactive CheckBox & Selection Columns", dg2,
@"<!-- DataGrid with Interactive CheckBox Column -->
<DataGrid ItemsSource=""{Binding BeamList}"" Height=""210"">
    <DataGrid.Columns>
        <DataGridCheckBoxColumn Header=""Select""
                                ElementStyle=""{StaticResource CONCOST.DataGrid.CheckBox}""
                                EditingElementStyle=""{StaticResource CONCOST.DataGrid.CheckBox}""
                                Binding=""{Binding IsSelected, Mode=TwoWay}"" Width=""65"" />
        <DataGridTextColumn Header=""Element"" Binding=""{Binding Name}"" Width=""2*"" />
        <DataGridTextColumn Header=""Length L (mm)"" Binding=""{Binding Length}"" Width=""1.2*"" />
        <DataGridTextColumn Header=""Rebar Layout"" Binding=""{Binding Rebar}"" Width=""1.5*"" />
    </DataGrid.Columns>
</DataGrid>");

        // ==============================================================================?
        // SECTION 3: Seamless Continuous Rows with Center Alignment
        // ==============================================================================?
        var dg3 = new DataGrid { ItemsSource = sampleBeams, Height = 190 };
        dg3.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.DataGrid.Seamless");
        CONCOST.UI.AttachedProperties.DataGridElement.SetHeaderHorizontalContentAlignment(dg3, System.Windows.HorizontalAlignment.Center);
        CONCOST.UI.AttachedProperties.DataGridElement.SetCellHorizontalContentAlignment(dg3, System.Windows.HorizontalAlignment.Center);
        dg3.Columns.Add(new DataGridTextColumn { Header = "Element Name", Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(2, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg3.Columns.Add(new DataGridTextColumn { Header = "Width b (mm)", Binding = new System.Windows.Data.Binding("Width"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg3.Columns.Add(new DataGridTextColumn { Header = "Depth h (mm)", Binding = new System.Windows.Data.Binding("Height"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });
        dg3.Columns.Add(new DataGridTextColumn { Header = "Rebar Layout", Binding = new System.Windows.Data.Binding("Rebar"), Width = new DataGridLength(1.5, DataGridLengthUnitType.Star), EditingElementStyle = editTextBoxStyle });

        AddCardSection("3. Seamless Style (Center-Aligned Header & Cells via Attached Properties)", dg3,
@"<!-- Center-Aligned Header & Cells via DataGridElement Attached Properties -->
<DataGrid Style=""{StaticResource CONCOST.DataGrid.Seamless}""
          attached:DataGridElement.HeaderHorizontalContentAlignment=""Center""
          attached:DataGridElement.CellHorizontalContentAlignment=""Center""
          ItemsSource=""{Binding BeamList}"" Height=""190"">
    <DataGrid.Columns>
        <DataGridTextColumn Header=""Element Name"" Binding=""{Binding Name}"" Width=""2*"" />
        <DataGridTextColumn Header=""Width b (mm)"" Binding=""{Binding Width}"" Width=""*"" />
        <DataGridTextColumn Header=""Depth h (mm)"" Binding=""{Binding Height}"" Width=""*"" />
        <DataGridTextColumn Header=""Rebar Layout"" Binding=""{Binding Rebar}"" Width=""1.5*"" />
    </DataGrid.Columns>
</DataGrid>");

        // ==============================================================================?
        // SECTION 4: Small & Compact Dense Styles
        // ==============================================================================?
        var dg4 = new DataGrid { ItemsSource = sampleBeams, Height = 160 };
        dg4.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.DataGrid.Small");
        dg4.Columns.Add(new DataGridTextColumn { Header = "Element Name", Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(2, DataGridLengthUnitType.Star) });
        dg4.Columns.Add(new DataGridTextColumn { Header = "Width (mm)", Binding = new System.Windows.Data.Binding("Width"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
        dg4.Columns.Add(new DataGridTextColumn { Header = "Depth (mm)", Binding = new System.Windows.Data.Binding("Height"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
        dg4.Columns.Add(new DataGridTextColumn { Header = "Rebar Layout", Binding = new System.Windows.Data.Binding("Rebar"), Width = new DataGridLength(1.5, DataGridLengthUnitType.Star) });

        AddCardSection("4. Small Dense Style (28px Row Height)", dg4,
@"<!-- Small Dense DataGrid -->
<DataGrid Style=""{StaticResource CONCOST.DataGrid.Small}"" ItemsSource=""{Binding BeamList}"" Height=""160"">
    <DataGrid.Columns>
        <DataGridTextColumn Header=""Element Name"" Binding=""{Binding Name}"" Width=""2*"" />
        <DataGridTextColumn Header=""Width (mm)"" Binding=""{Binding Width}"" Width=""*"" />
        <DataGridTextColumn Header=""Depth (mm)"" Binding=""{Binding Height}"" Width=""*"" />
        <DataGridTextColumn Header=""Rebar Layout"" Binding=""{Binding Rebar}"" Width=""1.5*"" />
    </DataGrid.Columns>
</DataGrid>");

        // ==============================================================================?
        // SECTION 5: Multi-Level Hierarchical Header DataGrid (Tree-Based N-Level)
        // ==============================================================================?
        var sampleStories = new ObservableCollection<StoryMeasurementItem>
        {
            new StoryMeasurementItem { Index = 1, L1 = 5000, W1 = 3000, L2 = 4500, W2 = 2800 },
            new StoryMeasurementItem { Index = 2, L1 = 6000, W1 = 3500, L2 = 5500, W2 = 3200 },
            new StoryMeasurementItem { Index = 3, L1 = 4800, W1 = 2900, L2 = 4200, W2 = 2600 },
            new StoryMeasurementItem { Index = 4, L1 = 7200, W1 = 4000, L2 = 6800, W2 = 3800 }
        };

        var dg5 = new CONCOST.UI.Controls.StackedHeaderDataGrid
        {
            ItemsSource = sampleStories,
            Height = 220,
            StackedRowHeight = 34,
            CanUserSortColumns = true,
            CanUserResizeColumns = true
        };
        dg5.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.StackedHeaderDataGrid.Base");
        CONCOST.UI.AttachedProperties.DataGridElement.SetCellHorizontalContentAlignment(dg5, System.Windows.HorizontalAlignment.Center);

        // Tree-based Header API
        // Structure:
        // +-------+-----------------------+-----------------------+
        // |  No.  |        LEVEL 1        |        LEVEL 2        |
        // |       +-----------+-----------+-----------+-----------+
