        AddCardSection("5. Multi-Level Hierarchical Header DataGrid (Tree-Based with Footer Aggregates)", dg5,
@"<!-- Multi-Level Header DataGrid (Tree-Based with Footer Sum / Average Summary) -->
<controls:StackedHeaderDataGrid ItemsSource=""{Binding StoryList}""
                                Height=""230"" StackedRowHeight=""34""
                                ShowFooterSummary=""True"" FooterRowHeight=""30""
                                CanUserSortColumns=""True"" CanUserResizeColumns=""True"">
    <!-- Header Tree: ColumnGroup = group node (colSpan), ColumnLeaf = leaf column (data binding) -->
    <controls:StackedHeaderDataGrid.ColumnHeaderTree>

        <!-- Standalone leaf with Custom Footer Text -->
        <controls:ColumnLeaf HeaderText=""No."" BindingPath=""Index"" Width=""70"" CustomAggregateText=""Total / Avg"" />

        <!-- Group 1 with Sum and Average Aggregates in Footer -->
        <controls:ColumnGroup HeaderText=""LEVEL 1"">
            <controls:ColumnLeaf HeaderText=""Length (mm)"" BindingPath=""L1"" Width=""*"" AggregateType=""Sum"" />
            <controls:ColumnLeaf HeaderText=""Width (mm)"" BindingPath=""W1"" Width=""*"" AggregateType=""Average"" />
        </controls:ColumnGroup>

        <!-- Group 2 with Sum and Average Aggregates in Footer -->
        <controls:ColumnGroup HeaderText=""LEVEL 2"">
