        dgBench.ColumnHeaderTree.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "ID", BindingPath = "Id", Width = new DataGridLength(80), CustomAggregateText = "Summary", CanUserSort = true });
        dgBench.ColumnHeaderTree.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Element Code", BindingPath = "ElementCode", Width = new DataGridLength(1.8, DataGridLengthUnitType.Star), AggregateType = CONCOST.UI.Controls.AggregateType.Count, CanUserSort = true });

        var grpDims = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "SECTION GEOMETRY" };
        grpDims.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Width (mm)", BindingPath = "Width", CellType = CONCOST.UI.Controls.CellType.Numeric, Width = new DataGridLength(110), AggregateType = CONCOST.UI.Controls.AggregateType.Average, CanUserSort = true });
        grpDims.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Depth (mm)", BindingPath = "Height", CellType = CONCOST.UI.Controls.CellType.Numeric, Width = new DataGridLength(110), AggregateType = CONCOST.UI.Controls.AggregateType.Average, CanUserSort = true });
        grpDims.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Length (mm)", BindingPath = "Length", CellType = CONCOST.UI.Controls.CellType.Numeric, Width = new DataGridLength(110), AggregateType = CONCOST.UI.Controls.AggregateType.Average, CanUserSort = true });
        dgBench.ColumnHeaderTree.Add(grpDims);

        var grpProgressBench = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "STATUS & QUALITY" };
        grpProgressBench.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Progress", BindingPath = "Progress", CellType = CONCOST.UI.Controls.CellType.Progress, Width = new DataGridLength(130), AggregateType = CONCOST.UI.Controls.AggregateType.Average, CanUserSort = true });
        grpProgressBench.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Status", BindingPath = "Status", CellType = CONCOST.UI.Controls.CellType.Badge, Width = new DataGridLength(110), CanUserSort = true });
        grpProgressBench.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Rating", BindingPath = "Rating", CellType = CONCOST.UI.Controls.CellType.Rating, Width = new DataGridLength(110), AggregateType = CONCOST.UI.Controls.AggregateType.Average, CanUserSort = true });
        dgBench.ColumnHeaderTree.Add(grpProgressBench);

        var grpCost = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "ESTIMATION & COST" };
        grpCost.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Rebar Weight (kg)", BindingPath = "RebarWeight", CellType = CONCOST.UI.Controls.CellType.Numeric, StringFormat = "N1", Width = new DataGridLength(140), AggregateType = CONCOST.UI.Controls.AggregateType.Sum, CanUserSort = true });
        grpCost.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Cost ($)", BindingPath = "TotalCost", CellType = CONCOST.UI.Controls.CellType.Numeric, StringFormat = "N0", HorizontalAlignment = System.Windows.HorizontalAlignment.Right, Width = new DataGridLength(150), AggregateType = CONCOST.UI.Controls.AggregateType.Sum, CanUserSort = true });
        dgBench.ColumnHeaderTree.Add(grpCost);

        ObservableCollection<BenchmarkGridItem> benchDataset = new();

        void LoadData(int count)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            var list = new List<BenchmarkGridItem>(count);
            var statuses = new[] { "Approved", "In Progress", "In Review", "Pending", "Draft" };
            var random = new Random(42);

            for (int i = 1; i <= count; i++)
            {
                list.Add(new BenchmarkGridItem
                {
                    Id = i,
                    ElementCode = $"BM-FL{((i % 20) + 1):D2}-D{i:D4}",
                    Width = 200 + (random.Next(0, 5) * 50),
                    Height = 350 + (random.Next(0, 7) * 50),
                    Length = 3000 + (random.Next(0, 10) * 500),
                    Progress = random.Next(0, 101),
                    Status = statuses[random.Next(statuses.Length)],
                    Rating = random.Next(1, 6),
                    RebarWeight = Math.Round(250 + random.NextDouble() * 1200, 1),
                    TotalCost = random.Next(15, 180) * 1_000_000
                });
            }
            sw.Stop();
            long genMs = sw.ElapsedMilliseconds;

            sw.Restart();
            benchDataset = new ObservableCollection<BenchmarkGridItem>(list);
            dgBench.ItemsSource = benchDataset;
            dgBench.RebuildFooterSummary();
            sw.Stop();
            long bindMs = sw.ElapsedMilliseconds;

            long memoryMb = GC.GetTotalMemory(false) / (1024 * 1024);
            lblRowCount.Text = $"Records: {count:N0}";
            lblGenTime.Text = $"Gen: {genMs} ms";
            lblBindTime.Text = $"Bind/Render: {bindMs} ms";
            lblMemory.Text = $"Heap RAM: ~{memoryMb} MB";
        }

        // Action Buttons
        var btn1k = new Button { Content = "Load 1,000 Rows", Style = (System.Windows.Style)App.Current.Resources["CONCOST.Button.Secondary"], Margin = new System.Windows.Thickness(0, 0, 8, 8) };
        btn1k.Click += (s, e) => LoadData(1_000);

        var btn10k = new Button { Content = "Load 10,000 Rows", Style = (System.Windows.Style)App.Current.Resources["CONCOST.Button.Secondary"], Margin = new System.Windows.Thickness(0, 0, 8, 8) };
        btn10k.Click += (s, e) => LoadData(10_000);

        var btn50k = new Button { Content = "Load 50,000 Rows", Style = (System.Windows.Style)App.Current.Resources["CONCOST.Button.Primary"], Margin = new System.Windows.Thickness(0, 0, 8, 8) };
        btn50k.Click += (s, e) => LoadData(50_000);

        var btn100k = new Button { Content = "Load 100,000 Rows", Style = (System.Windows.Style)App.Current.Resources["CONCOST.Button.Danger"], Margin = new System.Windows.Thickness(0, 0, 8, 8) };
        btn100k.Click += (s, e) => LoadData(100_000);

        var btnGc = new Button { Content = "Force GC (RAM Clean)", Style = (System.Windows.Style)App.Current.Resources["CONCOST.Button.Secondary"], Margin = new System.Windows.Thickness(0, 0, 8, 8) };
        btnGc.Click += (s, e) =>
        {
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            long memoryMb = GC.GetTotalMemory(true) / (1024 * 1024);
            lblMemory.Text = $"Heap RAM: ~{memoryMb} MB";
        };

        // Realtime Streaming Simulator
        System.Windows.Threading.DispatcherTimer? liveTimer = null;
        var tglStream = new System.Windows.Controls.Primitives.ToggleButton
        {
            Content = "▶ Start Real-time Stream (50 records/s)",
            Style = (System.Windows.Style)App.Current.Resources["CONCOST.ToggleButton.Success"],
            Margin = new System.Windows.Thickness(0, 0, 8, 8),
            Width = 270
        };

        tglStream.Checked += (s, e) =>
        {
            if (benchDataset.Count == 0) LoadData(1000);
            tglStream.Content = "⏹ Streaming Real-time (50 records/s)";
            var rnd = new Random();
            liveTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(20) };
            liveTimer.Tick += (ts, te) =>
            {
                if (benchDataset.Count > 0)
                {
                    int idx = rnd.Next(0, Math.Min(100, benchDataset.Count));
                    benchDataset[idx].Progress = (benchDataset[idx].Progress + 5) % 101;
                    benchDataset[idx].RebarWeight = Math.Round(benchDataset[idx].RebarWeight + 0.5, 1);
                }
            };
            liveTimer.Start();
        };

        tglStream.Unchecked += (s, e) =>
        {
            liveTimer?.Stop();
            tglStream.Content = "▶ Start Real-time Stream (50 records/s)";
        };

        actionWrap.Children.Add(btn1k);
        actionWrap.Children.Add(btn10k);
        actionWrap.Children.Add(btn50k);
        actionWrap.Children.Add(btn100k);
        actionWrap.Children.Add(btnGc);
        actionWrap.Children.Add(tglStream);

        benchmarkPanel.Children.Add(actionWrap);
        benchmarkPanel.Children.Add(dgBench);

        // Load 1,000 rows initially for display
        LoadData(1000);

        AddCardSection("9. Big Data Stress Test & Real-Time Performance Benchmarking (1K -> 100K Rows)", benchmarkPanel,
@"<!-- Big Data High-Performance StackedHeaderDataGrid (1K - 100K Rows) -->
<controls:StackedHeaderDataGrid ItemsSource=""{Binding BigDataset}""
                                Height=""360"" StackedRowHeight=""34""
                                ShowFooterSummary=""True"" FooterRowHeight=""30""
                                CanUserSortColumns=""True"" CanUserResizeColumns=""True""
                                EnableRowVirtualization=""True"" EnableColumnVirtualization=""True""
                                VirtualizingPanel.IsVirtualizingWhenGrouping=""True""
                                VirtualizingPanel.VirtualizationMode=""Recycling""
                                VirtualizingPanel.ScrollUnit=""Pixel"">
    <controls:StackedHeaderDataGrid.ColumnHeaderTree>
        <controls:ColumnLeaf HeaderText=""ID"" BindingPath=""Id"" Width=""80"" CustomAggregateText=""Summary"" />
        <controls:ColumnLeaf HeaderText=""Element Code"" BindingPath=""ElementCode"" Width=""1.8*"" AggregateType=""Count"" />
        
        <controls:ColumnGroup HeaderText=""SECTION GEOMETRY"">
            <controls:ColumnLeaf HeaderText=""Width (mm)"" BindingPath=""Width"" CellType=""Numeric"" Width=""110"" AggregateType=""Average"" />
            <controls:ColumnLeaf HeaderText=""Depth (mm)"" BindingPath=""Height"" CellType=""Numeric"" Width=""110"" AggregateType=""Average"" />
            <controls:ColumnLeaf HeaderText=""Length (mm)"" BindingPath=""Length"" CellType=""Numeric"" Width=""110"" AggregateType=""Average"" />
        </controls:ColumnGroup>

        <controls:ColumnGroup HeaderText=""STATUS &amp; QUALITY"">
            <controls:ColumnLeaf HeaderText=""Progress"" BindingPath=""Progress"" CellType=""Progress"" Width=""130"" AggregateType=""Average"" />
            <controls:ColumnLeaf HeaderText=""Status"" BindingPath=""Status"" CellType=""Badge"" Width=""110"" />
            <controls:ColumnLeaf HeaderText=""Rating"" BindingPath=""Rating"" CellType=""Rating"" Width=""110"" AggregateType=""Average"" />
        </controls:ColumnGroup>

        <controls:ColumnGroup HeaderText=""ESTIMATION &amp; COST"">
            <controls:ColumnLeaf HeaderText=""Rebar Weight (kg)"" BindingPath=""RebarWeight"" CellType=""Numeric"" StringFormat=""N1"" Width=""140"" AggregateType=""Sum"" />
            <controls:ColumnLeaf HeaderText=""Cost ($)"" BindingPath=""TotalCost"" CellType=""Numeric"" StringFormat=""N0"" Width=""150"" AggregateType=""Sum"" />
        </controls:ColumnGroup>
    </controls:StackedHeaderDataGrid.ColumnHeaderTree>
</controls:StackedHeaderDataGrid>");

        return mainSp;
    }


    private object CreateRepeatButtonDemo()
    {
        var sp = new StackPanel { Margin = new System.Windows.Thickness(10) };
        sp.Children.Add(new TextBlock { Text = "1. Normal Active State (Press & Hold for Continuous Repeat):", FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 8), Foreground = (Brush)App.Current.Resources["CONCOST.Brush.TextSecondary"] });
        var wp1 = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 16) };
        wp1.Children.Add(new System.Windows.Controls.Primitives.RepeatButton { Content = "Increment (+10)", Margin = new System.Windows.Thickness(0, 0, 10, 0) });
        wp1.Children.Add(new System.Windows.Controls.Primitives.RepeatButton { Content = "Decrement (-10)" });
        sp.Children.Add(wp1);

        sp.Children.Add(new TextBlock { Text = "2. Disabled State:", FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 8), Foreground = (Brush)App.Current.Resources["CONCOST.Brush.TextSecondary"] });
        var wp2 = new WrapPanel { Orientation = Orientation.Horizontal };
        wp2.Children.Add(new System.Windows.Controls.Primitives.RepeatButton { Content = "Increment (+10)", IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 10, 0) });
        wp2.Children.Add(new System.Windows.Controls.Primitives.RepeatButton { Content = "Decrement (-10)", IsEnabled = false });
        sp.Children.Add(wp2);
        return sp;
    }

    private object CreateToggleButtonDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                // Top Header Bar
                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML Code Example",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Standard & Semantic Toggle Buttons
        var semPanel = new StackPanel();
        var semWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var semDisWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var semOptions = new[] {
            ("Active", true, "CONCOST.ToggleButton.Base"),
            ("Inactive", false, "CONCOST.ToggleButton.Base"),
            ("Success", true, "CONCOST.ToggleButton.Success"),
            ("Outline On", true, "CONCOST.ToggleButton.Outline"),
            ("Outline Off", false, "CONCOST.ToggleButton.Outline")
        };

        foreach (var (lbl, isChecked, styleKey) in semOptions)
        {
            var btn = new System.Windows.Controls.Primitives.ToggleButton
            {
                Content = lbl,
                IsChecked = isChecked,
                Style = (System.Windows.Style)App.Current.Resources[styleKey],
