        semPanel.Children.Add(new TextBlock { Text = "Enabled States (Checked & Unchecked):", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        semPanel.Children.Add(semWp);
        semPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        semPanel.Children.Add(semDisWp);

        string semXaml =
@"<ToggleButton Content=""Active"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Base}"" Width=""120"" />
<ToggleButton Content=""Inactive"" IsChecked=""False"" Style=""{DynamicResource CONCOST.ToggleButton.Base}"" Width=""120"" />
<ToggleButton Content=""Success"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Success}"" Width=""120"" />
<ToggleButton Content=""Outline On"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Outline}"" Width=""120"" />
<ToggleButton Content=""Outline Off"" IsChecked=""False"" Style=""{DynamicResource CONCOST.ToggleButton.Outline}"" Width=""120"" />";

        AddCardSection("1. Semantic & Appearance Variations", semPanel, semXaml);

        // Section 2: Action Toggle Buttons with Vector Icons
        var iconPanel = new StackPanel();
        var iconWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var iconDisWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var iconOptions = new[] {
