        iconPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        iconPanel.Children.Add(iconDisWp);

        string iconActionXaml =
@"<ToggleButton Content=""Snapping"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Base}"" attached:IconElement.Kind=""Ruler"" Width=""140"" />
<ToggleButton Content=""Lock Layer"" IsChecked=""False"" Style=""{DynamicResource CONCOST.ToggleButton.Base}"" attached:IconElement.Kind=""Lock"" Width=""140"" />
<ToggleButton Content=""Auto Calc"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Success}"" attached:IconElement.Kind=""Check"" Width=""140"" />
<ToggleButton Content=""Filter"" IsChecked=""True"" Style=""{DynamicResource CONCOST.ToggleButton.Base}"" attached:IconElement.Kind=""Filter"" Width=""140"" />
<ToggleButton Content=""Bookmark"" IsChecked=""False"" Style=""{DynamicResource CONCOST.ToggleButton.Outline}"" attached:IconElement.Kind=""Layers"" Width=""140"" />";

        AddCardSection("2. Action Toggle Buttons with Vector Icons", iconPanel, iconActionXaml);

        // Section 3: Icon-Only Buttons (Square, Circle, Outline, Success, Ghost)
        var iconOnlyPanel = new StackPanel();
        var iconOnlyWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var iconOnlyDisWp = new WrapPanel { Orientation = Orientation.Horizontal };

        var iconOnlyOptions = new[] {
