            (IconKind.Filter, "CONCOST.ToggleButton.Icon.Circle", true, "Circle Filter (Active)"),
            (IconKind.Layers, "CONCOST.ToggleButton.Icon.Circle", false, "Circle Layers (Inactive)"),
            (IconKind.BookmarkItem, "CONCOST.ToggleButton.Icon.Outline", true, "Outline Bookmark (Active)"),
            (IconKind.Check, "CONCOST.ToggleButton.Icon.Success", true, "Success Check (Active)"),
            (IconKind.Eye, "CONCOST.ToggleButton.Icon.Ghost", true, "Ghost Visibility (Active)"),
            (IconKind.EyeOff, "CONCOST.ToggleButton.Icon.Ghost", false, "Ghost Visibility (Inactive)")
        };

        foreach (var (icon, styleKey, isChecked, tooltip) in iconOnlyOptions)
        {
            var btn = new System.Windows.Controls.Primitives.ToggleButton
            {
                Style = (System.Windows.Style)App.Current.Resources[styleKey],
                IsChecked = isChecked,
                ToolTip = tooltip,
                Margin = new System.Windows.Thickness(0, 0, 12, 8)
            };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btn, icon);
            iconOnlyWp.Children.Add(btn);

            var btnDis = new System.Windows.Controls.Primitives.ToggleButton
            {
                Style = (System.Windows.Style)App.Current.Resources[styleKey],
                IsChecked = isChecked,
                ToolTip = tooltip,
                Margin = new System.Windows.Thickness(0, 0, 12, 8),
                IsEnabled = false
            };
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btnDis, icon);
            iconOnlyDisWp.Children.Add(btnDis);
        }

        iconOnlyPanel.Children.Add(new TextBlock { Text = "Enabled States (Square 34px, Circle, Outline, Success, Ghost):", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        iconOnlyPanel.Children.Add(iconOnlyWp);
        iconOnlyPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        iconOnlyPanel.Children.Add(iconOnlyDisWp);

        string iconOnlyToggleXaml =
@"<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon}"" IsChecked=""True"" attached:IconElement.Kind=""Lock"" ToolTip=""Lock Viewport"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon}"" IsChecked=""False"" attached:IconElement.Kind=""Unlock"" ToolTip=""Unlock Viewport"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Circle}"" IsChecked=""True"" attached:IconElement.Kind=""Filter"" ToolTip=""Filter Elements"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Circle}"" IsChecked=""False"" attached:IconElement.Kind=""Layers"" ToolTip=""Layers Palette"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Outline}"" IsChecked=""True"" attached:IconElement.Kind=""BookmarkItem"" ToolTip=""Bookmark State"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Success}"" IsChecked=""True"" attached:IconElement.Kind=""Check"" ToolTip=""Confirm Selection"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Ghost}"" IsChecked=""True"" attached:IconElement.Kind=""Eye"" ToolTip=""Toggle Visibility"" />
<ToggleButton Style=""{DynamicResource CONCOST.ToggleButton.Icon.Ghost}"" IsChecked=""False"" attached:IconElement.Kind=""EyeOff"" ToolTip=""Toggle Visibility"" />";

        AddCardSection("3. Icon-Only Toggle Buttons", iconOnlyPanel, iconOnlyToggleXaml);

        // Section 4: Modern Segmented Toolbar Groups (CAD & Modeling Control)
        var segmentedPanel = new StackPanel();
        var segRow = new WrapPanel { Orientation = Orientation.Horizontal };

        // Group 1: Text Alignment / Direction
        var group1 = new Border
        {
            CornerRadius = new System.Windows.CornerRadius(8),
            BorderThickness = new System.Windows.Thickness(1),
            Padding = new System.Windows.Thickness(4),
            Margin = new System.Windows.Thickness(0, 0, 16, 8)
        };
        group1.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        group1.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var segSp1 = new StackPanel { Orientation = Orientation.Horizontal };
        var alignItems = new[] { ("Align Left", IconKind.ArrowLeft, true), ("Align Center", IconKind.Menu, false), ("Align Right", IconKind.ArrowRight, false) };
        foreach (var (lbl, icon, isChecked) in alignItems)
        {
            var btn = new System.Windows.Controls.Primitives.ToggleButton
            {
                Content = lbl,
                IsChecked = isChecked,
                Padding = new System.Windows.Thickness(12, 5, 12, 5),
                BorderThickness = new System.Windows.Thickness(0),
                Margin = new System.Windows.Thickness(2, 0, 2, 0)
            };
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(btn, new System.Windows.CornerRadius(6));
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btn, icon);
            segSp1.Children.Add(btn);
        }
        group1.Child = segSp1;
        segRow.Children.Add(group1);

        // Group 2: Viewport Mode Group (2D / 3D / Section)
        var group2 = new Border
        {
            CornerRadius = new System.Windows.CornerRadius(8),
            BorderThickness = new System.Windows.Thickness(1),
            Padding = new System.Windows.Thickness(4),
            Margin = new System.Windows.Thickness(0, 0, 16, 8)
        };
        group2.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        group2.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var segSp2 = new StackPanel { Orientation = Orientation.Horizontal };
        var viewItems = new[] { ("2D Plan", IconKind.Layers, false), ("3D Model", IconKind.Eye, true), ("Cross Section", IconKind.Ruler, false) };
        foreach (var (lbl, icon, isChecked) in viewItems)
        {
            var btn = new System.Windows.Controls.Primitives.ToggleButton
            {
                Content = lbl,
                IsChecked = isChecked,
                Padding = new System.Windows.Thickness(14, 5, 14, 5),
                BorderThickness = new System.Windows.Thickness(0),
                Margin = new System.Windows.Thickness(2, 0, 2, 0)
            };
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(btn, new System.Windows.CornerRadius(6));
            CONCOST.UI.AttachedProperties.IconElement.SetKind(btn, icon);
            segSp2.Children.Add(btn);
        }
        group2.Child = segSp2;
        segRow.Children.Add(group2);

        segmentedPanel.Children.Add(segRow);

        string segXaml =
@"<!-- Segmented Toolbar Group (Single-line Compact Format) -->
<Border Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"" BorderBrush=""{DynamicResource CONCOST.Brush.Border}"" BorderThickness=""1"" CornerRadius=""8"" Padding=""4"">
    <StackPanel Orientation=""Horizontal"">
        <ToggleButton Content=""Align Left"" IsChecked=""True"" BorderThickness=""0"" attached:IconElement.Kind=""ArrowLeft"" />
        <ToggleButton Content=""Align Center"" IsChecked=""False"" BorderThickness=""0"" attached:IconElement.Kind=""Menu"" />
        <ToggleButton Content=""Align Right"" IsChecked=""False"" BorderThickness=""0"" attached:IconElement.Kind=""ArrowRight"" />
    </StackPanel>
</Border>";

        AddCardSection("4. Segmented Toolbar Groups", segmentedPanel, segXaml);

        return mainSp;
    }

    private object CreateRadioButtonDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrWhiteSpace(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tagIcon = new CONCOST.UI.Icons.Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock { Text = "XAML Code Example", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);
                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border { Height = 1, Margin = new System.Windows.Thickness(0) };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Standard Traditional RadioButtons
        var stdPanel = new StackPanel();
        var stdEnabledWp = new StackPanel { Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        stdEnabledWp.Children.Add(new RadioButton { GroupName = "DesignStandard1", Content = "TCVN 5574:2018 (Vietnam Standard - Reinforced Concrete)", IsChecked = true, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        stdEnabledWp.Children.Add(new RadioButton { GroupName = "DesignStandard1", Content = "ACI 318-19 (American Concrete Institute)", Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        stdEnabledWp.Children.Add(new RadioButton { GroupName = "DesignStandard1", Content = "Eurocode 2: EN 1992-1-1 (Design of Concrete Structures)", Margin = new System.Windows.Thickness(0, 0, 0, 0) });

        var stdDisabledWp = new StackPanel();
        stdDisabledWp.Children.Add(new RadioButton { GroupName = "DesignStandardDis", Content = "TCVN 5574:2018 (Vietnam Standard - Reinforced Concrete)", IsChecked = true, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        stdDisabledWp.Children.Add(new RadioButton { GroupName = "DesignStandardDis", Content = "ACI 318-19 (American Concrete Institute)", IsChecked = false, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        stdDisabledWp.Children.Add(new RadioButton { GroupName = "DesignStandardDis", Content = "Eurocode 2: EN 1992-1-1 (Design of Concrete Structures)", IsChecked = false, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 0, 0) });

        stdPanel.Children.Add(new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        stdPanel.Children.Add(stdEnabledWp);
        stdPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 10, 0, 8) });
        stdPanel.Children.Add(stdDisabledWp);

        string stdXaml =
@"<RadioButton GroupName=""DesignStandard"" Content=""TCVN 5574:2018 (Vietnam Standard - Reinforced Concrete)"" IsChecked=""True"" />
<RadioButton GroupName=""DesignStandard"" Content=""ACI 318-19 (American Concrete Institute)"" />
<RadioButton GroupName=""DesignStandard"" Content=""Eurocode 2: EN 1992-1-1 (Design of Concrete Structures)"" />";

        AddCardSection("1. Standard Traditional RadioButtons", stdPanel, stdXaml);

        // Section 2: Button-Like Radio Cards with Indicator Bar (Solid & Outline)
        var cardPanel = new StackPanel();
        var cardEnabledWp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        var cardDisabledWp = new WrapPanel { Orientation = Orientation.Horizontal };

        // Enabled States
        var rBtn1 = new RadioButton { GroupName = "CardGroup", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button"], IsChecked = true, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(rBtn1, IconKind.Calendar);
        cardEnabledWp.Children.Add(rBtn1);

        var rBtn2 = new RadioButton { GroupName = "CardGroup", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button"], IsChecked = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 130 };
        cardEnabledWp.Children.Add(rBtn2);

        var rBtn3 = new RadioButton { GroupName = "CardGroup", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button.Outline"], IsChecked = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(rBtn3, IconKind.Calendar);
        cardEnabledWp.Children.Add(rBtn3);

        var rBtn4 = new RadioButton { GroupName = "CardGroup", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button.Outline"], IsChecked = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 130 };
        cardEnabledWp.Children.Add(rBtn4);

        // Disabled States
        var rBtnDis1 = new RadioButton { GroupName = "CardGroupDis", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button"], IsChecked = true, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(rBtnDis1, IconKind.Calendar);
        cardDisabledWp.Children.Add(rBtnDis1);

        var rBtnDis2 = new RadioButton { GroupName = "CardGroupDis", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button"], IsChecked = false, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 130 };
        cardDisabledWp.Children.Add(rBtnDis2);

        var rBtnDis3 = new RadioButton { GroupName = "CardGroupDis", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button.Outline"], IsChecked = false, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 140 };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(rBtnDis3, IconKind.Calendar);
        cardDisabledWp.Children.Add(rBtnDis3);

        var rBtnDis4 = new RadioButton { GroupName = "CardGroupDis", Content = "RadioButton", Style = (System.Windows.Style)App.Current.Resources["CONCOST.RadioButton.Button.Outline"], IsChecked = false, IsEnabled = false, Margin = new System.Windows.Thickness(0, 0, 12, 8), Width = 130 };
        cardDisabledWp.Children.Add(rBtnDis4);

        cardPanel.Children.Add(new TextBlock { Text = "Enabled States (Checked & Unchecked):", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        cardPanel.Children.Add(cardEnabledWp);
        cardPanel.Children.Add(new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 8, 0, 8) });
        cardPanel.Children.Add(cardDisabledWp);

        string cardXaml =
@"<RadioButton GroupName=""CardGroup"" Content=""RadioButton"" Style=""{DynamicResource CONCOST.RadioButton.Button}"" attached:IconElement.Kind=""Calendar"" IsChecked=""True"" Width=""140"" />
<RadioButton GroupName=""CardGroup"" Content=""RadioButton"" Style=""{DynamicResource CONCOST.RadioButton.Button}"" Width=""130"" />
<RadioButton GroupName=""CardGroup"" Content=""RadioButton"" Style=""{DynamicResource CONCOST.RadioButton.Button.Outline}"" attached:IconElement.Kind=""Calendar"" Width=""140"" />
<RadioButton GroupName=""CardGroup"" Content=""RadioButton"" Style=""{DynamicResource CONCOST.RadioButton.Button.Outline}"" Width=""130"" />";

        AddCardSection("2. Button-Like Radio Cards with Indicator Bar (Custom Appearance)", cardPanel, cardXaml);

        return mainSp;
