        navButtons1.Children.Add(btn75);
        navButtons1.Children.Add(btnBottom);
        Grid.SetColumn(navButtons1, 0);
        navBar1.Children.Add(navButtons1);

        var offsetLabel1 = new TextBlock
        {
            Text = "Offset: 0.0 px (0%)",
