            HorizontalAlignment = System.Windows.HorizontalAlignment.Right
        };
        offsetLabel1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Grid.SetColumn(offsetLabel1, 1);
        navBar1.Children.Add(offsetLabel1);
        sec1.Children.Add(navBar1);

        var g1 = new Grid();
        g1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        g1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(14) });
        g1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var sv1Border = new Border { Height = 220, CornerRadius = new System.Windows.CornerRadius(8), BorderThickness = new System.Windows.Thickness(1), Padding = new System.Windows.Thickness(12) };
        sv1Border.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sv1Border.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sv1 = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
        };
        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetIsInertiaEnabled(sv1, true);
        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetBubbleAtBoundary(sv1, true);

        var sp1 = new StackPanel();
        for (int i = 1; i <= 25; i++)
        {
            var rowCard = new Border
            {
                Padding = new System.Windows.Thickness(10, 8, 10, 8),
                Margin = new System.Windows.Thickness(0, 0, 0, 6),
                CornerRadius = new System.Windows.CornerRadius(6),
                BorderThickness = new System.Windows.Thickness(1)
            };
            rowCard.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            rowCard.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var rowGrid = new Grid();
