            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var tagBadge = new Border { CornerRadius = new System.Windows.CornerRadius(4), Padding = new System.Windows.Thickness(6, 2, 6, 2), Margin = new System.Windows.Thickness(0, 0, 10, 0), MinWidth = 36 };
            tagBadge.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Primary");
            var tagText = new TextBlock { Text = $"B{i:D2}", FontSize = 11, FontWeight = System.Windows.FontWeights.Normal, HorizontalAlignment = System.Windows.HorizontalAlignment.Center };
            tagText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.White");
            tagBadge.Child = tagText;
            Grid.SetColumn(tagBadge, 0);
            rowGrid.Children.Add(tagBadge);

            var infoText = new TextBlock { Text = $"Reinforced Beam  •  300 × {400 + i * 15} mm  •  L = {4.0 + i * 0.2:F1} m", FontSize = 12.5, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            infoText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(infoText, 1);
            rowGrid.Children.Add(infoText);

            var gradeText = new TextBlock { Text = "CB400V / B25", FontSize = 11.5, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            gradeText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            Grid.SetColumn(gradeText, 2);
            rowGrid.Children.Add(gradeText);

            rowCard.Child = rowGrid;
            sp1.Children.Add(rowCard);
        }
        sv1.Content = sp1;
        sv1Border.Child = sv1;
        Grid.SetColumn(sv1Border, 0);
        g1.Children.Add(sv1Border);

        sv1.ScrollChanged += (s, e) =>
        {
            double max = sv1.ScrollableHeight;
            double pct = max > 0 ? (sv1.VerticalOffset / max * 100.0) : 0;
            offsetLabel1.Text = $"Offset: {sv1.VerticalOffset:F0} px ({pct:F0}%)";
        };

        btnTop.Click += (s, e) => CONCOST.UI.AttachedProperties.ScrollViewerHelper.ScrollToTop(sv1);
        btn25.Click += (s, e) => CONCOST.UI.AttachedProperties.ScrollViewerHelper.ScrollTo(sv1, sv1.ScrollableHeight * 0.25);
        btn75.Click += (s, e) => CONCOST.UI.AttachedProperties.ScrollViewerHelper.ScrollTo(sv1, sv1.ScrollableHeight * 0.75);
        btnBottom.Click += (s, e) => CONCOST.UI.AttachedProperties.ScrollViewerHelper.ScrollToBottom(sv1);

        var sv2Border = new Border { Height = 220, CornerRadius = new System.Windows.CornerRadius(8), BorderThickness = new System.Windows.Thickness(1), Padding = new System.Windows.Thickness(12) };
        sv2Border.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sv2Border.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sv2 = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
