        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetIsInertiaEnabled(sv2, true);
        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetBubbleAtBoundary(sv2, true);

        var sp2 = new StackPanel();
        for (int i = 1; i <= 25; i++)
