            var infoText = new TextBlock { Text = $"Column Member  •  {300 + i * 20} × {300 + i * 20} mm  •  8Φ{(i % 2 == 0 ? 20 : 18)}", FontSize = 12.5, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            infoText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(infoText, 1);
