        // ====================================================================================
        // SECTION 3: Bidirectional 2D Data Grid Matrix
        // ====================================================================================
        var sec3 = new StackPanel();

        var sv2DBorder = new Border { Height = 230, CornerRadius = new System.Windows.CornerRadius(8), BorderThickness = new System.Windows.Thickness(1) };
        sv2DBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sv2DBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sv2D = new ScrollViewer
        {
            HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto
        };
        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetIsInertiaEnabled(sv2D, true);
        CONCOST.UI.AttachedProperties.ScrollViewerHelper.SetBubbleAtBoundary(sv2D, true);

        var dataGrid2D = new Grid { Margin = new System.Windows.Thickness(8) };
        string[] colHdrs = { "Element ID", "Structural Type", "Story", "Section (mm)", "Rebar Layout", "Concrete", "Axial N (kN)", "Shear Vy (kN)", "Shear Vz (kN)", "Moment Mz (kNm)" };
        foreach (var _ in colHdrs) dataGrid2D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(145) });
        dataGrid2D.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });

        for (int c = 0; c < colHdrs.Length; c++)
        {
            var hb = new Border { Padding = new System.Windows.Thickness(10, 8, 10, 8), BorderThickness = new System.Windows.Thickness(0, 0, 1, 1) };
            hb.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Primary");
            hb.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
            var ht = new TextBlock { Text = colHdrs[c], FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
            ht.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.White");
            hb.Child = ht;
            Grid.SetColumn(hb, c);
            Grid.SetRow(hb, 0);
            dataGrid2D.Children.Add(hb);
        }

        var rng2 = new Random(42);
        string[] elTypes = { "Main Beam", "Primary Column", "Two-Way Slab", "Shear Wall", "Isolated Footing" };
        for (int r = 1; r <= 16; r++)
        {
            dataGrid2D.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
            string[] rd =
            {
                $"EL-{r:D3}",
                elTypes[(r - 1) % 5],
                $"Story {(r % 4) + 1}",
                $"{250 + r * 15}×{350 + r * 20}",
                $"8Φ{(r % 2 == 0 ? 20 : 18)}",
                "C30/37 (B30)",
                $"{(rng2.NextDouble() * 300 - 150):F1}",
                $"{(rng2.NextDouble() * 80 - 40):F1}",
                $"{(rng2.NextDouble() * 80 - 40):F1}",
                $"{(rng2.NextDouble() * 150 - 75):F1}"
            };

            for (int c = 0; c < rd.Length; c++)
            {
                var cb = new Border { Padding = new System.Windows.Thickness(10, 7, 10, 7), BorderThickness = new System.Windows.Thickness(0, 0, 1, 1) };
                cb.SetResourceReference(Border.BackgroundProperty, r % 2 == 0 ? "CONCOST.Brush.Surface" : "CONCOST.Brush.SurfaceSecondary");
                cb.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
                var ct = new TextBlock { Text = rd[c], FontSize = 12 };
                ct.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                cb.Child = ct;
                Grid.SetColumn(cb, c);
                Grid.SetRow(cb, r);
                dataGrid2D.Children.Add(cb);
            }
        }

        sv2D.Content = dataGrid2D;
        sv2DBorder.Child = sv2D;
        sec3.Children.Add(sv2DBorder);

        AddCardSection("3. Bidirectional 2D Data Grid Matrix  (2-Axis Inertia · Anti-Trap Boundary Bubble)", sec3,
@"<!-- Bidirectional 2D ScrollViewer with Boundary Bubbling -->
