            var qtyText = new TextBlock { Text = $"Qty: {(i + 1) * 35:N0} m³  •  ${(i + 1) * 1250:N0}", FontSize = 12, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            qtyText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
