        var svP2Border = new Border { Height = 190, CornerRadius = new System.Windows.CornerRadius(8), BorderThickness = new System.Windows.Thickness(1), Padding = new System.Windows.Thickness(10) };
        svP2Border.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
