        s1Val1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        var s1Slider1 = new Slider { Minimum = 10, Maximum = 200, Value = 100 };
        s1Slider1.ValueChanged += (s, e) => s1Val1.Text = $"Scale / CAD Zoom: {Math.Round(e.NewValue)}%";
        s1Col1.Children.Add(s1Val1); s1Col1.Children.Add(s1Slider1);
        Grid.SetColumn(s1Col1, 0); grid1E.Children.Add(s1Col1);

        var s1Col2 = new StackPanel();
        var s1Val2 = new TextBlock { Text = "Opacity / Transparency: 75%", FontSize = 12, FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        s1Val2.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        var s1Slider2 = new Slider { Minimum = 0, Maximum = 100, Value = 75 };
        s1Slider2.ValueChanged += (s, e) => s1Val2.Text = $"Opacity / Transparency: {Math.Round(e.NewValue)}%";
        s1Col2.Children.Add(s1Val2); s1Col2.Children.Add(s1Slider2);
        Grid.SetColumn(s1Col2, 2); grid1E.Children.Add(s1Col2);
        sec1.Children.Add(grid1E);

        var lbl1D = new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl1D.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec1.Children.Add(lbl1D);

        var grid1D = new Grid();
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var s1DCol1 = new StackPanel();
        var s1DVal1 = new TextBlock { Text = "Scale / CAD Zoom (Locked): 100%", FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        s1DVal1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        var s1DSlider1 = new Slider { Minimum = 10, Maximum = 200, Value = 100, IsEnabled = false };
        s1DCol1.Children.Add(s1DVal1); s1DCol1.Children.Add(s1DSlider1);
        Grid.SetColumn(s1DCol1, 0); grid1D.Children.Add(s1DCol1);

        var s1DCol2 = new StackPanel();
        var s1DVal2 = new TextBlock { Text = "Opacity / Transparency (Locked): 50%", FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        s1DVal2.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        var s1DSlider2 = new Slider { Minimum = 0, Maximum = 100, Value = 50, IsEnabled = false };
        s1DCol2.Children.Add(s1DVal2); s1DCol2.Children.Add(s1DSlider2);
        Grid.SetColumn(s1DCol2, 2); grid1D.Children.Add(s1DCol2);
        sec1.Children.Add(grid1D);

        AddCardSection("1. Continuous Horizontal Sliders  (Standard · Auto-Fill Track)", sec1,
@"<!-- Continuous Horizontal Slider -->
<Slider Minimum=""0""
        Maximum=""100""
        Value=""75"" />

<!-- Disabled State -->
<Slider Minimum=""0""
        Maximum=""100""
        Value=""50""
        IsEnabled=""False"" />");

        // ==============================================================================?
        // SECTION 2: Discrete Sliders with Tick Marks & Snapping
        // ==============================================================================?
        var sec2 = new StackPanel();
        var lbl2E = new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl2E.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec2.Children.Add(lbl2E);

        var grid2E = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 18) };
        grid2E.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
