        g1D.Children.Add(tH1D); g1D.Children.Add(tH2D);
        sec1.Children.Add(g1D);

        AddCardSection("1. Heading Hierarchy  (H1 · H2 · H3 · H4)", sec1,
@"<TextBlock Text=""H1 Title"" Style=""{StaticResource CONCOST.TextBlock.H1}"" />
<TextBlock Text=""H2 Subtitle"" Style=""{StaticResource CONCOST.TextBlock.H2}"" />
<TextBlock Text=""H3 Section Header"" Style=""{StaticResource CONCOST.TextBlock.H3}"" />
<TextBlock Text=""H4 Component Subheading"" Style=""{StaticResource CONCOST.TextBlock.H4}"" />");

        // ==============================================================================?
        // SECTION 2: Body, Secondary & Code Typography
        // ==============================================================================?
        var sec2 = new StackPanel();
        var lbl2E = new TextBlock { Text = "Enabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl2E.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec2.Children.Add(lbl2E);

        var g2 = new StackPanel { Margin = new System.Windows.Thickness(0, 0, 0, 18) };
        var tBody = new TextBlock { Text = "Body Text (13px Regular) — Ultimate limit state (ULS) design check verified according to Eurocode 2 (EN 1992-1-1) with design yield strength fyd = 435 MPa.", Margin = new System.Windows.Thickness(0, 0, 0, 8), TextWrapping = System.Windows.TextWrapping.Wrap };
        tBody.SetResourceReference(TextBlock.StyleProperty, "CONCOST.TextBlock.Body");
        var tSec = new TextBlock { Text = "Secondary Text (12.5px Muted) — Parameter updated 5 minutes ago by Structural Engine v3.0.0 Pro.", Margin = new System.Windows.Thickness(0, 0, 0, 8) };
        tSec.SetResourceReference(TextBlock.StyleProperty, "CONCOST.TextBlock.Secondary");
        var tCap = new TextBlock { Text = "Caption / Note (11px Subtle) — * Note: Deflection calculation includes long-term creep coefficient φ(∞,t0) = 2.45.", Margin = new System.Windows.Thickness(0, 0, 0, 8) };
        tCap.SetResourceReference(TextBlock.StyleProperty, "CONCOST.TextBlock.Caption");
        var tCode = new TextBlock { Text = "Code / Formula: ?_max = M_Ed / W_el = 125.4 kN·m / (0.0125 m³) = 10.03 MPa → f_cd = 16.7 MPa [OK]" };
        tCode.SetResourceReference(TextBlock.StyleProperty, "CONCOST.TextBlock.Code");
        g2.Children.Add(tBody); g2.Children.Add(tSec); g2.Children.Add(tCap); g2.Children.Add(tCode);
        sec2.Children.Add(g2);

        var lbl2D = new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl2D.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec2.Children.Add(lbl2D);

        var g2D = new StackPanel { Opacity = 0.45 };
        var tBodyD = new TextBlock { Text = "Body Text (Disabled) — This calculation revision is superseded and locked for editing.", Margin = new System.Windows.Thickness(0, 0, 0, 6) };
