    private object CreateExpanderDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Helper to generate elegant parameter metric badges
        Border CreateMetricBadge(string label, string val, bool isHighlight = false)
        {
            var badge = new Border
            {
                Background = isHighlight
                    ? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(16, 255, 121, 0))
                    : new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(10, 100, 116, 139)),
                BorderBrush = isHighlight
                    ? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(60, 255, 121, 0))
                    : new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(30, 100, 116, 139)),
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(6),
                Padding = new System.Windows.Thickness(10, 5, 10, 5),
                Margin = new System.Windows.Thickness(0, 0, 8, 8)
            };
            var bSp = new StackPanel();
            var lTxt = new TextBlock
            {
                Text = label,
                FontSize = 10.5,
                FontWeight = System.Windows.FontWeights.Normal,
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(180, 100, 116, 139))
            };
            var vTxt = new TextBlock
            {
                Text = val,
                FontSize = 12.5,
                FontWeight = System.Windows.FontWeights.Normal
            };
            if (isHighlight)
                vTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
            else
                vTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");

            bSp.Children.Add(lTxt);
            bSp.Children.Add(vTxt);
            badge.Child = bSp;
            return badge;
        }

        // ==================== SECTION 1: 4-Directional Multi-Style Expanders ====================
        System.Windows.Controls.Expander CreateHcExp(string title, System.Windows.Controls.ExpandDirection dir, string? styleKey = null, bool isExpanded = false, double? height = null, Thickness? margin = null, string? tooltip = null)
        {
            var exp = new System.Windows.Controls.Expander
            {
                Header = title,
                ExpandDirection = dir,
                IsExpanded = isExpanded,
                Margin = margin ?? ((dir == System.Windows.Controls.ExpandDirection.Down || dir == System.Windows.Controls.ExpandDirection.Up)
                    ? new System.Windows.Thickness(0, 0, 0, 8)
                    : new System.Windows.Thickness(0, 0, 6, 0))
            };
            if (height.HasValue) exp.Height = height.Value;
            if (!string.IsNullOrEmpty(tooltip)) exp.ToolTip = tooltip;

            exp.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, string.IsNullOrEmpty(styleKey) ? "CONCOST.Expander.Base" : styleKey);

            exp.Content = new Border
            {
                Padding = new System.Windows.Thickness(12),
                Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(8, 0, 0, 0)),
                Child = new TextBlock
                {
                    Text = $"Expanded content in direction [{dir}] ({styleKey ?? "Default"}).",
                    FontSize = 11.5,
                    Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(200, 100, 116, 139))
                }
            };
            return exp;
        }

        var sec1Sp = new StackPanel();

        // Row 1: ExpandDirection = Down (Left) & Side-Docked Strips (Right)
        var row1Grid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 24) };
        row1Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        row1Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        row1Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var r1Left = new StackPanel();
        r1Left.Children.Add(new TextBlock
        {
            Text = "ExpandDirection = Down (Default, Primary, Success, Warning):",
            FontWeight = System.Windows.FontWeights.Normal,
            FontSize = 12.5,
            Margin = new System.Windows.Thickness(0, 0, 0, 8)
        });
        r1Left.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Down, null, false, null, new System.Windows.Thickness(0, 0, 0, 8), "Default Surface"));
        r1Left.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Down, "CONCOST.Expander.Primary", false, null, new System.Windows.Thickness(0, 0, 0, 8), "Primary Accent"));
        r1Left.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Down, "CONCOST.Expander.Success", false, null, new System.Windows.Thickness(0, 0, 0, 8), "Success Status"));
        r1Left.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Down, "CONCOST.Expander.Warning", false, null, new System.Windows.Thickness(0), "Warning Alert"));

        var r1Right = new StackPanel();
        r1Right.Children.Add(new TextBlock
        {
            Text = "ExpandDirection = Left & Right (Row 1 Side-Docked Strips):",
            FontWeight = System.Windows.FontWeights.Normal,
            FontSize = 12.5,
            Margin = new System.Windows.Thickness(0, 0, 0, 8)
        });

        const double stripHeight = 152.0; // Exactly matches 4 * 32px + 3 * 8px of the left column
        var r1Strips = new StackPanel { Orientation = Orientation.Horizontal, Height = stripHeight };
        // 4 Left strips
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Left, null, false, stripHeight, null, "Default (Left Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Left, "CONCOST.Expander.Primary", false, stripHeight, null, "Primary (Left Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Left, "CONCOST.Expander.Success", false, stripHeight, null, "Success (Left Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Left, "CONCOST.Expander.Warning", false, stripHeight, null, "Warning (Left Dock)"));

        var r1Div = new Border { Width = 1, Margin = new System.Windows.Thickness(6, 0, 10, 0) };
        r1Div.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
        r1Strips.Children.Add(r1Div);

        // 4 Right strips
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Right, null, false, stripHeight, null, "Default (Right Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Right, "CONCOST.Expander.Primary", false, stripHeight, null, "Primary (Right Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Right, "CONCOST.Expander.Success", false, stripHeight, null, "Success (Right Dock)"));
        r1Strips.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Right, "CONCOST.Expander.Warning", false, stripHeight, null, "Warning (Right Dock)"));

        r1Right.Children.Add(r1Strips);

        Grid.SetColumn(r1Left, 0);
        Grid.SetColumn(r1Right, 2);
        row1Grid.Children.Add(r1Left);
        row1Grid.Children.Add(r1Right);
        sec1Sp.Children.Add(row1Grid);

        // Row 2: ExpandDirection = Up (Left) & Side-Docked Strips (Right)
        var row2Grid = new Grid();
        row2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        row2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        row2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var r2Left = new StackPanel();
        r2Left.Children.Add(new TextBlock
        {
            Text = "ExpandDirection = Up (Default, Primary, Success, Warning):",
            FontWeight = System.Windows.FontWeights.Normal,
            FontSize = 12.5,
            Margin = new System.Windows.Thickness(0, 0, 0, 8)
        });
        r2Left.Children.Add(CreateHcExp("Title", System.Windows.Controls.ExpandDirection.Up, null, false, null, new System.Windows.Thickness(0, 0, 0, 8), "Default Bottom"));
