<!-- 4. ExpandDirection=""Right"" (Vertical Side-Docked Header with RotateTransform) -->
<Expander Header=""Title"" ExpandDirection=""Right"" Height=""152"" />";

        AddCardSection("1. 4-Directional Multi-Style Expanders", sec1Sp, sec1Code);

        // ==================== SECTION 2: Standard & Elevated Card Engineering Expanders ====================
        var grid1 = new Grid();
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var expDef = new System.Windows.Controls.Expander { Header = "Standard: Beam Geometry (300 x 600 mm)", IsExpanded = true };
        var expDefContent = new StackPanel();
        var wp1 = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        wp1.Children.Add(CreateMetricBadge("WIDTH b", "300 mm"));
        wp1.Children.Add(CreateMetricBadge("DEPTH h", "600 mm"));
        wp1.Children.Add(CreateMetricBadge("EFF DEPTH d", "560 mm"));
        wp1.Children.Add(CreateMetricBadge("GRADE", "C25/30", true));
        expDefContent.Children.Add(wp1);
        expDefContent.Children.Add(new TextBlock
        {
            Text = "✓ Clear cover c = 40 mm | Slenderness ratio λ = 18.4 (Short column/beam)",
