            Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(200, 16, 185, 129)),
            FontWeight = System.Windows.FontWeights.Normal
        });
        expDef.Content = expDefContent;

        var expCard = new System.Windows.Controls.Expander { Header = "Elevated Card: Rebar Detailing Schedule", IsExpanded = true };
        expCard.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Expander.Card");
        var expCardContent = new StackPanel();
        var wp2 = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
