        wp2.Children.Add(CreateMetricBadge("STIRRUPS", "D10 @ 150"));
        wp2.Children.Add(CreateMetricBadge("STEEL GRADE", "B500B"));
        expCardContent.Children.Add(wp2);
        expCardContent.Children.Add(new TextBlock
        {
            Text = "✓ High ductility steel fyd = 435 MPa | Anchorage length lb,rqd = 480 mm",
            FontSize = 11.5,
            Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(200, 16, 185, 129)),
            FontWeight = System.Windows.FontWeights.Normal
        });
        expCard.Content = expCardContent;

        Grid.SetColumn(expDef, 0); grid1.Children.Add(expDef);
        Grid.SetColumn(expCard, 2); grid1.Children.Add(expCard);

        string sec2Code =
@"<!-- Standard & Elevated Card Engineering Expanders -->
<Grid>
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width=""*"" />
        <ColumnDefinition Width=""16"" />
        <ColumnDefinition Width=""*"" />
    </Grid.ColumnDefinitions>

    <!-- Standard Expander with Metric Badges -->
    <Expander Grid.Column=""0"" Header=""Standard: Beam Geometry (300 x 600 mm)"" IsExpanded=""True"">
        <StackPanel Margin=""4"">
            <!-- Parameter Badges: b=300mm, h=600mm, d=560mm, C25/30 -->
            <TextBlock Text=""✓ Clear cover c = 40 mm | Slenderness ratio λ = 18.4"" />
        </StackPanel>
    </Expander>

    <!-- Elevated Floating Card Expander -->
    <Expander Grid.Column=""2"" Style=""{DynamicResource CONCOST.Expander.Card}"" Header=""Elevated Card: Rebar Schedule"" IsExpanded=""True"">
        <StackPanel Margin=""4"">
            <!-- Parameter Badges: 4xD20, As=1,256mm², D10@150, B500B -->
            <TextBlock Text=""✓ High ductility steel fyd = 435 MPa | lb,rqd = 480 mm"" />
        </StackPanel>
    </Expander>
</Grid>";

        AddCardSection("2. Standard & Elevated Card Engineering Expanders", grid1, sec2Code);

        // ==================== SECTION 3: Clean Underline Accordion ====================
        var sec3Sp = new StackPanel();
        var acc1 = new System.Windows.Controls.Expander { Header = "Step 1: Ultimate Bending Moment Capacity (MRd)", IsExpanded = true, Margin = new System.Windows.Thickness(0) };
        acc1.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Expander.Clean");
        var acc1Content = new StackPanel();
        acc1Content.Children.Add(new TextBlock
        {
            Text = "Concrete design strength fcd = 16.7 MPa | Compression zone depth x = 86.4 mm (x/d = 0.154 < 0.45)\nMRd = As · fyd · (d - 0.4x) = 1256 · 435 · (560 - 34.6) · 10⁻⁶ = 286.8 kNm > MEd (245.8 kNm)\nStatus: CAPACITY PASS (Margin: +16.7%)",
            FontSize = 12,
            LineHeight = 20,
            Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(220, 16, 185, 129)),
            FontWeight = System.Windows.FontWeights.Normal
        });
        acc1.Content = acc1Content;

        var acc2 = new System.Windows.Controls.Expander { Header = "Step 2: Shear Force & Strut Crushing Check (VRd,c & VRd,max)", IsExpanded = false, Margin = new System.Windows.Thickness(0) };
        acc2.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Expander.Clean");
        acc2.Content = new TextBlock
        {
            Text = "VEd = 142.5 kN | Concrete capacity VRd,c = 68.2 kN (Shear stirrups required)\nProvided: D10 @ 150 mm c/c (2 legs) -> Shear capacity VRd,s = 186.4 kN > VEd (142.5 kN)\nStatus: SHEAR PASS (Margin: +30.8%)",
            FontSize = 12,
            LineHeight = 20,
            Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(220, 16, 185, 129)),
            FontWeight = System.Windows.FontWeights.Normal
        };

        var acc3 = new System.Windows.Controls.Expander { Header = "Step 3: Serviceability Limit State (Deflection & Cracking)", IsExpanded = false, Margin = new System.Windows.Thickness(0) };
        acc3.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Expander.Clean");
        acc3.Content = new TextBlock
        {
            Text = "Creep coefficient φ(∞,t0) = 2.45 | Instantaneous δ0 = 4.8 mm -> Total long-term δ = 14.8 mm < L/250 (24.0 mm)\nSteel stress under quasi-permanent load σs = 224 MPa -> Crack width wk = 0.18 mm < 0.30 mm\nStatus: SLS PASS (All limits compliant)",
            FontSize = 12,
            LineHeight = 20,
            Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(220, 16, 185, 129)),
            FontWeight = System.Windows.FontWeights.Normal
        };

        sec3Sp.Children.Add(acc1);
        sec3Sp.Children.Add(acc2);
        sec3Sp.Children.Add(acc3);

        string sec3Code =
@"<!-- Clean Underline Accordion (Stepped Engineering Calculations) -->
<StackPanel>
    <Expander Style=""{DynamicResource CONCOST.Expander.Clean}"" Header=""Step 1: Bending Capacity MRd"" IsExpanded=""True"">
        <TextBlock Text=""MRd = 286.8 kNm > MEd (245.8 kNm) -> STATUS: PASS"" />
