        pbSuccess.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Success");
        spPb2.Children.Add(pbSuccess);

        var spPb3 = new StackPanel();
        spPb3.Children.Add(new TextBlock { Text = "Warning (82%)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        var pbWarning = new ProgressBar { Value = 82 };
        pbWarning.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Warning");
        spPb3.Children.Add(pbWarning);

        var spPb4 = new StackPanel();
        spPb4.Children.Add(new TextBlock { Text = "Danger (95% Load)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        var pbDanger = new ProgressBar { Value = 95 };
        pbDanger.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Danger");
        spPb4.Children.Add(pbDanger);

        Grid.SetColumn(spPb1, 0); grid1E.Children.Add(spPb1);
        Grid.SetColumn(spPb2, 2); grid1E.Children.Add(spPb2);
        Grid.SetColumn(spPb3, 4); grid1E.Children.Add(spPb3);
        Grid.SetColumn(spPb4, 6); grid1E.Children.Add(spPb4);
        sec1.Children.Add(grid1E);

        var lbl1D = new TextBlock { Text = "Disabled States:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl1D.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec1.Children.Add(lbl1D);

        var grid1D = new Grid();
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid1D.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var spPb1D = new StackPanel();
        spPb1D.Children.Add(new TextBlock { Text = "Locked Primary", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        spPb1D.Children.Add(new ProgressBar { Value = 45, IsEnabled = false });

        var spPb2D = new StackPanel();
