        Grid.SetColumn(spPb3D, 4); grid1D.Children.Add(spPb3D);
        Grid.SetColumn(spPb4D, 6); grid1D.Children.Add(spPb4D);
        sec1.Children.Add(grid1D);

        AddCardSection("1. Semantic Variants & Value Percentage (Primary · Success · Warning · Danger)", sec1,
@"<!-- Primary Progress with Percentage Text (Default ShowText=True) -->
<ProgressBar Value=""65"" />

<!-- Success Progress with Percentage -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Success}"" Value=""100"" />

<!-- Warning Progress with Percentage -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Warning}"" Value=""82"" />

<!-- Danger Progress with Percentage -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Danger}"" Value=""95"" />");

        // ==============================================================================?
        // SECTION 2: Indeterminate & Loading Loops
        // ==============================================================================?
        var sec2 = new StackPanel();
        var lbl2E = new TextBlock { Text = "Indeterminate & Calculation Loop Loaders:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl2E.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec2.Children.Add(lbl2E);

        var grid2 = new Grid();
        grid2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid2.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var spIndet1 = new StackPanel();
        spIndet1.Children.Add(new TextBlock { Text = "Active FEA Structural Mesh Solver (Wave Animation)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        spIndet1.Children.Add(new ProgressBar { IsIndeterminate = true, Height = 8 });

        var spIndet2 = new StackPanel();
        spIndet2.Children.Add(new TextBlock { Text = "Building Model Export / BIM Synchronization", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        var pbIndetSuccess = new ProgressBar { IsIndeterminate = true, Height = 8 };
        pbIndetSuccess.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Success");
        spIndet2.Children.Add(pbIndetSuccess);

        Grid.SetColumn(spIndet1, 0); grid2.Children.Add(spIndet1);
        Grid.SetColumn(spIndet2, 2); grid2.Children.Add(spIndet2);
        sec2.Children.Add(grid2);

        AddCardSection("2. Indeterminate & Real-Time Loading Wave Animation", sec2,
@"<!-- Indeterminate Standard Wave -->
<ProgressBar IsIndeterminate=""True"" Height=""8"" />

<!-- Indeterminate Success Stream -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Success}"" IsIndeterminate=""True"" Height=""8"" />");

        // ==============================================================================?
        // SECTION 3: Size & Corner Radius Geometry
        // ==============================================================================?
        var sec3 = new StackPanel();
        var lbl3E = new TextBlock { Text = "Geometry & Height System:", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        lbl3E.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary"); sec3.Children.Add(lbl3E);

        var grid3 = new Grid();
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(16) });
        grid3.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var spThin = new StackPanel();
        spThin.Children.Add(new TextBlock { Text = "Thin Compact (Height = 6px, No Text)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 8) });
        var pbThin = new ProgressBar { Value = 55 };
        pbThin.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Thin");
        spThin.Children.Add(pbThin);

        var spDefSize = new StackPanel();
        spDefSize.Children.Add(new TextBlock { Text = "Standard (Height = 18px with % Text)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        spDefSize.Children.Add(new ProgressBar { Value = 75 });

        var spThick = new StackPanel();
        spThick.Children.Add(new TextBlock { Text = "Thick Pill (Height = 22px with Bold % Text)", FontSize = 11.5, Margin = new System.Windows.Thickness(0, 0, 0, 3) });
        var pbThick = new ProgressBar { Value = 88 };
        pbThick.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.ProgressBar.Thick");
        spThick.Children.Add(pbThick);

        Grid.SetColumn(spThin, 0); grid3.Children.Add(spThin);
        Grid.SetColumn(spDefSize, 2); grid3.Children.Add(spDefSize);
        Grid.SetColumn(spThick, 4); grid3.Children.Add(spThick);
        sec3.Children.Add(grid3);

        AddCardSection("3. Size System & Corner Radius (Thin 4px · Standard 8px · Thick 14px)", sec3,
@"<!-- Thin 4px Compact Progress -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Thin}"" Value=""55"" />

<!-- Standard 8px Progress -->
<ProgressBar Value=""75"" Height=""8"" />

<!-- Thick 14px High-Contrast Progress -->
<ProgressBar Style=""{StaticResource CONCOST.ProgressBar.Thick}"" Value=""88"" />");

        return mainSp;
    }

    private object CreateCalendarDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // ==================== SECTION 1: Single Date Selection (Base vs Primary) ====================
        var grid1 = new Grid();
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        grid1.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var calBase = new System.Windows.Controls.Calendar
        {
            SelectedDate = DateTime.Today,
            DisplayDate = DateTime.Today,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };

        var calPrimary = new System.Windows.Controls.Calendar
        {
            SelectedDate = DateTime.Today.AddDays(3),
            DisplayDate = DateTime.Today,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };
        calPrimary.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Calendar.Primary");

        Grid.SetColumn(calBase, 0); grid1.Children.Add(calBase);
        Grid.SetColumn(calPrimary, 2); grid1.Children.Add(calPrimary);

        string sec1Code =
@"<!-- Single Date Selection (Standard vs Primary Highlight) -->
<Grid>
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width=""*"" />
        <ColumnDefinition Width=""24"" />
        <ColumnDefinition Width=""*"" />
    </Grid.ColumnDefinitions>

    <!-- Standard Base Calendar -->
    <Calendar Grid.Column=""0"" SelectedDate=""{x:Static sys:DateTime.Today}"" HorizontalAlignment=""Center"" />

    <!-- Primary Accent Highlight Calendar -->
    <Calendar Grid.Column=""2"" Style=""{DynamicResource CONCOST.Calendar.Primary}""
              SelectedDate=""{Binding InspectionDate}"" HorizontalAlignment=""Center"" />
</Grid>";

        AddCardSection("1. Single Date Selection & Today Highlight (Base vs Primary)", grid1, sec1Code);

        // ==================== SECTION 2: Milestone Multiple Range Selection ====================
        var sec2Grid = new Grid();
        sec2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        sec2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        sec2Grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var calRange = new System.Windows.Controls.Calendar
        {
            SelectionMode = System.Windows.Controls.CalendarSelectionMode.MultipleRange,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };
        calRange.SelectedDates.AddRange(DateTime.Today, DateTime.Today.AddDays(14));
        Grid.SetColumn(calRange, 0);
        sec2Grid.Children.Add(calRange);

        var rangeDetails = new Border
        {
            CornerRadius = new System.Windows.CornerRadius(8),
            BorderThickness = new System.Windows.Thickness(1),
            Padding = new System.Windows.Thickness(18),
            VerticalAlignment = System.Windows.VerticalAlignment.Center
        };
        rangeDetails.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        rangeDetails.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var rangeSp = new StackPanel();
        var rdTitle = new TextBlock { Text = "Gantt Schedule: Foundation Concrete Pouring", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13.5 };
        rdTitle.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        rangeSp.Children.Add(rdTitle);

        var rdSub = new TextBlock
        {
            Text = $"Duration: 14 Consecutive Working Days\nPeriod: {DateTime.Today:MMM dd, yyyy} to {DateTime.Today.AddDays(14):MMM dd, yyyy}\nWork Package: Pile Caps, Grade Beams & Raft Foundation\nPre-pour Rebar Inspection: VERIFIED (Status: PASS)",
            Margin = new System.Windows.Thickness(0, 10, 0, 12),
            LineHeight = 22
        };
        rdSub.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        rangeSp.Children.Add(rdSub);

        var badgeSp = new StackPanel { Orientation = Orientation.Horizontal };
        var b1 = new Badge { Style = (System.Windows.Style)App.Current.Resources["CONCOST.Badge.Soft"], Content = "Gantt Phase 1", Appearance = BadgeAppearance.Primary, Margin = new System.Windows.Thickness(0, 0, 8, 0) };
        var b2 = new Badge { Style = (System.Windows.Style)App.Current.Resources["CONCOST.Badge.Soft"], Content = "Scheduled", Appearance = BadgeAppearance.Success };
        badgeSp.Children.Add(b1);
        badgeSp.Children.Add(b2);
        rangeSp.Children.Add(badgeSp);

        rangeDetails.Child = rangeSp;
        Grid.SetColumn(rangeDetails, 2);
        sec2Grid.Children.Add(rangeDetails);

        string sec2Code =
@"<!-- Multiple Range Selection Mode (Project Milestone Duration) -->
<Grid>
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width=""*"" />
        <ColumnDefinition Width=""24"" />
        <ColumnDefinition Width=""*"" />
    </Grid.ColumnDefinitions>

    <Calendar Grid.Column=""0"" SelectionMode=""MultipleRange"" HorizontalAlignment=""Center"" />

    <Border Grid.Column=""2"" CornerRadius=""8"" Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"" Padding=""18"">
        <StackPanel>
            <TextBlock Text=""Gantt Schedule: Foundation Concrete Pouring"" FontWeight=""Normal"" />
            <TextBlock Text=""14 Consecutive Days | Pile Caps &amp; Raft Foundation"" Margin=""0,8"" />
        </StackPanel>
    </Border>
</Grid>";

        AddCardSection("2. Milestone Multiple Range Selection (Gantt Period)", sec2Grid, sec2Code);

        // ==================== SECTION 3: Blackout Dates (Site Non-Working Days) ====================
        var sec3Sp = new StackPanel();
        var calBlackout = new System.Windows.Controls.Calendar
        {
            SelectedDate = DateTime.Today.AddDays(5),
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left
        };
        // Add past dates blackout and upcoming maintenance window blackout
        calBlackout.BlackoutDates.AddDatesInPast();
        calBlackout.BlackoutDates.Add(new System.Windows.Controls.CalendarDateRange(DateTime.Today.AddDays(1), DateTime.Today.AddDays(3)));
        sec3Sp.Children.Add(calBlackout);

        string sec3Code =
@"<!-- Blackout Dates (Restricted & Non-Working Days) -->
<Calendar HorizontalAlignment=""Left"" />

// C# Code-Behind: Configure non-working dates
cal.BlackoutDates.AddDatesInPast();
cal.BlackoutDates.Add(new CalendarDateRange(DateTime.Today.AddDays(1), DateTime.Today.AddDays(3)));";

        AddCardSection("3. Blackout Dates (Site Non-Working Days & Past Lockout)", sec3Sp, sec3Code);

        // ==================== SECTION 4: Elevated Card Calendar with Action Presets ====================
        var sec4Host = new Grid();
        sec4Host.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        sec4Host.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(24) });
        sec4Host.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var cardCal = new System.Windows.Controls.Calendar
        {
            SelectedDate = DateTime.Today,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };
        cardCal.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Calendar.Card");

        var compactCalContainer = new StackPanel { HorizontalAlignment = System.Windows.HorizontalAlignment.Center };
        var compactCal = new System.Windows.Controls.Calendar
        {
            SelectedDate = DateTime.Today,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };
        compactCal.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.Calendar.Compact");

        var presetBar = new StackPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 8, 0, 0) };
        var btnToday = new Button { Content = "Today", Width = 65, Height = 26, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
        btnToday.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btnToday.Click += (s, e) => compactCal.SelectedDate = DateTime.Today;

        var btn7Days = new Button { Content = "+7 Days", Width = 65, Height = 26, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
        btn7Days.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btn7Days.Click += (s, e) => compactCal.SelectedDate = (compactCal.SelectedDate ?? DateTime.Today).AddDays(7);

        var btnClear = new Button { Content = "Clear", Width = 65, Height = 26 };
        btnClear.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btnClear.Click += (s, e) => compactCal.SelectedDate = null;

        presetBar.Children.Add(btnToday);
        presetBar.Children.Add(btn7Days);
        presetBar.Children.Add(btnClear);

        compactCalContainer.Children.Add(compactCal);
        compactCalContainer.Children.Add(presetBar);

        Grid.SetColumn(cardCal, 0); sec4Host.Children.Add(cardCal);
        Grid.SetColumn(compactCalContainer, 2); sec4Host.Children.Add(compactCalContainer);

        string sec4Code =
@"<!-- Elevated Card & Compact Calendar with Action Presets -->
<Grid>
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width=""*"" />
        <ColumnDefinition Width=""24"" />
        <ColumnDefinition Width=""*"" />
    </Grid.ColumnDefinitions>

    <!-- Elevated Card Calendar -->
    <Calendar Grid.Column=""0"" Style=""{DynamicResource CONCOST.Calendar.Card}"" SelectedDate=""{x:Static sys:DateTime.Today}"" />

    <!-- Compact Calendar with Presets -->
    <StackPanel Grid.Column=""2"">
        <Calendar x:Name=""compactCal"" Style=""{DynamicResource CONCOST.Calendar.Compact}"" />
        <StackPanel Orientation=""Horizontal"" Margin=""0,8,0,0"">
            <Button Style=""{DynamicResource CONCOST.Button.Secondary}"" Content=""Today"" Click=""OnTodayClick"" Width=""65"" />
            <Button Style=""{DynamicResource CONCOST.Button.Secondary}"" Content=""+7 Days"" Click=""OnAdd7DaysClick"" Width=""65"" Margin=""6,0"" />
            <Button Style=""{DynamicResource CONCOST.Button.Secondary}"" Content=""Clear"" Click=""OnClearClick"" Width=""65"" />
        </StackPanel>
    </StackPanel>
</Grid>";

        AddCardSection("4. Elevated Card & Compact Calendar with Action Presets", sec4Host, sec4Code);

        return mainSp;
    }

    private object CreateDatePickerDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrWhiteSpace(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid { Height = 34, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tagIcon = new CONCOST.UI.Icons.Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var langLabel = new TextBlock { Text = "XAML Code Example", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);
                codeBoxInner.Children.Add(codeTopBar);

                var div = new Border { Height = 1 };
                div.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(div);

                var codePresenter = new TextBlock
                {
                    Text = xamlSnippet.Trim(),
                    FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New, Segoe UI Mono, monospace"),
                    FontSize = 12,
                    LineHeight = 19,
                    Padding = new System.Windows.Thickness(14, 12, 14, 12),
                    TextWrapping = System.Windows.TextWrapping.Wrap
                };
                codePresenter.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBoxInner.Children.Add(codePresenter);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == System.Windows.Visibility.Visible
                        ? System.Windows.Visibility.Collapsed
                        : System.Windows.Visibility.Visible;
                    codeBtn.Content = codeBox.Visibility == System.Windows.Visibility.Visible ? "Hide XAML" : "View XAML";
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // ==============================================================================?
        // SECTION 1: Standard Construction Milestone DatePickers
        // ==============================================================================?
        var sec1 = new StackPanel();
        var grid1 = new Grid();
