        tTop1Content.Children.Add(BuildMetricCard("TOTAL STORIES", "18 Floors", "64.8 m height above ground", IconKind.Layers));
        tTop1Content.Children.Add(BuildMetricCard("FOOTPRINT AREA", "4,500 m²", "64.0m x 48.0m bay layout", IconKind.Grid));
        tTop1Content.Children.Add(BuildMetricCard("CONCRETE GRADE", "C35/45", "f'c = 35 MPa, Ec = 31.2 GPa", IconKind.TuneAdjust));
        tTop1Content.Children.Add(BuildMetricCard("COLUMN COUNT", "72 Columns", "800x800mm tied square sections", IconKind.Check));
        tTop1.Content = tTop1Content;

        // Tab 2: FEA Solver
        var tTop2 = new TabItem { Header = "FEA Member Forces" };
