        tTop2Content.Children.Add(BuildMetricCard("GOVERNING LOAD", "1.2D + 1.0E + 0.5L", "Strength envelope combination", IconKind.TuneAdjust));
        tTop2Content.Children.Add(BuildMetricCard("BASE SHEAR (Vx)", "4,820 kN", "V_base / Seismic Weight = 0.082", IconKind.Layers));
        tTop2Content.Children.Add(BuildMetricCard("INTER-STORY DRIFT", "1 / 480", "Allowable: 1 / 400 (Passed)", IconKind.Check));
        tTop2Content.Children.Add(BuildMetricCard("SOLVER STATUS", "Converged", "12 load combinations solved", IconKind.Check));
        tTop2.Content = tTop2Content;

        // Tab 3: Rebar Schedule
        var tTop3 = new TabItem { Header = "Rebar & BBS Schedule" };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tTop3, IconKind.File);
        var tTop3Content = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 6, 0, 0) };
        tTop3Content.Children.Add(BuildMetricCard("COLUMN MAIN REBAR", "16 Ø 25 mm", "HRB500 deformed rebar", IconKind.Edit));
        tTop3Content.Children.Add(BuildMetricCard("BEAM REINFORCEMENT", "4Ø25 Top / 6Ø25 Bot", "Mid-span critical moment steel", IconKind.Edit));
        tTop3Content.Children.Add(BuildMetricCard("SHEAR TIES", "Ø 10 @ 100 mm", "4-legged seismic stirrups", IconKind.TuneAdjust));
        tTop3Content.Children.Add(BuildMetricCard("TOTAL STEEL TONNAGE", "248.6 Tons", "Reinforcement density: 101 kg/m³", IconKind.File));
        tTop3.Content = tTop3Content;

        tcTop.Items.Add(tTop1);
        tcTop.Items.Add(tTop2);
        tcTop.Items.Add(tTop3);

        sec1Sp.Children.Add(tcTop);

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
