            newTab.Content = newTabContent;

            tcChrome.Items.Add(newTab);
            tcChrome.SelectedItem = newTab;
            ToastService.Success($"Created new worksheet '{newTab.Header}'", "IDE TabControl");
        };
        headerBar.Children.Add(addTabBtn);
        CONCOST.UI.AttachedProperties.TabControlHelper.SetHeaderExtraContent(tcChrome, headerBar);

        // Listen for TabClosed routed event
        CONCOST.UI.AttachedProperties.TabControlHelper.AddTabClosedHandler(tcChrome, (s, e) =>
        {
            if (e.OriginalSource is TabItem closedTab)
            {
                ToastService.Info($"Closed tab: {closedTab.Header}", "Tab Manager");
            }
        });

        // Pinned tab: Project Overview (IsClosable = False)
        var tChrome1 = new TabItem { Header = "Project Overview" };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tChrome1, IconKind.Layers);
        CONCOST.UI.AttachedProperties.TabControlHelper.SetIsClosable(tChrome1, false);
        var c1Content = new StackPanel();
        c1Content.Children.Add(new TextBlock { Text = "Central BIM Project Coordination Model (Pinned)", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        c1Content.Children.Add(new TextBlock { Text = "This master dashboard is pinned and cannot be closed. It maintains central state synchronization with the BIM server.", Margin = new System.Windows.Thickness(0, 0, 0, 12) });
        var c1Wrap = new WrapPanel { Orientation = Orientation.Horizontal };
        c1Wrap.Children.Add(BuildMetricCard("PINNED STATUS", "Protected Tab", "IsClosable = False", IconKind.Check));
        c1Wrap.Children.Add(BuildMetricCard("CENTRAL MODEL", "Revision 2.4", "Synced with Revit / ETABS", IconKind.File));
        c1Content.Children.Add(c1Wrap);
        tChrome1.Content = c1Content;

        // Closable tab 2: MainFrame_3D.dwg
        var tChrome2 = new TabItem { Header = "MainFrame_3D.dwg" };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tChrome2, IconKind.File);
        CONCOST.UI.AttachedProperties.TabControlHelper.SetIsClosable(tChrome2, true);
        var c2Content = new StackPanel();
        c2Content.Children.Add(new TextBlock { Text = "AutoCAD DWG 3D Structural Analytical Model", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        c2Content.Children.Add(new TextBlock { Text = "Hover over tab header to reveal close button (X). Click X to execute TabControlHelper.CloseCommand.", Margin = new System.Windows.Thickness(0, 0, 0, 12) });
        var c2Wrap = new WrapPanel { Orientation = Orientation.Horizontal };
        c2Wrap.Children.Add(BuildMetricCard("FORMAT", "DWG 2024", "AutoCAD solids & wireframe", IconKind.File));
        c2Wrap.Children.Add(BuildMetricCard("CLOSE ACTION", "Closable Tab", "IsClosable = True", IconKind.Close));
        c2Content.Children.Add(c2Wrap);
        tChrome2.Content = c2Content;

        // Closable tab 3: Column_C1_Detail.calc
        var tChrome3 = new TabItem { Header = "Column_C1_Detail.calc" };
        CONCOST.UI.AttachedProperties.IconElement.SetKind(tChrome3, IconKind.Edit);
        CONCOST.UI.AttachedProperties.TabControlHelper.SetIsClosable(tChrome3, true);
        var c3Content = new StackPanel();
        c3Content.Children.Add(new TextBlock { Text = "Column C1 Axial-Flexure P-M Interaction Sheet", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13.5, Margin = new System.Windows.Thickness(0, 0, 0, 6) });
        c3Content.Children.Add(new TextBlock { Text = "Nonlinear fiber section integration: Pu = 6,840 kN, Mux = 480 kNm, Muy = 320 kNm. Capacity ratio D/C = 0.82 (OK).", Margin = new System.Windows.Thickness(0, 0, 0, 12) });
        var c3Wrap = new WrapPanel { Orientation = Orientation.Horizontal };
