        // ==================== SECTION 2: Rich Engineering Nodes with Vector Icons & Status Chips ====================
        TreeView CreateRichTree()
        {
            var tv = new TreeView { Height = 220, Width = 480, Margin = new System.Windows.Thickness(0) };

            TreeViewItem CreateNode(string title, IconKind icon, Brush iconBrush, string? tagText = null, BadgeAppearance appearance = BadgeAppearance.Neutral, bool isExpanded = false)
            {
                var item = new TreeViewItem { IsExpanded = isExpanded };
                var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                
                var ico = new Icon { Kind = icon, Width = 15, Height = 15, Margin = new System.Windows.Thickness(0, 0, 8, 0), VerticalAlignment = System.Windows.VerticalAlignment.Center, Foreground = iconBrush };
                sp.Children.Add(ico);

                var txt = new TextBlock { Text = title, FontSize = 12.5, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                sp.Children.Add(txt);

                if (!string.IsNullOrEmpty(tagText))
                {
                    var badge = new Badge
                    {
                        Style = (System.Windows.Style)App.Current.Resources["CONCOST.Badge.Soft"],
                        Content = tagText,
                        Appearance = appearance,
                        Margin = new System.Windows.Thickness(10, 0, 0, 0),
                        Padding = new System.Windows.Thickness(6, 1.5, 6, 1.5),
                        FontSize = 10.5
                    };
                    sp.Children.Add(badge);
                }

                item.Header = sp;
                return item;
            }

            var brushFolder = new SolidColorBrush(Color.FromRgb(217, 119, 6));   // Gold
            var brushLayer = new SolidColorBrush(Color.FromRgb(37, 99, 235));    // Blue
            var brushRuler = new SolidColorBrush(Color.FromRgb(5, 150, 105));    // Green
            var brushFile = new SolidColorBrush(Color.FromRgb(100, 116, 139));   // Slate

            var root = CreateNode("Project: CONCOST Commercial Tower", IconKind.Folder, brushFolder, "Active", BadgeAppearance.Primary, true);
            var t1 = CreateNode("Level 1 [Elev. +0.000m]", IconKind.Layers, brushLayer, "12 Elements", BadgeAppearance.Neutral, true);
            t1.Items.Add(CreateNode("Main Girder D1 (300x600 - 4D20)", IconKind.Ruler, brushRuler, "Approved", BadgeAppearance.Success));
            t1.Items.Add(CreateNode("Secondary Beam D2 (200x400 - 3D16)", IconKind.Ruler, brushRuler, "In Review", BadgeAppearance.Warning));
            var t2 = CreateNode("Level 2 [Elev. +3.900m]", IconKind.Layers, brushLayer, "14 Elements", BadgeAppearance.Neutral);
            t2.Items.Add(CreateNode("Columns C1-C8 (500x500)", IconKind.File, brushFile, "Verified", BadgeAppearance.Success));

            root.Items.Add(t1);
            root.Items.Add(t2);
            tv.Items.Add(root);
            return tv;
        }

