        TreeView CreateCheckTree()
        {
            var tv = new TreeView { Height = 200, Width = 480, Margin = new System.Windows.Thickness(0) };

            TreeViewItem CreateCheckNode(string text, bool? isChecked = false, bool isExpanded = false)
            {
                var item = new TreeViewItem { IsExpanded = isExpanded };
                var cb = new CheckBox
                {
                    Content = text,
                    IsChecked = isChecked,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    FontSize = 12.5,
                    Margin = new System.Windows.Thickness(2, 0, 0, 0)
                };
                item.Header = cb;
                return item;
