            var l1 = CreateCheckNode("Ground Floor Beams (Level 1)", true, true);
            l1.Items.Add(CreateCheckNode("Girder B101 (300x700)", true));
            l1.Items.Add(CreateCheckNode("Girder B102 (300x700)", true));
            l1.Items.Add(CreateCheckNode("Secondary Beam B103 (200x450)", false));

            var l2 = CreateCheckNode("First Floor Beams (Level 2)", false);
            l2.Items.Add(CreateCheckNode("Girder B201 (300x650)", false));
            l2.Items.Add(CreateCheckNode("Girder B202 (300x650)", false));

            root.Items.Add(l1);
            root.Items.Add(l2);
            tv.Items.Add(root);
            return tv;
        }

