        // ==============================================================================?
        // SECTION 2: Rich Card-Style ListBox
        // ==============================================================================?
        ListBox CreateCardListBox()
        {
            var lb = new ListBox
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.ListBox.Card"],
                Width = 540,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                SelectedIndex = 0,
                Margin = new System.Windows.Thickness(0)
            };

            ListBoxItem CreateCardItem(string title, string subtitle, IconKind icon, Brush iconBrush, string tag, string tagType)
            {
                var item = new ListBoxItem();
                var grid = new Grid();
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var iconBox = new Border
                {
                    Width = 36,
                    Height = 36,
                    CornerRadius = new System.Windows.CornerRadius(8),
                    Background = new SolidColorBrush(Color.FromArgb(20, 100, 116, 139)),
                    Margin = new System.Windows.Thickness(0, 0, 12, 0),
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var ico = new Icon { Kind = icon, Width = 18, Height = 18, HorizontalAlignment = System.Windows.HorizontalAlignment.Center, VerticalAlignment = System.Windows.VerticalAlignment.Center, Foreground = iconBrush };
                iconBox.Child = ico;
                Grid.SetColumn(iconBox, 0);
                grid.Children.Add(iconBox);

                var spText = new StackPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var txtTitle = new TextBlock { Text = title, FontWeight = System.Windows.FontWeights.Normal, FontSize = 13 };
                var txtSub = new TextBlock { Text = subtitle, FontSize = 11.5, Margin = new System.Windows.Thickness(0, 3, 0, 0) };
                txtSub.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                spText.Children.Add(txtTitle);
                spText.Children.Add(txtSub);
                Grid.SetColumn(spText, 1);
                grid.Children.Add(spText);

                var badge = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(4),
                    BorderThickness = new System.Windows.Thickness(1),
                    Padding = new System.Windows.Thickness(8, 3, 8, 3),
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var bTxt = new TextBlock { Text = tag, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal };
                if (tagType == "Success")
                {
                    badge.Background = new SolidColorBrush(Color.FromArgb(28, 16, 185, 129));
                    badge.BorderBrush = new SolidColorBrush(Color.FromArgb(80, 16, 185, 129));
                    bTxt.Foreground = new SolidColorBrush(Color.FromRgb(5, 150, 105));
                }
                else
                {
                    badge.Background = new SolidColorBrush(Color.FromArgb(28, 245, 158, 11));
                    badge.BorderBrush = new SolidColorBrush(Color.FromArgb(80, 245, 158, 11));
                    bTxt.Foreground = new SolidColorBrush(Color.FromRgb(180, 83, 9));
                }
                badge.Child = bTxt;
                Grid.SetColumn(badge, 2);
                grid.Children.Add(badge);

                item.Content = grid;
                return item;
            }

            var brushRuler = new SolidColorBrush(Color.FromRgb(5, 150, 105));
            var brushLayer = new SolidColorBrush(Color.FromRgb(37, 99, 235));

            lb.Items.Add(CreateCardItem("Girder D1 (300x600)", "Span 6.0m · Rebar 4D20 · Concrete B25", IconKind.Ruler, brushRuler, "Approved", "Success"));
            lb.Items.Add(CreateCardItem("Beam D2 (200x400)", "Span 4.5m · Rebar 3D16 · Concrete B25", IconKind.Ruler, brushRuler, "In Review", "Warning"));
            lb.Items.Add(CreateCardItem("Slab S1 (d=120mm)", "Area 24.5 m² · Rebar D10@150", IconKind.Layers, brushLayer, "Approved", "Success"));
            return lb;
        }

        string sec2Xaml =
@"<ListBox Style=""{DynamicResource CONCOST.ListBox.Card}"" Width=""540"" SelectedIndex=""0"" HorizontalAlignment=""Left"">
