        // ==============================================================================?
        // SECTION 3: Multi-Select CheckBox ListBox
        // ==============================================================================?
        ListBox CreateMultiCheckListBox()
        {
            var lb = new ListBox
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.ListBox.Base"],
                Width = 520,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                SelectionMode = SelectionMode.Multiple,
                Margin = new System.Windows.Thickness(0)
            };

            ListBoxItem CreateCheckItem(string label, bool isChecked)
            {
                var item = new ListBoxItem { IsSelected = isChecked };
                var cb = new CheckBox
                {
                    Content = label,
                    IsChecked = isChecked,
                    FontSize = 12.5,
                    IsHitTestVisible = false,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };

                item.Selected += (s, e) => cb.IsChecked = true;
                item.Unselected += (s, e) => cb.IsChecked = false;

                item.Content = cb;
                return item;
            }

            lb.Items.Add(CreateCheckItem("Bending Moment Check (M_u <= [M])", true));
            lb.Items.Add(CreateCheckItem("Shear Capacity Verification (V_u <= [V])", true));
            lb.Items.Add(CreateCheckItem("Deflection & Serviceability Limit (f_max <= [f])", false));
            lb.Items.Add(CreateCheckItem("Crack Width Control (a_crc <= 0.3mm)", true));
            return lb;
        }

        string sec3Xaml =
@"<ListBox Style=""{DynamicResource CONCOST.ListBox.Base}"" SelectionMode=""Multiple"" HorizontalAlignment=""Stretch"">
    <ListBoxItem>
        <CheckBox Content=""Bending Moment Check (M_u &lt;= [M])"" IsChecked=""True"" />
    </ListBoxItem>
    <ListBoxItem>
        <CheckBox Content=""Shear Capacity Verification (V_u &lt;= [V])"" IsChecked=""True"" />
    </ListBoxItem>
    <ListBoxItem>
        <CheckBox Content=""Deflection &amp; Serviceability Limit (f_max &lt;= [f])"" IsChecked=""False"" />
    </ListBoxItem>
    <ListBoxItem>
        <CheckBox Content=""Crack Width Control (a_crc &lt;= 0.3mm)"" IsChecked=""True"" />
    </ListBoxItem>
</ListBox>";

        AddCardSection("3. Multi-Select Criteria CheckBox ListBox", CreateMultiCheckListBox(), sec3Xaml);

        return mainSp;
    }

