    private object CreateMenuDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        MenuItem CreateSubItem(string header, IconKind? icon = null, string? shortcut = null)
        {
            var mi = new MenuItem { Header = header, InputGestureText = shortcut ?? string.Empty };
            if (icon.HasValue)
            {
                var ico = new Icon { Kind = icon.Value, Width = 14, Height = 14 };
                ico.SetBinding(Icon.ForegroundProperty, new System.Windows.Data.Binding(nameof(MenuItem.Foreground)) { Source = mi });
                mi.Icon = ico;
            }
            return mi;
        }

        // ==================== SECTION 1: Standard Application Main Menu Bar ====================
        Menu CreateStandardMenu()
        {
            var menu = new Menu
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Menu.Base"],
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                Margin = new System.Windows.Thickness(0)
            };

            // File Menu
            var mFile = new MenuItem { Header = "_File" };
            mFile.Items.Add(CreateSubItem("New Structural Project", IconKind.Folder, "Ctrl+N"));
            mFile.Items.Add(CreateSubItem("Open AutoCAD Drawing (.dwg)...", IconKind.Folder, "Ctrl+O"));
            mFile.Items.Add(CreateSubItem("Save Calculation Model", IconKind.Check, "Ctrl+S"));
            mFile.Items.Add(new Separator { Style = (System.Windows.Style)App.Current.Resources["CONCOST.MenuItem.Separator"] });
            mFile.Items.Add(CreateSubItem("Export PDF Design Report", IconKind.Layers, "Ctrl+P"));
            menu.Items.Add(mFile);

            // Edit Menu
            var mEdit = new MenuItem { Header = "_Edit" };
            mEdit.Items.Add(CreateSubItem("Undo Section Modification", IconKind.Close, "Ctrl+Z"));
            mEdit.Items.Add(CreateSubItem("Redo Action", IconKind.Check, "Ctrl+Y"));
            mEdit.Items.Add(new Separator { Style = (System.Windows.Style)App.Current.Resources["CONCOST.MenuItem.Separator"] });
            mEdit.Items.Add(CreateSubItem("Select All Beams & Columns", null, "Ctrl+A"));
            menu.Items.Add(mEdit);

            // Analysis Menu
            var mAnalysis = new MenuItem { Header = "_Analysis" };
            mAnalysis.Items.Add(CreateSubItem("Run 3D Frame Solver", IconKind.Search, "F5"));
            mAnalysis.Items.Add(CreateSubItem("Check P-Delta Secondary Effects", null, "Ctrl+F5"));
            mAnalysis.Items.Add(CreateSubItem("Dynamic Modal Eigenvalue Analysis", null, "Shift+F5"));
            menu.Items.Add(mAnalysis);

            // View Menu
            var mView = new MenuItem { Header = "_View" };
            mView.Items.Add(CreateSubItem("Show Bending Moment (M33)", null, "Alt+1"));
            mView.Items.Add(CreateSubItem("Show Shear Force Diagram (V22)", null, "Alt+2"));
            mView.Items.Add(CreateSubItem("Show Axial Thrust Force (N)", null, "Alt+3"));
            menu.Items.Add(mView);

            return menu;
        }

        string sec1Code =
@"<!-- Standard Application Main Menu Bar -->
<Menu Style=""{DynamicResource CONCOST.Menu.Base}"" HorizontalAlignment=""Left"">
    <MenuItem Header=""_File"">
        <MenuItem Header=""New Structural Project"" InputGestureText=""Ctrl+N"">
            <MenuItem.Icon><icons:Icon Kind=""Folder"" Width=""14"" Height=""14"" /></MenuItem.Icon>
        </MenuItem>
        <MenuItem Header=""Save Calculation Model"" InputGestureText=""Ctrl+S"" />
        <Separator Style=""{DynamicResource CONCOST.MenuItem.Separator}"" />
        <MenuItem Header=""Export PDF Design Report"" InputGestureText=""Ctrl+P"" />
    </MenuItem>
    <MenuItem Header=""_Edit"">
        <MenuItem Header=""Undo Section Modification"" InputGestureText=""Ctrl+Z"" />
        <MenuItem Header=""Redo Action"" InputGestureText=""Ctrl+Y"" />
    </MenuItem>
    <MenuItem Header=""_Analysis"">
        <MenuItem Header=""Run 3D Frame Solver"" InputGestureText=""F5"" />
    </MenuItem>
</Menu>";

        AddCardSection("1. Standard Application Main Menu Bar", CreateStandardMenu(), sec1Code);

        // ==================== SECTION 2: Modern Floating Pill NavMenu ====================
        Menu CreatePillMenu()
        {
            var menu = new Menu
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Menu.ModernPill"],
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                Margin = new System.Windows.Thickness(0)
            };

            var m1 = new MenuItem { Header = "Dashboard" };
            var m2 = new MenuItem { Header = "Model Geometry" };
            m2.Items.Add(CreateSubItem("Grid Layout & Levels", IconKind.Layers));
            m2.Items.Add(CreateSubItem("Beam & Column Sections", IconKind.Ruler));
            var m3 = new MenuItem { Header = "Loads & Combos" };
            var m4 = new MenuItem { Header = "Verification" };
            var m5 = new MenuItem { Header = "Reports & BOQ" };

            menu.Items.Add(m1);
            menu.Items.Add(m2);
            menu.Items.Add(m3);
            menu.Items.Add(m4);
            menu.Items.Add(m5);

            return menu;
        }

        string sec2Code =
@"<!-- Modern Floating Pill NavMenu -->
<Menu Style=""{DynamicResource CONCOST.Menu.ModernPill}"" HorizontalAlignment=""Left"">
    <MenuItem Header=""Dashboard"" />
    <MenuItem Header=""Model Geometry"">
        <MenuItem Header=""Grid Layout &amp; Levels"" />
        <MenuItem Header=""Beam &amp; Column Sections"" />
    </MenuItem>
    <MenuItem Header=""Loads &amp; Combos"" />
    <MenuItem Header=""Verification"" />
    <MenuItem Header=""Reports &amp; BOQ"" />
</Menu>";

        AddCardSection("2. Modern Floating Pill NavMenu (Command Bar)", CreatePillMenu(), sec2Code);

        // ==================== SECTION 3: Interactive Right-Click ContextMenu ====================
        var sec3Card = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(24, 20, 24, 20),
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left
        };
        sec3Card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sec3Card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var cm = new ContextMenu { Style = (System.Windows.Style)App.Current.Resources["CONCOST.ContextMenu.Card"] };
        cm.Items.Add(CreateSubItem("Copy Member Properties", IconKind.Check, "Ctrl+C"));
        cm.Items.Add(CreateSubItem("Paste Detailing Rules", IconKind.Edit, "Ctrl+V"));
        cm.Items.Add(new Separator { Style = (System.Windows.Style)App.Current.Resources["CONCOST.MenuItem.Separator"] });
        cm.Items.Add(CreateSubItem("Redesign Longitudinal Rebar", IconKind.Ruler, "Alt+D"));
        cm.Items.Add(CreateSubItem("Delete Selected Elements", IconKind.Close, "Del"));

        sec3Card.ContextMenu = cm;

        var cmContent = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
        var cmIcon = new Icon { Kind = IconKind.Edit, Width = 16, Height = 16, Margin = new System.Windows.Thickness(0, 0, 10, 0), Foreground = (Brush)App.Current.Resources["CONCOST.Brush.Primary"] };
        var cmText = new TextBlock { Text = "Right-click anywhere inside this card to open the Modern ContextMenu", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13 };
        cmText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        cmContent.Children.Add(cmIcon);
        cmContent.Children.Add(cmText);
        sec3Card.Child = cmContent;

        string sec3Code =
@"<!-- Elevated Card ContextMenu -->
<Border Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"" CornerRadius=""8"" Padding=""24,20"">
