        // ==============================================================================?
        // SECTION 1: CornerRadius Design Tokens
        // ==============================================================================?
        System.Windows.UIElement CreateCornerRadiusTokensDemo()
        {
            var wp = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0) };

            Border CreateTokenBox(string name, string radiusVal, int radius)
            {
                var b = new Border
                {
                    Width = 145,
                    Height = 72,
                    CornerRadius = new System.Windows.CornerRadius(radius),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 0, 12, 10),
                    Padding = new System.Windows.Thickness(10)
                };
                b.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var spInner = new StackPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tName = new TextBlock { Text = name, FontWeight = System.Windows.FontWeights.Normal, FontSize = 12.5 };
                tName.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                var tVal = new TextBlock { Text = radiusVal, FontSize = 11, Margin = new System.Windows.Thickness(0, 2, 0, 0) };
                tVal.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                spInner.Children.Add(tName);
                spInner.Children.Add(tVal);
                b.Child = spInner;
                return b;
            }

            wp.Children.Add(CreateTokenBox("Small", "Radius: 4px", 4));
            wp.Children.Add(CreateTokenBox("Medium", "Radius: 8px", 8));
            wp.Children.Add(CreateTokenBox("Large", "Radius: 12px", 12));
            wp.Children.Add(CreateTokenBox("Pill / Round", "Radius: 24px", 24));
            return wp;
        }

