                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================
        // VARIANT 1: Base / Standard Style
        // =========================================================================
        System.Windows.UIElement CreateStandardBreadcrumb()
        {
            var sp = new StackPanel { HorizontalAlignment = System.Windows.HorizontalAlignment.Left };
            
            var desc = new TextBlock 
            { 
                Text = "Standard hierarchical path for structural engineering project navigation:",
                Margin = new System.Windows.Thickness(0, 0, 0, 12),
                FontSize = 12.5
            };
            desc.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            sp.Children.Add(desc);

            var bc = new Breadcrumb 
            { 
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Breadcrumb.Base"] 
            };
            bc.Items.Add(new BreadcrumbItem { Header = "High-Rise Commercial Tower" });
            bc.Items.Add(new BreadcrumbItem { Header = "Reinforced Concrete Subsystem" });
            bc.Items.Add(new BreadcrumbItem { Header = "Level 02 (+7.200m)" });
            bc.Items.Add(new BreadcrumbItem { Header = "Frame Girder G1 (300x600)" });
            sp.Children.Add(bc);

            return sp;
        }

