        <controls:BreadcrumbItem Header=""Frame Girder G1 (300x600)"" />
    </controls:Breadcrumb.Items>
</controls:Breadcrumb>";

        AddCardSection("1. Standard Structural Hierarchy Breadcrumb", CreateStandardBreadcrumb(), sec1Xaml);

