        System.Windows.UIElement CreateBaseEmptyState()
        {
            return new EmptyState
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.EmptyState.Base"],
                Icon = IconKind.Folder,
                Title = "No Structural Model Loaded",
                Description = "Select a calculation sheet from the left project tree or import an analysis model to view structural schedules.",
                Padding = new System.Windows.Thickness(20)
            };
