        AddCardSection("2. Actionable Empty State with Call-to-Action Button", CreateActionEmptyState(), sec2Xaml);

        // =========================================================================
        // VARIANT 3: Compact Inline EmptyState for Data Grids & Tables
        // =========================================================================
        System.Windows.UIElement CreateCompactEmptyState()
        {
            var sp = new StackPanel { MaxWidth = 560, HorizontalAlignment = System.Windows.HorizontalAlignment.Left };

            var es1 = new EmptyState
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.EmptyState.Compact"],
                Icon = IconKind.Layers,
                Title = "No Failed Structural Members",
                Description = "All 124 reinforced concrete beams and columns satisfied ULS & SLS design checks.",
                Margin = new System.Windows.Thickness(0, 0, 0, 10)
            };
            sp.Children.Add(es1);

            var es2 = new EmptyState
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.EmptyState.Compact"],
                Icon = IconKind.Warning,
                Title = "No Warning Notices or Compliance Issues",
                Description = "Deflection limits and minimum reinforcement ratios meet TCVN 5574:2018 requirements."
            };
            sp.Children.Add(es2);

            return sp;
        }

        string sec3Xaml = @"<StackPanel Width=""560"" HorizontalAlignment=""Left"">
    <controls:EmptyState Style=""{DynamicResource CONCOST.EmptyState.Compact}""
                         Icon=""Layers""
                         Title=""No Failed Structural Members""
                         Description=""All 124 reinforced concrete beams and columns satisfied ULS &amp; SLS design checks.""
                         Margin=""0,0,0,10"" />
    <controls:EmptyState Style=""{DynamicResource CONCOST.EmptyState.Compact}""
                         Icon=""Warning""
                         Title=""No Warning Notices or Compliance Issues""
                         Description=""Deflection limits and minimum reinforcement ratios meet TCVN 5574:2018 requirements."" />
</StackPanel>";

        AddCardSection("3. Compact Inline Empty State for Tables & Reports", CreateCompactEmptyState(), sec3Xaml);

        return mainSp;
    }


