        // ==============================================================================?
        // SECTION 1: Interactive Live-Filter Structural Schedule
        // ==============================================================================?
        System.Windows.UIElement CreateBaseSearchBox()
        {
            var container = new StackPanel { HorizontalAlignment = System.Windows.HorizontalAlignment.Left };

            var searchBox = new SearchBox
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.SearchBox.Base"],
                Placeholder = "Type to live filter beam schedules (e.g. D1, 300x600, B25, CB400)...",
                Text = "D1",
                Width = 520,
                Margin = new System.Windows.Thickness(0, 0, 0, 10)
            };

            var items = new (string Code, string Section, string Rebar, string Concrete, string Status)[]
            {
                ("Girder D1-Floor 2", "300x600", "4D20 Top + 3D20 Bot", "B25", "Passed (ULS: 82%)"),
                ("Girder D1-Floor 3", "300x600", "4D20 Top + 3D20 Bot", "B25", "Passed (ULS: 84%)"),
                ("Girder D1-Floor 4", "300x600", "4D22 Top + 4D20 Bot", "B30", "Passed (ULS: 78%)"),
                ("Column C1-Level 1", "400x400", "8D25 All Faces", "B30", "Passed (Axial: 65%)"),
                ("Secondary Beam B2", "200x400", "2D16 Top + 2D16 Bot", "B20", "Deflection Limit: L/450"),
                ("Transfer Girder TG1", "600x1200", "12D25 Top + 10D25 Bot", "B40", "Passed (ULS: 91%)")
            };

            var resultCard = new Border
            {
                Width = 520,
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(6),
                Padding = new System.Windows.Thickness(10),
                ClipToBounds = true
            };
            resultCard.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            resultCard.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var resultsPanel = new StackPanel();

            void UpdateFilteredResults(string query)
            {
                resultsPanel.Children.Clear();
                var q = (query ?? string.Empty).Trim().ToLowerInvariant();
                var filtered = items.Where(x => string.IsNullOrEmpty(q) ||
                                               x.Code.ToLowerInvariant().Contains(q) ||
                                               x.Section.ToLowerInvariant().Contains(q) ||
                                               x.Concrete.ToLowerInvariant().Contains(q) ||
                                               x.Rebar.ToLowerInvariant().Contains(q)).ToList();

                var countLabel = new TextBlock
                {
                    Text = $"Showing {filtered.Count} of {items.Length} structural items:",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    Margin = new System.Windows.Thickness(0, 0, 0, 6)
                };
                countLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                resultsPanel.Children.Add(countLabel);

                if (filtered.Count == 0)
                {
                    var emptyText = new TextBlock
                    {
                        Text = "No structural elements match your search keyword.",
                        FontSize = 12,
                        Margin = new System.Windows.Thickness(0, 4, 0, 4)
                    };
                    emptyText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Danger");
                    resultsPanel.Children.Add(emptyText);
                }
                else
                {
                    foreach (var item in filtered)
                    {
                        var row = new Grid { Margin = new System.Windows.Thickness(0, 3, 0, 3) };
                        row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(160) });
                        row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(90) });
                        row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

                        var c1 = new TextBlock { Text = item.Code, FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
                        c1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
                        Grid.SetColumn(c1, 0); row.Children.Add(c1);

                        var c2 = new TextBlock { Text = item.Section, FontSize = 11.5 };
                        c2.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                        Grid.SetColumn(c2, 1); row.Children.Add(c2);

                        var c3 = new TextBlock { Text = $"{item.Rebar} ({item.Status})", FontSize = 11.5 };
                        c3.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                        Grid.SetColumn(c3, 2); row.Children.Add(c3);

                        resultsPanel.Children.Add(row);
                    }
                }
            }

            searchBox.SearchStarted += (s, e) => UpdateFilteredResults(searchBox.Text);
            searchBox.Clear += (s, e) => UpdateFilteredResults(string.Empty);
            UpdateFilteredResults(searchBox.Text);

            resultCard.Child = resultsPanel;
            container.Children.Add(searchBox);
            container.Children.Add(resultCard);

            return container;
        }

        string sec1Xaml =
@"<!-- SearchBox integrated with Real-Time Filter Event Handlers -->
<StackPanel>
    <controls:SearchBox Style=""{DynamicResource CONCOST.SearchBox.Base}""
                        Placeholder=""Type to live filter beam schedules...""
                        Text=""Girder D1""
                        SearchStarted=""SearchBox_SearchStarted""
                        Clear=""SearchBox_Clear""
                        Width=""520"" />

    <!-- Live filtered structural target data list -->
    <Border Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"" CornerRadius=""6"" Padding=""10"" Margin=""0,10,0,0"">
        <ItemsControl ItemsSource=""{Binding FilteredStructuralBeams}"" />
    </Border>
</StackPanel>";

        AddCardSection("1. Interactive Live-Filtering SearchBox with Quick Clear", CreateBaseSearchBox(), sec1Xaml);

