        // ==============================================================================?
        // SECTION 1: Interactive Data Pagination with Live Page Switcher
        // ==============================================================================?
        System.Windows.UIElement CreateBasePagination()
        {
            var container = new StackPanel { HorizontalAlignment = System.Windows.HorizontalAlignment.Left };

            var pagination = new Pagination
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Pagination.Base"],
                CurrentPage = 1,
                MaxPage = 5,
                TotalItems = 25,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
                Margin = new System.Windows.Thickness(0, 12, 0, 0)
            };

            var dataCard = new Border
            {
                Width = 540,
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(6),
                Padding = new System.Windows.Thickness(10),
                ClipToBounds = true
            };
            dataCard.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            dataCard.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var listPanel = new StackPanel();

            void UpdatePageData(int page)
            {
                listPanel.Children.Clear();

                var header = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 8) };
                header.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(140) });
                header.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(120) });
                header.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

                var h1 = new TextBlock { Text = "Member ID", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
                h1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var h2 = new TextBlock { Text = "Rebar Area (As)", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
                h2.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                Grid.SetColumn(h2, 1); header.Children.Add(h2);

                var h3 = new TextBlock { Text = "Bending Capacity", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
                h3.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                Grid.SetColumn(h3, 2); header.Children.Add(h3);

                listPanel.Children.Add(header);

                int startIdx = (page - 1) * 5 + 1;
                for (int i = 0; i < 5; i++)
                {
                    int itemNum = startIdx + i;
                    var row = new Grid { Margin = new System.Windows.Thickness(0, 3, 0, 3) };
                    row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(140) });
                    row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(120) });
                    row.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

                    var r1 = new TextBlock { Text = $"Beam-Level-{page}-B{itemNum}", FontWeight = System.Windows.FontWeights.Normal, FontSize = 12 };
                    r1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
                    Grid.SetColumn(r1, 0); row.Children.Add(r1);

                    var r2 = new TextBlock { Text = $"{1200 + itemNum * 45:N0} mm²", FontSize = 11.5 };
                    r2.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                    Grid.SetColumn(r2, 1); row.Children.Add(r2);

                    var r3 = new TextBlock { Text = $"Mu = {245.5 + itemNum * 8.2:F1} kN.m", FontSize = 11.5 };
                    r3.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                    Grid.SetColumn(r3, 2); row.Children.Add(r3);

                    listPanel.Children.Add(row);
                }
            }

            pagination.PageChanged += (s, e) => UpdatePageData(pagination.CurrentPage);
            UpdatePageData(1);

            dataCard.Child = listPanel;
            container.Children.Add(dataCard);
            container.Children.Add(pagination);

            return container;
        }

        string sec1Xaml =
@"<!-- Pagination Bound to Master Data Collection View -->
<StackPanel>
    <Border Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"" CornerRadius=""6"" Padding=""10"">
        <ItemsControl ItemsSource=""{Binding PagedStructuralItems}"" />
    </Border>

    <controls:Pagination Style=""{DynamicResource CONCOST.Pagination.Base}""
                         CurrentPage=""{Binding CurrentPage, Mode=TwoWay}""
                         MaxPage=""5""
                         TotalItems=""25""
                         PageChanged=""Pagination_PageChanged""
                         Margin=""0,12,0,0""
                         HorizontalAlignment=""Left"" />
</StackPanel>";

        AddCardSection("1. Interactive Structural Calculation Ledger with Live Pagination", CreateBasePagination(), sec1Xaml);

        // -------------------------------------------------------------
        // SECTION 2: Floating Card Pagination
        // -------------------------------------------------------------
        Pagination CreateCardPagination()
        {
            return new Pagination
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Pagination.Card"],
                CurrentPage = 1,
                MaxPage = 12,
                TotalItems = 120,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left
            };
        }

        string sec2Xaml =
@"<controls:Pagination Style=""{DynamicResource CONCOST.Pagination.Card}""
                     CurrentPage=""1""
                     MaxPage=""12""
                     TotalItems=""120""
                     HorizontalAlignment=""Left"" />";

        AddCardSection("2. Inset Card Floating Pagination", CreateCardPagination(), sec2Xaml);

        // -------------------------------------------------------------
        // SECTION 3: Compact Minimalist Pagination
        // -------------------------------------------------------------
        Pagination CreateCompactPagination()
        {
            return new Pagination
            {
                Style = (System.Windows.Style)App.Current.Resources["CONCOST.Pagination.Compact"],
                CurrentPage = 8,
                MaxPage = 40,
                TotalItems = 400,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left
            };
        }

        string sec3Xaml =
@"<controls:Pagination Style=""{DynamicResource CONCOST.Pagination.Compact}""
                     CurrentPage=""8""
                     MaxPage=""40""
                     TotalItems=""400""
                     HorizontalAlignment=""Left"" />";

        AddCardSection("3. Compact Minimalist Pagination for Toolbars", CreateCompactPagination(), sec3Xaml);

        return mainSp;
    }

