            {
                Margin = new System.Windows.Thickness(10, 0, 0, 0),
                CornerRadius = new System.Windows.CornerRadius(8),
                Padding = new System.Windows.Thickness(12)
            };
            donutBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");

            var donutStack = new StackPanel();
            var donutTitle = new TextBlock { Text = "Project Phase Budget (Donut Ring)", FontWeight = System.Windows.FontWeights.Normal, FontSize = 13, Margin = new System.Windows.Thickness(4, 0, 0, 10) };
            donutTitle.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
