            b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var wm = new Watermark
            {
                Text = "PRELIMINARY DRAFT - NOT FOR CONSTRUCTION",
                Angle = -15.0,
                MarkFontSize = 26
            };

            var docPanel = new StackPanel { Margin = new System.Windows.Thickness(20), VerticalAlignment = System.Windows.VerticalAlignment.Center };
            var t1 = new TextBlock { Text = "Structural Calculation Sheet No. 402 - Level 12 Transfer Girder", FontWeight = System.Windows.FontWeights.Normal, FontSize = 14, HorizontalAlignment = System.Windows.HorizontalAlignment.Center };
            t1.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
