            <GridViewColumn Header=""Bottom Bars"" DisplayMemberBinding=""{Binding BotRebar}"" Width=""100"" />
            <GridViewColumn Header=""Stirrups"" DisplayMemberBinding=""{Binding Stirrups}"" Width=""100"" />
            <GridViewColumn Header=""Status"" DisplayMemberBinding=""{Binding Status}"" Width=""130"" />
