                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11.5,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================================
        // SECTION 1: Standard Multi-Select Project Stories Filter
        // =========================================================================================
        StackPanel CreateBaseSection()
        {
            var container = new StackPanel();

            var row = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            var lbl = new TextBlock { Text = "Target Project Stories:", Width = 220, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            lbl.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

            var stories = new[] { "Foundation Basement B2", "Basement B1", "Ground Level L1", "Level 2 Floor Framing", "Level 3 Floor Framing", "Roof Terrace" };
            var ccb = new CheckComboBox
            {
                ItemsSource = stories,
                Placeholder = "Select project stories...",
                SelectedItemsPreviewMaxWidth = 500,
                Width = 280,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Left
            };

            var selectAllBtn = new Button
            {
                Content = "Select All",
                Padding = new System.Windows.Thickness(10, 4, 10, 4),
                Margin = new System.Windows.Thickness(12, 0, 6, 0),
                FontSize = 11.5,
                Cursor = System.Windows.Input.Cursors.Hand
            };
            selectAllBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            selectAllBtn.Click += (s, e) => ccb.SelectAll();

            var clearBtn = new Button
            {
                Content = "Clear All",
                Padding = new System.Windows.Thickness(10, 4, 10, 4),
                FontSize = 11.5,
                Cursor = System.Windows.Input.Cursors.Hand
            };
            clearBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            clearBtn.Click += (s, e) => ccb.UnselectAll();

            row.Children.Add(lbl);
            row.Children.Add(ccb);
            row.Children.Add(selectAllBtn);
            row.Children.Add(clearBtn);
            container.Children.Add(row);

            var statusBlock = new TextBlock
            {
                Text = "Current Selection: (None)",
                FontSize = 12,
                Margin = new System.Windows.Thickness(220, 8, 0, 0),
                TextTrimming = TextTrimming.CharacterEllipsis
            };
            statusBlock.SetBinding(FrameworkElement.MaxWidthProperty, new Binding(nameof(CheckComboBox.SelectedItemsPreviewMaxWidth)) { Source = ccb });
            statusBlock.SetBinding(FrameworkElement.ToolTipProperty, new Binding(nameof(CheckComboBox.SelectedValue)) { Source = ccb });
            statusBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextTertiary");
            ccb.SelectionChanged += (s, e) =>
            {
                if (string.IsNullOrEmpty(ccb.SelectedValue))
                {
                    statusBlock.Text = "Current Selection: (None)";
                    statusBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextTertiary");
                }
                else
                {
                    statusBlock.Text = $"Current Selection: {ccb.SelectedValue} ({ccb.SelectedItems.Count} items selected)";
                    statusBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
                }
            };
            container.Children.Add(statusBlock);

            return container;
        }

        string sec1Code =
@"<!-- ==================== XAML MARKUP ==================== -->
<StackPanel Orientation=""Horizontal"">
    <TextBlock Text=""Target Project Stories:"" Width=""220"" Foreground=""{DynamicResource CONCOST.Brush.TextSecondary}"" VerticalAlignment=""Center"" />
    <controls:CheckComboBox Style=""{DynamicResource CONCOST.CheckComboBox.Base}""
                            ItemsSource=""{Binding ProjectStories}""
                            Placeholder=""Select project stories...""
                            SelectedValue=""{Binding SelectedStories, Mode=TwoWay}""
                            SelectedItemsPreviewMaxWidth=""500""
                            Width=""280"" />
</StackPanel>

