        // =========================================================================================
    // PINBOX DEMO
    // =========================================================================================
    private object CreatePinBoxDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11.5,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Standard 4-Digit License PIN
        var pb1 = new PinBox { Length = 4, Password = "8492", HorizontalAlignment = System.Windows.HorizontalAlignment.Left };
        string sec1Xaml = @"<controls:PinBox Style=""{DynamicResource CONCOST.PinBox.Base}"" Length=""4"" Password=""8492"" />";
        AddCardSection("1. 4-Digit License Activation PIN Input", pb1, sec1Xaml);

        // Section 2: 6-Digit Rounded Pill Cloud MFA
        var pb2 = new PinBox { Style = (System.Windows.Style)App.Current.Resources["CONCOST.PinBox.Rounded"], Length = 6, Password = "491820", HorizontalAlignment = System.Windows.HorizontalAlignment.Left };
        string sec2Xaml = @"<controls:PinBox Style=""{DynamicResource CONCOST.PinBox.Rounded}"" Length=""6"" Password=""491820"" />";
        AddCardSection("2. 6-Digit Rounded Pill Cloud Sync MFA Input", pb2, sec2Xaml);

        // Section 3: Password Masked Security PIN
        var pb3 = new PinBox { Style = (System.Windows.Style)App.Current.Resources["CONCOST.PinBox.Password"], Length = 4, Password = "5500", HorizontalAlignment = System.Windows.HorizontalAlignment.Left };
        string sec3Xaml = @"<controls:PinBox Style=""{DynamicResource CONCOST.PinBox.Password}"" Length=""4"" Password=""5500"" />";
        AddCardSection("3. Secret Approval Passcode (Masked)", pb3, sec3Xaml);

        return mainSp;
    }

