    // =========================================================================================
    // =========================================================================================
    // =========================================================================================
    // GROWL DEMO
    // =========================================================================================
    private object CreateGrowlDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            TextBox? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                codeBox = new TextBox
                {
                    Text = xamlSnippet,
                    IsReadOnly = true,
                    AcceptsReturn = true,
                    FontFamily = new System.Windows.Media.FontFamily("Consolas"),
                    FontSize = 12,
                    Padding = new System.Windows.Thickness(12),
                    Margin = new System.Windows.Thickness(0, 12, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(TextBox.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(TextBox.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBox.SetResourceReference(TextBox.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBtn = new Button
                {
                    Content = "Show C# / XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11.5
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "Show C# / XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide C# / XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Window Scope GroupBox
        var winGroupBox = new GroupBox
        {
            Header = "Window",
            Padding = new System.Windows.Thickness(12, 10, 12, 10),
            Margin = new System.Windows.Thickness(0, 0, 0, 14)
        };
        winGroupBox.SetResourceReference(GroupBox.StyleProperty, "CONCOST.GroupBox.Base");

        var winBtnWrap = new WrapPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center };

        var wInfo = new Button { Content = "Info", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wInfo.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Info");
        wInfo.Click += (s, e) => Growl.Info("BIM synchronization background service is running.");

        var wSuccess = new Button { Content = "Success", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wSuccess.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Success");
        wSuccess.Click += (s, e) => Growl.Success("Rebar schedule successfully exported to Excel!");

        var wWarning = new Button { Content = "Warning", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wWarning.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Warning");
        wWarning.Click += (s, e) => Growl.Warning("Column axial ratio exceeds permissible limit.");

        var wError = new Button { Content = "Error", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wError.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Danger");
        wError.Click += (s, e) => Growl.Error("Failed to connect to BIM Server #408.");

        var wAsk = new Button { Content = "Ask", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wAsk.Background = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#8B5CF6"));
        wAsk.Foreground = System.Windows.Media.Brushes.White;
        wAsk.BorderThickness = new System.Windows.Thickness(0);
        wAsk.FontWeight = System.Windows.FontWeights.Normal;
        wAsk.Click += (s, e) => Growl.Ask("Are you sure you want to recalculate foundation forces?", () => Growl.Success("Recalculation started!"));

        var wFatal = new Button { Content = "Fatal", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wFatal.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        wFatal.Click += (s, e) => Growl.Fatal("Fatal crash intercepted in calculation module!");

        var wClear = new Button { Content = "Clear", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        wClear.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        wClear.Click += (s, e) => Growl.Clear();

        winBtnWrap.Children.Add(wInfo);
        winBtnWrap.Children.Add(wSuccess);
        winBtnWrap.Children.Add(wWarning);
        winBtnWrap.Children.Add(wError);
        winBtnWrap.Children.Add(wAsk);
        winBtnWrap.Children.Add(wFatal);
        winBtnWrap.Children.Add(wClear);
        winGroupBox.Content = winBtnWrap;

        // Desktop Scope GroupBox
        var deskGroupBox = new GroupBox
        {
            Header = "Desktop",
            Padding = new System.Windows.Thickness(12, 10, 12, 10),
            Margin = new System.Windows.Thickness(0, 0, 0, 0)
        };
        deskGroupBox.SetResourceReference(GroupBox.StyleProperty, "CONCOST.GroupBox.Base");

        var deskBtnWrap = new WrapPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center };

        var dInfo = new Button { Content = "Info", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dInfo.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Info");
        dInfo.Click += (s, e) => Growl.InfoGlobal("Global Desktop Notification: Server sync active.");

        var dSuccess = new Button { Content = "Success", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dSuccess.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Success");
        dSuccess.Click += (s, e) => Growl.SuccessGlobal("Global Desktop Notification: IFC export finished!");

        var dWarning = new Button { Content = "Warning", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dWarning.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Warning");
        dWarning.Click += (s, e) => Growl.WarningGlobal("Global Desktop Notification: High memory usage.");

        var dError = new Button { Content = "Error", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dError.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Danger");
        dError.Click += (s, e) => Growl.ErrorGlobal("Global Desktop Notification: Licensing server timeout.");

        var dAsk = new Button { Content = "Ask", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dAsk.Background = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#8B5CF6"));
        dAsk.Foreground = System.Windows.Media.Brushes.White;
        dAsk.BorderThickness = new System.Windows.Thickness(0);
        dAsk.FontWeight = System.Windows.FontWeights.Normal;
        dAsk.Click += (s, e) => Growl.AskGlobal("Global: Save backup before updating plugin?", () => Growl.SuccessGlobal("Backup saved!"));

        var dFatal = new Button { Content = "Fatal", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dFatal.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        dFatal.Click += (s, e) => Growl.FatalGlobal("Global Desktop Notification: Fatal Crash avoided.");

        var dClear = new Button { Content = "Clear", Margin = new System.Windows.Thickness(0, 4, 8, 4), Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        dClear.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        dClear.Click += (s, e) => Growl.ClearGlobal();

        deskBtnWrap.Children.Add(dInfo);
        deskBtnWrap.Children.Add(dSuccess);
        deskBtnWrap.Children.Add(dWarning);
        deskBtnWrap.Children.Add(dError);
        deskBtnWrap.Children.Add(dAsk);
        deskBtnWrap.Children.Add(dFatal);
        deskBtnWrap.Children.Add(dClear);
        deskGroupBox.Content = deskBtnWrap;

        var fullDemoStack = new StackPanel();
        fullDemoStack.Children.Add(winGroupBox);
        fullDemoStack.Children.Add(deskGroupBox);

        string demoXaml = @"<!-- Window Scope -->
<hc:GroupBox Header=""Window"">
    <WrapPanel>
        <Button Content=""Info"" Style=""{DynamicResource CONCOST.Button.Info}"" />
        <Button Content=""Success"" Style=""{DynamicResource CONCOST.Button.Success}"" />
        <Button Content=""Warning"" Style=""{DynamicResource CONCOST.Button.Warning}"" />
        <Button Content=""Error"" Style=""{DynamicResource CONCOST.Button.Danger}"" />
        <Button Content=""Ask"" Background=""#8B5CF6"" />
        <Button Content=""Fatal"" Style=""{DynamicResource CONCOST.Button.Secondary}"" />
        <Button Content=""Clear"" Style=""{DynamicResource CONCOST.Button.Primary}"" />
    </WrapPanel>
</hc:GroupBox>

<!-- Desktop Scope -->
<hc:GroupBox Header=""Desktop"">
    <WrapPanel>
        <Button Content=""Info"" Click=""Growl.InfoGlobal(...)"" />
        <Button Content=""Success"" Click=""Growl.SuccessGlobal(...)"" />
    </WrapPanel>
</hc:GroupBox>";

        AddCardSection("Interactive Growl Notification Console", fullDemoStack, demoXaml);

        return mainSp;
    }

    private object CreateDrawerDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            TextBox? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                codeBox = new TextBox
                {
                    Text = xamlSnippet,
                    IsReadOnly = true,
                    AcceptsReturn = true,
                    FontFamily = new System.Windows.Media.FontFamily("Consolas"),
                    FontSize = 12,
                    Padding = new System.Windows.Thickness(12),
                    Margin = new System.Windows.Thickness(0, 12, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(TextBox.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(TextBox.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBox.SetResourceReference(TextBox.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBtn = new Button
                {
                    Content = "Show C# / XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 11.5
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "Show C# / XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide C# / XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Host Grid with 4-way Container Drawer & Window Drawer
        var hostGrid = new Grid { Height = 400, ClipToBounds = true };
        var bgBorder = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(20)
        };
        bgBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        bgBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        // Center Matrix Controls
        var centerGrid = new Grid { VerticalAlignment = System.Windows.VerticalAlignment.Center, HorizontalAlignment = System.Windows.HorizontalAlignment.Center };
        centerGrid.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        centerGrid.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(40) });
        centerGrid.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });
        centerGrid.RowDefinitions.Add(new RowDefinition { Height = new System.Windows.GridLength(40) });
        centerGrid.RowDefinitions.Add(new RowDefinition { Height = System.Windows.GridLength.Auto });

        centerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });
        centerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(60) });
        centerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });
        centerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(60) });
        centerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

        // Drawer component
        var drawer = new Drawer
        {
            Title = "Drawer Inspector",
            DrawerWidth = 320,
            DrawerHeight = 220,
            Placement = DrawerPlacement.Right
        };

        var drawerContent = new StackPanel { Margin = new System.Windows.Thickness(16) };
        var statusLabel = new TextBlock { Text = "Configuration & Parameters Sheet", FontSize = 13, FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 12) };
        statusLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        drawerContent.Children.Add(statusLabel);

        var sampleBox1 = new TextBox { Text = "Rebar Yield Strength fy: 500 MPa", Height = 32, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        sampleBox1.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Base");
        var sampleBox2 = new TextBox { Text = "Concrete Compressive f'c: 35 MPa", Height = 32, Margin = new System.Windows.Thickness(0, 0, 0, 14) };
        sampleBox2.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Base");
        drawerContent.Children.Add(sampleBox1);
        drawerContent.Children.Add(sampleBox2);

        var closeDrawerBtn = new Button { Content = "Close Drawer", Padding = new System.Windows.Thickness(14, 6, 14, 6) };
        closeDrawerBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        closeDrawerBtn.Click += (s, e) => drawer.IsOpen = false;
        drawerContent.Children.Add(closeDrawerBtn);

        drawer.Content = drawerContent;

        void OpenDrawer(string title, DrawerPlacement placement)
        {
            drawer.Title = title;
            drawer.Placement = placement;
            drawer.IsOpen = true;
        }

        Button CreatePairBtn(string text, Action action)
        {
            var btn = new Button
            {
                Content = text,
                Padding = new System.Windows.Thickness(12, 6, 12, 6),
                FontSize = 12
            };
            btn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            btn.Click += (s, e) => action();
            return btn;
        }

        // Top Row (Top-Container)
        var topPair = new StackPanel { Orientation = Orientation.Horizontal };
        var topWin = CreatePairBtn("Top-Windows", () => OpenDrawer("Top Drawer (Window)", DrawerPlacement.Top));
        var topCont = CreatePairBtn("Top-Container", () => OpenDrawer("Top Drawer (Container)", DrawerPlacement.Top));
        topWin.Margin = new System.Windows.Thickness(0, 0, 4, 0);
        topPair.Children.Add(topWin);
        topPair.Children.Add(topCont);
        Grid.SetRow(topPair, 0);
        Grid.SetColumn(topPair, 2);
        centerGrid.Children.Add(topPair);

        // Middle Row (Left & Right)
        var leftPair = new StackPanel { Orientation = Orientation.Horizontal };
        var leftWin = CreatePairBtn("Left-Window", () => OpenDrawer("Left Drawer (Window)", DrawerPlacement.Left));
        var leftCont = CreatePairBtn("Left-Container", () => OpenDrawer("Left Drawer (Container)", DrawerPlacement.Left));
        leftWin.Margin = new System.Windows.Thickness(0, 0, 4, 0);
        leftPair.Children.Add(leftWin);
        leftPair.Children.Add(leftCont);
        Grid.SetRow(leftPair, 2);
        Grid.SetColumn(leftPair, 0);
        centerGrid.Children.Add(leftPair);

        var rightPair = new StackPanel { Orientation = Orientation.Horizontal };
        var rightWin = CreatePairBtn("Right-Windows", () => OpenDrawer("Right Drawer (Windows)", DrawerPlacement.Right));
        var rightCont = CreatePairBtn("Right-Container", () => OpenDrawer("Right Drawer (Container)", DrawerPlacement.Right));
        rightWin.Margin = new System.Windows.Thickness(0, 0, 4, 0);
        rightPair.Children.Add(rightWin);
        rightPair.Children.Add(rightCont);
        Grid.SetRow(rightPair, 2);
        Grid.SetColumn(rightPair, 4);
        centerGrid.Children.Add(rightPair);

        // Bottom Row (Bottom-Container)
        var bottomPair = new StackPanel { Orientation = Orientation.Horizontal };
        var bottomWin = CreatePairBtn("Bottom-Windows", () => OpenDrawer("Bottom Drawer (Windows)", DrawerPlacement.Bottom));
        var bottomCont = CreatePairBtn("Bottom-Container", () => OpenDrawer("Bottom Drawer (Container)", DrawerPlacement.Bottom));
        bottomWin.Margin = new System.Windows.Thickness(0, 0, 4, 0);
        bottomPair.Children.Add(bottomWin);
        bottomPair.Children.Add(bottomCont);
        Grid.SetRow(bottomPair, 4);
        Grid.SetColumn(bottomPair, 2);
        centerGrid.Children.Add(bottomPair);

        bgBorder.Child = centerGrid;
        hostGrid.Children.Add(bgBorder);
        hostGrid.Children.Add(drawer);

        string sec1Xaml = @"<!-- 4-Direction Drawer (Left / Right / Top / Bottom) -->
<controls:Drawer Title=""Drawer Inspector"" 
                 Placement=""Left | Right | Top | Bottom"" 
                 IsOpen=""{Binding IsDrawerOpen}"" 
                 DrawerWidth=""320"" DrawerHeight=""220"">
    <StackPanel>
        <TextBox Text=""Parameter Settings"" />
    </StackPanel>
</controls:Drawer>";
        AddCardSection("4-Way Directional Drawer", hostGrid, sec1Xaml);

        return mainSp;
    }

    private object CreateDialogDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11.5,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================
        // SECTION 1: Standard Modal Dialog Variants (Clean Trigger Bar)
        // =========================================================================
        var sec1Host = new Grid { Height = 360, ClipToBounds = true };
        var sec1Bg = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(20)
        };
        sec1Bg.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sec1Bg.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sec1CenterSp = new StackPanel
        {
            VerticalAlignment = System.Windows.VerticalAlignment.Center,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
            Width = 620
        };

        var sec1Dialog = new Dialog
        {
            Title = "Engineering Calculation Parameters",
            DialogWidth = 460
        };

        var sec1Row1 = new UniformGrid { Columns = 3, Margin = new System.Windows.Thickness(0, 0, 0, 14) };

        var btnTextDialog = new Button
        {
            Content = "Simple Text Dialog",
            Height = 36,
            Margin = new System.Windows.Thickness(4, 0, 4, 0)
        };
        btnTextDialog.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btnTextDialog.Click += (s, e) =>
        {
            var sp = new StackPanel { Margin = new System.Windows.Thickness(4) };
            var msg = new TextBlock
            {
                Text = "Reinforced concrete volume calculation completed successfully. All structural checks adhere to standard code.",
                FontSize = 13,
                TextWrapping = System.Windows.TextWrapping.Wrap,
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            msg.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");

            var okBtn = new Button
            {
                Content = "OK",
                Width = 90,
                Height = 32,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Right
            };
            okBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
            okBtn.Click += (s1, e1) => sec1Dialog.IsOpen = false;

            sp.Children.Add(msg);
            sp.Children.Add(okBtn);

            sec1Dialog.Title = "Text Dialog";
            sec1Dialog.Content = sp;
            sec1Dialog.IsOpen = true;
        };

        var btnTimerDialog = new Button
        {
            Content = "Auto-Close Timer",
            Height = 36,
            Margin = new System.Windows.Thickness(4, 0, 4, 0)
        };
        btnTimerDialog.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btnTimerDialog.Click += (s, e) =>
        {
            var sp = new StackPanel { Margin = new System.Windows.Thickness(4) };
            var msg = new TextBlock
            {
                Text = "Syncing bill of quantities with Revit central server... This modal will auto-dismiss in 3 seconds.",
                FontSize = 13,
                TextWrapping = System.Windows.TextWrapping.Wrap,
                Margin = new System.Windows.Thickness(0, 0, 0, 14)
            };
            msg.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");

            var pBar = new ProgressBar { IsIndeterminate = true, Height = 4, Margin = new System.Windows.Thickness(0, 0, 0, 10) };
            pBar.SetResourceReference(ProgressBar.ForegroundProperty, "CONCOST.Brush.Primary");

            sp.Children.Add(msg);
            sp.Children.Add(pBar);

            sec1Dialog.Title = "Timed Auto-Dismiss Dialog";
            sec1Dialog.Content = sp;
            sec1Dialog.IsOpen = true;

            var t = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(3) };
            t.Tick += (s1, e1) =>
            {
                t.Stop();
                sec1Dialog.IsOpen = false;
            };
            t.Start();
        };

        var btnChildWinDialog = new Button
        {
            Content = "New Window Modal",
            Height = 36,
            Margin = new System.Windows.Thickness(4, 0, 4, 0)
        };
        btnChildWinDialog.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        btnChildWinDialog.Click += (s, e) =>
        {
            var win = new System.Windows.Window
            {
                Title = "CONCOST Sub-Window Host",
                Width = 500,
                Height = 380,
                WindowStartupLocation = System.Windows.WindowStartupLocation.CenterScreen
            };
            win.SetResourceReference(System.Windows.Window.BackgroundProperty, "CONCOST.Brush.Surface");

            var subGrid = new Grid();
            var subSp = new StackPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center, HorizontalAlignment = System.Windows.HorizontalAlignment.Center };
            var subBtn = new Button { Content = "Trigger Sub-Window Dialog", Width = 220, Height = 36 };
            subBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");

            var subDlg = new Dialog { Title = "Modal Inside Child Window", DialogWidth = 380 };
            var subContent = new StackPanel { Margin = new System.Windows.Thickness(4) };
            var subText = new TextBlock { Text = "This modal dialog runs in an isolated scope inside the newly opened child window.", TextWrapping = System.Windows.TextWrapping.Wrap, Margin = new System.Windows.Thickness(0, 0, 0, 16) };
            subText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            var closeSubBtn = new Button { Content = "Close Window Dialog", Width = 150, Height = 32, HorizontalAlignment = System.Windows.HorizontalAlignment.Right };
            closeSubBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
            closeSubBtn.Click += (s1, e1) => subDlg.IsOpen = false;

            subContent.Children.Add(subText);
            subContent.Children.Add(closeSubBtn);
            subDlg.Content = subContent;

            subBtn.Click += (s1, e1) => subDlg.IsOpen = true;
            subSp.Children.Add(subBtn);
            subGrid.Children.Add(subSp);
            subGrid.Children.Add(subDlg);
            win.Content = subGrid;
            win.Show();
        };

        sec1Row1.Children.Add(btnTextDialog);
        sec1Row1.Children.Add(btnTimerDialog);
        sec1Row1.Children.Add(btnChildWinDialog);

        // Row 2: Form & Input interaction
        var formBox = new TextBox
        {
            Text = "BEAM-SECTION-W310x38.7",
            Height = 34,
            Margin = new System.Windows.Thickness(4, 0, 4, 12)
        };
        formBox.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Base");

        var btnInteractive = new Button
        {
            Content = "Open Interactive Form Dialog",
            Height = 36,
            Margin = new System.Windows.Thickness(4, 0, 4, 0)
        };
        btnInteractive.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        btnInteractive.Click += (s, e) =>
        {
            var formSp = new StackPanel { Margin = new System.Windows.Thickness(4) };
            var headerDesc = new TextBlock
            {
                Text = "Edit Structural Element Specifications:",
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 13.5,
                Margin = new System.Windows.Thickness(0, 0, 0, 12)
            };
            headerDesc.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");

            var inputEdit = new TextBox
            {
                Text = formBox.Text,
                Height = 34,
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            inputEdit.SetResourceReference(TextBox.StyleProperty, "CONCOST.TextBox.Base");

            var btnActionPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Right
            };

            var cancelBtn = new Button
            {
                Content = "Cancel",
                Width = 90,
                Height = 32,
                Margin = new System.Windows.Thickness(0, 0, 10, 0)
            };
            cancelBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            cancelBtn.Click += (s1, e1) => sec1Dialog.IsOpen = false;

            var submitBtn = new Button
            {
                Content = "Save Changes",
                Width = 110,
                Height = 32
            };
            submitBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
            submitBtn.Click += (s1, e1) =>
            {
                formBox.Text = inputEdit.Text;
                sec1Dialog.IsOpen = false;
                Growl.Success($"Updated Element: {inputEdit.Text}");
            };

            btnActionPanel.Children.Add(cancelBtn);
            btnActionPanel.Children.Add(submitBtn);

            formSp.Children.Add(headerDesc);
            formSp.Children.Add(inputEdit);
            formSp.Children.Add(btnActionPanel);

            sec1Dialog.Title = "Interactive Element Inspector";
            sec1Dialog.Content = formSp;
            sec1Dialog.IsOpen = true;
        };

        sec1CenterSp.Children.Add(sec1Row1);
        sec1CenterSp.Children.Add(formBox);
        sec1CenterSp.Children.Add(btnInteractive);

        sec1Bg.Child = sec1CenterSp;
        sec1Host.Children.Add(sec1Bg);
        sec1Host.Children.Add(sec1Dialog);

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:Dialog x:Name=""MainDialog"" 
                 Title=""Engineering Calculation Parameters"" 
                 DialogWidth=""460"" 
                 CornerRadius=""12"" 
                 IsOpen=""{Binding IsDialogOpen, Mode=TwoWay}"">
    <StackPanel Margin=""4"">
        <TextBlock Text=""Edit Structural Element Specifications:"" FontWeight=""Normal"" Margin=""0,0,0,12"" />
        <TextBox Text=""{Binding ElementSpec, Mode=TwoWay}"" Height=""34"" Margin=""0,0,0,18"" />
        <StackPanel Orientation=""Horizontal"" HorizontalAlignment=""Right"">
            <Button Content=""Cancel"" Width=""90"" Height=""32"" Margin=""0,0,10,0"" Style=""{StaticResource CONCOST.Button.Secondary}"" Command=""{Binding CancelCmd}"" />
            <Button Content=""Save Changes"" Width=""110"" Height=""32"" Style=""{StaticResource CONCOST.Button.Primary}"" Command=""{Binding SaveCmd}"" />
        </StackPanel>
    </StackPanel>
</controls:Dialog>

// ==================== C# CODE-BEHIND / LOGIC ====================
// 1. Programmatic Trigger
MainDialog.IsOpen = true;

// 2. Or using the static API
Dialog.Show(new CustomParameterView(), ""Engineering Calculation Parameters"");";

        AddCardSection("1. Standard Modal Dialog", sec1Host, sec1Code);

        // =========================================================================
        // SECTION 2: Asynchronous Fluent Dialog Services (Prompt & Confirm)
        // =========================================================================
        var sec2Host = new Grid { MinHeight = 280 };
        var sec2Bg = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(20)
        };
        sec2Bg.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sec2Bg.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sec2Token = "Sec2AsyncDialogToken";
        var sec2Dialog = new Dialog { DialogWidth = 440 };
        Dialog.SetToken(sec2Dialog, sec2Token);

        var sec2Sp = new StackPanel
        {
            VerticalAlignment = System.Windows.VerticalAlignment.Center,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
            Width = 620
        };

        var sec2Grid = new UniformGrid { Columns = 2 };

        var btnConfirmAsync = new Button
        {
            Content = "ShowConfirmAsync (Yes / No)",
            Height = 38,
            Margin = new System.Windows.Thickness(6, 0, 6, 0)
        };
        btnConfirmAsync.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Warning");
        btnConfirmAsync.Click += async (s, e) =>
        {
            var confirmed = await Dialog.ShowConfirmAsync(
                "Are you sure you want to recalculate all structural load combinations?",
                "Confirm Recalculation",
                sec2Token);

            if (confirmed)
                Growl.Success("Recalculation confirmed & started.");
            else
                Growl.Info("Action cancelled by user.");
        };

        var btnInputAsync = new Button
        {
            Content = "ShowInputAsync (Quick Prompt)",
            Height = 38,
            Margin = new System.Windows.Thickness(6, 0, 6, 0)
        };
        btnInputAsync.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        btnInputAsync.Click += async (s, e) =>
        {
            var result = await Dialog.ShowInputAsync(
                "Please enter the project code for the engineering export:",
                "PJ-2026-QS-099",
                "Export Project Code",
                sec2Token);

            if (!string.IsNullOrEmpty(result))
                Growl.Success($"Project Code set: {result}");
            else
                Growl.Warning("Prompt was cancelled.");
        };

        sec2Grid.Children.Add(btnConfirmAsync);
        sec2Grid.Children.Add(btnInputAsync);
        sec2Sp.Children.Add(sec2Grid);

        sec2Bg.Child = sec2Sp;
        sec2Host.Children.Add(sec2Bg);
        sec2Host.Children.Add(sec2Dialog);

        string sec2Code = @"// ==================== C# ASYNC SERVICE INVOCATION ====================
// 1. Asynchronous Confirmation Modal
bool isConfirmed = await Dialog.ShowConfirmAsync(
    ""Are you sure you want to recalculate all structural load combinations?"", 
    ""Confirm Recalculation"");

if (isConfirmed)
{
    ExecuteLoadRecalculation();
}

// 2. Asynchronous String Input Prompt
string? projectCode = await Dialog.ShowInputAsync(
    ""Please enter the project code for the engineering export:"", 
    ""PJ-2026-QS-099"", 
    ""Export Project Code"");

if (!string.IsNullOrEmpty(projectCode))
{
    ExportProject(projectCode);
}";

        AddCardSection("2. Asynchronous Fluent Dialog Services (ShowConfirmAsync & ShowInputAsync)", sec2Host, sec2Code);

        return mainSp;
    }

    // =========================================================================================
    // STEPBAR DEMO
