    private object CreateStepBarDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11.5,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border
                {
                    Height = 1,
                    Margin = new System.Windows.Thickness(0)
                };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null)
            {
                sp.Children.Add(codeBox);
            }
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Interactive BIM Construction Workflow StepBar
        var sb1Panel = new StackPanel();
        var sb1 = new StepBar
        {
            StepIndex = 1,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Stretch
        };
        sb1.Items.Add(new StepBarItem { Content = "Survey & Soil Test", Description = "Borehole & topography logs" });
        sb1.Items.Add(new StepBarItem { Content = "Structural Modeling", Description = "ETABS & Revit frame setup" });
        sb1.Items.Add(new StepBarItem { Content = "Rebar Detailing", Description = "Auto-rebar fabrication schedule" });
        sb1.Items.Add(new StepBarItem { Content = "Cost Estimation", Description = "BOQ & BIM 5D takeoff export" });
        sb1.Items.Add(new StepBarItem { Content = "Final Approval", Description = "Signed structural engineer stamp" });

        var navBtnPanel1 = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = System.Windows.HorizontalAlignment.Center, Margin = new System.Windows.Thickness(0, 24, 0, 0) };
        var prevBtn1 = new Button { Content = "Previous Step", Padding = new System.Windows.Thickness(14, 6, 14, 6), Margin = new System.Windows.Thickness(0, 0, 10, 0) };
        prevBtn1.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        prevBtn1.Click += (s, e) => sb1.Prev();

        var nextBtn1 = new Button { Content = "Next Step", Padding = new System.Windows.Thickness(16, 6, 16, 6) };
        nextBtn1.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        nextBtn1.Click += (s, e) => sb1.Next();

        navBtnPanel1.Children.Add(prevBtn1);
        navBtnPanel1.Children.Add(nextBtn1);
        sb1Panel.Children.Add(sb1);
        sb1Panel.Children.Add(navBtnPanel1);

        string sec1Xaml = @"<controls:StepBar StepIndex=""{Binding CurrentStep}"">
    <controls:StepBarItem Content=""Survey &amp; Soil Test"" Description=""Borehole &amp; topography logs"" />
    <controls:StepBarItem Content=""Structural Modeling"" Description=""ETABS &amp; Revit frame setup"" />
    <controls:StepBarItem Content=""Rebar Detailing"" Description=""Auto-rebar fabrication schedule"" />
    <controls:StepBarItem Content=""Cost Estimation"" Description=""BOQ &amp; BIM 5D takeoff export"" />
    <controls:StepBarItem Content=""Final Approval"" Description=""Signed structural engineer stamp"" />
</controls:StepBar>";
        AddCardSection("1. Interactive BIM Structural Pipeline Workflow Tracker", sb1Panel, sec1Xaml);

        // Section 2: 3-Stage Project License Verification StepBar
        var sb2 = new StepBar
        {
            StepIndex = 2,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Stretch
        };
        sb2.Items.Add(new StepBarItem { Content = "Account Register", Description = "Enterprise credentials" });
        sb2.Items.Add(new StepBarItem { Content = "USB Dongle Key", Description = "Hardware lock verification" });
        sb2.Items.Add(new StepBarItem { Content = "Ready to Launch", Description = "Full BIM engine activated" });

        string sec2Xaml = @"<controls:StepBar StepIndex=""2"">
    <controls:StepBarItem Content=""Account Register"" Description=""Enterprise credentials"" />
    <controls:StepBarItem Content=""USB Dongle Key"" Description=""Hardware lock verification"" />
    <controls:StepBarItem Content=""Ready to Launch"" Description=""Full BIM engine activated"" />
</controls:StepBar>";
        AddCardSection("2. 3-Stage Enterprise License Activation Flow", sb2, sec2Xaml);

        // Section 3: 4-Stage Slab Design Calculation Verification
        var sb3 = new StepBar
        {
            StepIndex = 0,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Stretch
        };
        sb3.Items.Add(new StepBarItem { Content = "Input Geometry", Description = "Span Lx, Ly & Boundary condition" });
        sb3.Items.Add(new StepBarItem { Content = "Dead & Live Loads", Description = "Superimposed load distribution" });
        sb3.Items.Add(new StepBarItem { Content = "Moment Capacity", Description = "Wood-Armer & Yield line check" });
        sb3.Items.Add(new StepBarItem { Content = "Deflection & Cracking", Description = "ACI / Eurocode serviceability" });

        string sec3Xaml = @"<controls:StepBar StepIndex=""0"">
    <controls:StepBarItem Content=""Input Geometry"" Description=""Span Lx, Ly &amp; Boundary condition"" />
    <controls:StepBarItem Content=""Dead &amp; Live Loads"" Description=""Superimposed load distribution"" />
    <controls:StepBarItem Content=""Moment Capacity"" Description=""Wood-Armer &amp; Yield line check"" />
    <controls:StepBarItem Content=""Deflection &amp; Cracking"" Description=""ACI / Eurocode serviceability"" />
</controls:StepBar>";
        AddCardSection("3. Automated RC Slab Detailing Calculation Stages", sb3, sec3Xaml);

        return mainSp;
    }
