        {
            ItemsSource = bimElements,
            TransferredItems = new List<object> { "C1 - 400x400 Column", "C2 - 500x500 Shear Column", "B1 - 250x500 Primary Beam" },
            SourceTitle = "Available BIM Components",
            TargetTitle = "Target Bill of Quantities",
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left
        };
        sec1Container.Children.Add(t1);

        var sec1Status = new TextBlock
        {
            Text = $"Transferred: {t1.TargetItems.Count} items in Bill of Quantities | Double-click any item to quick-transfer",
            FontSize = 12,
            Margin = new System.Windows.Thickness(0, 10, 0, 0)
        };
        sec1Status.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        t1.Transferred += (s, e) =>
        {
            sec1Status.Text = $"Transferred: {t1.TargetItems.Count} items in Bill of Quantities | Available: {t1.SourceItems.Count} items";
        };
        sec1Container.Children.Add(sec1Status);

        string sec1Code =
@"<!-- ==================== XAML MARKUP ==================== -->
<controls:Transfer ItemsSource=""{Binding AvailableBimElements}""
                   TransferredItems=""{Binding SelectedBillOfQuantities, Mode=TwoWay}""
                   SourceTitle=""Available BIM Components""
                   TargetTitle=""Target Bill of Quantities""
                   ListWidth=""260"" ListHeight=""320"" />

/* ==================== C# VIEWMODEL BINDING ==================== */
public class BimTransferViewModel : ObservableObject
{
    public ObservableCollection<string> AvailableBimElements { get; } = new()
    {
        ""C1 - 400x400 Column"", ""C2 - 500x500 Shear Column"", ""B1 - 250x500 Primary Beam"",
        ""B2 - 200x400 Secondary Beam"", ""SL1 - 150mm Two-Way Slab"", ""SL2 - 200mm Transfer Slab"",
        ""W1 - 300mm Core Shear Wall"", ""FT1 - 1200x1200x600 Footing""
    };

    private IList? _selectedBillOfQuantities;
    public IList? SelectedBillOfQuantities
    {
        get => _selectedBillOfQuantities;
        set => SetProperty(ref _selectedBillOfQuantities, value);
    }
}";

        AddCardSection("1. Standard Searchable BIM Structural Elements Transfer", sec1Container, sec1Code);

        // Section 2: Compact Transfer Shuttle Variant
        var sec2Container = new StackPanel();
        var t2 = new Transfer
        {
            Style = (System.Windows.Style)App.Current.Resources["CONCOST.Transfer.Compact"],
            ItemsSource = new List<string> { "Rebar D10", "Rebar D12", "Rebar D16", "Rebar D20", "Rebar D25", "Rebar D32" },
            TransferredItems = new List<object> { "Rebar D16", "Rebar D20" },
            SourceTitle = "Available Rebars",
            TargetTitle = "Active Schedule",
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left
        };
        sec2Container.Children.Add(t2);

        var sec2Status = new TextBlock
        {
            Text = $"Active Schedule: {t2.TargetItems.Count} rebars | Double-click to transfer",
            FontSize = 12,
            Margin = new System.Windows.Thickness(0, 10, 0, 0)
        };
        sec2Status.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        t2.Transferred += (s, e) =>
        {
            sec2Status.Text = $"Active Schedule: {t2.TargetItems.Count} rebars | Available: {t2.SourceItems.Count} rebars";
        };
        sec2Container.Children.Add(sec2Status);

        string sec2Code =
@"<!-- ==================== XAML MARKUP ==================== -->
<controls:Transfer Style=""{DynamicResource CONCOST.Transfer.Compact}""
                   ItemsSource=""{Binding AvailableRebars}""
                   TransferredItems=""{Binding ActiveSchedule, Mode=TwoWay}""
                   SourceTitle=""Available Rebars""
                   TargetTitle=""Active Schedule"" />

/* ==================== C# CODE-BEHIND / VIEWMODEL ==================== */
// Compact transfer has ListWidth=""200"" and ListHeight=""260"", ideal for compact tool palettes.";

        AddCardSection("2. Compact Transfer Shuttle Variant", sec2Container, sec2Code);

        // Section 3: Spacious Engineering Scope Transfer Variant
        var sec3Container = new StackPanel();
        var t3 = new Transfer
        {
            Style = (System.Windows.Style)App.Current.Resources["CONCOST.Transfer.Spacious"],
            ItemsSource = new List<string>
            {
                "Architectural Detailing Scope",
                "Structural Load Analysis",
                "MEP HVAC Integration",
                "Fire Safety Compliance",
                "BIM 4D Construction Simulation",
                "Geotechnical Soil Testing"
            },
            TransferredItems = new List<object> { "Structural Load Analysis", "BIM 4D Construction Simulation" },
            SourceTitle = "Master Project Scope",
            TargetTitle = "Sprint Milestones",
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left
        };
        sec3Container.Children.Add(t3);

        var sec3Status = new TextBlock
        {
            Text = $"Sprint Milestones: {t3.TargetItems.Count} scopes assigned",
            FontSize = 12,
            Margin = new System.Windows.Thickness(0, 10, 0, 0)
        };
        sec3Status.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        t3.Transferred += (s, e) =>
        {
            sec3Status.Text = $"Sprint Milestones: {t3.TargetItems.Count} scopes assigned | Remaining: {t3.SourceItems.Count}";
        };
        sec3Container.Children.Add(sec3Status);

        string sec3Code =
@"<!-- ==================== XAML MARKUP ==================== -->
<controls:Transfer Style=""{DynamicResource CONCOST.Transfer.Spacious}""
                   ItemsSource=""{Binding MasterScopeList}""
                   TransferredItems=""{Binding SprintMilestones, Mode=TwoWay}""
                   SourceTitle=""Master Project Scope""
                   TargetTitle=""Sprint Milestones"" />

/* ==================== C# CODE-BEHIND / VIEWMODEL ==================== */
// Spacious variant uses ListWidth=""300"" and ListHeight=""380"" for large-scale engineering modules.";

        AddCardSection("3. Spacious Engineering Scope Transfer Variant", sec3Container, sec3Code);

        return mainSp;
    }

