        var num5 = new NumericUpDown { Value = 0.0025, Increment = 0.0005, DecimalPlaces = 4, Suffix = "rad", Margin = new System.Windows.Thickness(0, 0, 12, 0) };
        var num6 = new NumericUpDown { Value = 25.0, Increment = 1.0, Minimum = -50, Maximum = 100, Suffix = "°C" };

        sec2Grid.Children.Add(num4);
        sec2Grid.Children.Add(num5);
        sec2Grid.Children.Add(num6);

        string sec2Code = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:NumericUpDown Value=""2500000"" Prefix=""$"" Increment=""50000"" DecimalPlaces=""0"" FormatString=""N0"" />
<controls:NumericUpDown Value=""0.0025"" Increment=""0.0005"" DecimalPlaces=""4"" Suffix=""rad"" />
<controls:NumericUpDown Value=""25"" Minimum=""-50"" Maximum=""100"" Increment=""1"" Suffix=""°C"" />";
        AddCardSection("2. Currency Prefix, Precision Decimals & Constraints", sec2Grid, sec2Code);

        return mainSp;
    }

