                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid { Height = 34, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var tagIcon = new CONCOST.UI.Icons.Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new System.Windows.Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var langLabel = new TextBlock { Text = "XAML & C# Code-Behind", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button { Content = "Copy", Padding = new System.Windows.Thickness(10, 2, 10, 2), FontSize = 11.5, Cursor = System.Windows.Input.Cursors.Hand };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        System.Windows.Clipboard.SetText(codeSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);
                var divider = new Border { Height = 1, Margin = new System.Windows.Thickness(0) };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);
                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);
                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == System.Windows.Visibility.Visible)
                    {
                        codeBox.Visibility = System.Windows.Visibility.Collapsed;
                        codeBtn.Content = "View XAML / C#";
                    }
                    else
                    {
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                        codeBtn.Content = "Hide XAML / C#";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        var clockHost = new Grid();
        clockHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        clockHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var clock1 = new Clock
        {
            SelectedTime = DateTime.Now,
            DisplayMode = ClockDisplayMode.Hour,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Center
        };

        var ctrlSp = new StackPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center, Margin = new System.Windows.Thickness(24, 0, 0, 0) };
        var timeLabel = new TextBlock
        {
            Text = $"Selected Time: {clock1.FormattedTime}",
            FontSize = 20,
            FontWeight = System.Windows.FontWeights.Normal,
            Margin = new System.Windows.Thickness(0, 0, 0, 16)
        };
        timeLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");

        // Real-time time text updater
        var timeTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
        timeTimer.Tick += (s, e) => { timeLabel.Text = $"Selected Time: {clock1.FormattedTime}"; };
        timeTimer.Start();

        var modeSp = new StackPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 12) };
        var btnHour = new Button { Content = "Hour Mode", Width = 115, Height = 34, Margin = new System.Windows.Thickness(0, 0, 10, 0) };
        btnHour.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");

        var btnMin = new Button { Content = "Minute Mode", Width = 115, Height = 34, Margin = new System.Windows.Thickness(0, 0, 10, 0) };
        btnMin.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");

        var btnSec = new Button { Content = "Second Mode", Width = 115, Height = 34 };
        btnSec.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");

        btnHour.Click += (s, e) =>
        {
            clock1.DisplayMode = ClockDisplayMode.Hour;
            btnHour.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
            btnMin.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            btnSec.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        };

        btnMin.Click += (s, e) =>
        {
            clock1.DisplayMode = ClockDisplayMode.Minute;
            btnHour.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            btnMin.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
            btnSec.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
        };

        btnSec.Click += (s, e) =>
        {
            clock1.ShowSeconds = true;
            clock1.DisplayMode = ClockDisplayMode.Second;
            btnHour.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            btnMin.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            btnSec.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Primary");
        };

        modeSp.Children.Add(btnHour);
        modeSp.Children.Add(btnMin);
        modeSp.Children.Add(btnSec);

        ctrlSp.Children.Add(timeLabel);
        ctrlSp.Children.Add(modeSp);

        Grid.SetColumn(clock1, 0);
        Grid.SetColumn(ctrlSp, 1);
        clockHost.Children.Add(clock1);
        clockHost.Children.Add(ctrlSp);

        string clockCode = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:Clock SelectedTime=""{Binding CurrentInspectionTime, Mode=TwoWay}""
                DisplayMode=""Hour""
                ShowSeconds=""False""
                Width=""240"" Height=""240"" />

// ==================== C# CODE-BEHIND / LOGIC ====================
// 1. Listen or bind to SelectedTime
clock.SelectedTime = DateTime.Now;
clock.DisplayMode = ClockDisplayMode.Minute;";
        AddCardSection("1. Interactive Radial Clock with Auto-Advance Selection", clockHost, clockCode);

        // Section 2: Full Style Variants (Circle Base, Card Rounded Box, Filled, Borderless)
        var sec2Grid = new UniformGrid { Columns = 3 };
        
        var vClock1 = new Clock { SelectedTime = DateTime.Now, DisplayMode = ClockDisplayMode.Hour, Margin = new System.Windows.Thickness(0, 0, 16, 0) };
        vClock1.SetResourceReference(Clock.StyleProperty, "CONCOST.Clock.Card");

        var vClock2 = new Clock { SelectedTime = DateTime.Now, DisplayMode = ClockDisplayMode.Minute, Margin = new System.Windows.Thickness(0, 0, 16, 0) };
        vClock2.SetResourceReference(Clock.StyleProperty, "CONCOST.Clock.Filled");

        var vClock3 = new Clock { SelectedTime = DateTime.Now, DisplayMode = ClockDisplayMode.Second, ShowSeconds = true };
        vClock3.SetResourceReference(Clock.StyleProperty, "CONCOST.Clock.Borderless");

        sec2Grid.Children.Add(vClock1);
        sec2Grid.Children.Add(vClock2);
        sec2Grid.Children.Add(vClock3);

        string sec2Code = @"<!-- ==================== XAML MARKUP ==================== -->
<!-- 1. Card Container Style (Material Dialog Design) -->
<controls:Clock Style=""{StaticResource CONCOST.Clock.Card}"" DisplayMode=""Hour"" />

<!-- 2. Filled Surface Style -->
<controls:Clock Style=""{StaticResource CONCOST.Clock.Filled}"" DisplayMode=""Minute"" />

<!-- 3. Borderless Minimal Style -->
<controls:Clock Style=""{StaticResource CONCOST.Clock.Borderless}"" DisplayMode=""Second"" ShowSeconds=""True"" />";
        AddCardSection("2. Style Variants (Card Box, Filled Surface, Borderless Minimal)", sec2Grid, sec2Code);

        return mainSp;
    }

