public class SlabDetailingItem
{
    public string Warning { get; set; } = "OK";
    public string Symbol { get; set; } = string.Empty;
    public double ShortOuter { get; set; }
    public double LongOuter { get; set; }

    public double ShortLeftTop_Span { get; set; }
    public string ShortLeftTop_Beam { get; set; } = string.Empty;
    public string ShortLeftTop_Type { get; set; } = string.Empty;
    public string ShortLeftTop_Hook { get; set; } = string.Empty;

    public double ShortRightBot_Span { get; set; }
    public string ShortRightBot_Beam { get; set; } = string.Empty;
    public string ShortRightBot_Type { get; set; } = string.Empty;
    public string ShortRightBot_Hook { get; set; } = string.Empty;

    public double LongLeftTop_Span { get; set; }
