public class BenchmarkGridItem : System.ComponentModel.INotifyPropertyChanged
{
    private int _id;
    private string _elementCode = string.Empty;
    private double _width;
    private double _height;
    private double _length;
    private double _progress;
    private string _status = string.Empty;
    private int _rating;
    private double _rebarWeight;
    private double _totalCost;

    public int Id { get => _id; set { _id = value; OnPropertyChanged(nameof(Id)); } }
    public string ElementCode { get => _elementCode; set { _elementCode = value; OnPropertyChanged(nameof(ElementCode)); } }
    public double Width { get => _width; set { _width = value; OnPropertyChanged(nameof(Width)); } }
    public double Height { get => _height; set { _height = value; OnPropertyChanged(nameof(Height)); } }
    public double Length { get => _length; set { _length = value; OnPropertyChanged(nameof(Length)); } }
    public double Progress { get => _progress; set { _progress = value; OnPropertyChanged(nameof(Progress)); } }
    public string Status { get => _status; set { _status = value; OnPropertyChanged(nameof(Status)); } }
    public int Rating { get => _rating; set { _rating = value; OnPropertyChanged(nameof(Rating)); } }
    public double RebarWeight { get => _rebarWeight; set { _rebarWeight = value; OnPropertyChanged(nameof(RebarWeight)); } }
    public double TotalCost { get => _totalCost; set { _totalCost = value; OnPropertyChanged(nameof(TotalCost)); } }

    public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
    protected void OnPropertyChanged(string name) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(name));
}

