    private object CreateDrawerMenuDemo()
    {
        var mainSp = new StackPanel { Margin = new Thickness(0) };

        Border BuildMetricCard(string title, string value, string subtitle, IconKind iconKind)
        {
            var b = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(14, 12, 14, 12),
                Margin = new Thickness(0, 0, 12, 12),
                MinWidth = 180
            };
            b.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var innerSp = new StackPanel();
            var topGrid = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var tBlock = new TextBlock { Text = title, FontSize = 11, FontWeight = FontWeights.Normal };
            tBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            Grid.SetColumn(tBlock, 0);
            topGrid.Children.Add(tBlock);

            var ic = new CONCOST.UI.Icons.Icon { Kind = iconKind, Width = 14, Height = 14 };
            ic.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.Primary");
            Grid.SetColumn(ic, 1);
            topGrid.Children.Add(ic);
            innerSp.Children.Add(topGrid);

            var vBlock = new TextBlock { Text = value, FontSize = 16, FontWeight = FontWeights.Normal, Margin = new Thickness(0, 0, 0, 2) };
            vBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            innerSp.Children.Add(vBlock);

            var sBlock = new TextBlock { Text = subtitle, FontSize = 11, FontWeight = FontWeights.Normal };
            sBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            innerSp.Children.Add(sBlock);

            b.Child = innerSp;
            return b;
        }

        void AddCardSection(string title, UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
