        void UpdateModuleView(CONCOST.UI.Controls.DrawerMenuItem? item)
        {
            if (item == null) return;

            metricsWrap.Children.Clear();
            wsTitleBlock.Text = item.Text;

            switch (item.Text)
            {
                case "Project Overview":
                    wsSubBlock.Text = "BIM project coordination, milestone schedule & structural model federation.";
                    metricsWrap.Children.Add(BuildMetricCard("TOTAL STORIES", "18 Floors", "64.8 m height above ground", IconKind.Layers));
                    metricsWrap.Children.Add(BuildMetricCard("FOOTPRINT AREA", "4,500 m²", "64.0m x 48.0m bay layout", IconKind.Grid));
                    metricsWrap.Children.Add(BuildMetricCard("COMPLETION", "84.5%", "Phase 3 rebar detailing", IconKind.Check));
                    metricsWrap.Children.Add(BuildMetricCard("ACTIVE TEAM", "6 Engineers", "Structural FEA & BIM leads", IconKind.Check));
                    break;

                case "3D Structural Model":
                    wsSubBlock.Text = "Finite element mesh, node constraints & 3D rebar clash detection.";
                    metricsWrap.Children.Add(BuildMetricCard("STRUCTURAL NODES", "14,820 Nodes", "6-DOF rigid base restraints", IconKind.Grid));
                    metricsWrap.Children.Add(BuildMetricCard("COLUMNS & BEAMS", "212 Members", "C35/45 concrete sections", IconKind.Layers));
                    metricsWrap.Children.Add(BuildMetricCard("CLASH DETECTION", "0 Clashes", "Rebar cage interference clear", IconKind.Check));
                    metricsWrap.Children.Add(BuildMetricCard("SOLVER STATUS", "Converged", "12 load combinations solved", IconKind.TuneAdjust));
                    break;

                case "Quantity Takeoff":
                    wsSubBlock.Text = "Automated volumetric rebar extraction & concrete pour schedule.";
                    metricsWrap.Children.Add(BuildMetricCard("CONCRETE VOLUME", "1,420 m³", "Foundations, columns, slabs", IconKind.Layers));
                    metricsWrap.Children.Add(BuildMetricCard("REBAR SUPPLY", "168.5 Tons", "HRB500 deformed rebar", IconKind.File));
                    metricsWrap.Children.Add(BuildMetricCard("FORMWORK AREA", "5,280 m²", "98% formwork reuse", IconKind.Grid));
                    metricsWrap.Children.Add(BuildMetricCard("REBAR DENSITY", "101 kg/m³", "Optimal economic range", IconKind.Check));
                    break;

                case "Cost Estimation & Pricing":
                    wsSubBlock.Text = "Direct materials costing, labor unit rates & contingency estimation.";
                    metricsWrap.Children.Add(BuildMetricCard("DIRECT MATERIAL", "$428,500", "Concrete & rebar procurement", IconKind.File));
                    metricsWrap.Children.Add(BuildMetricCard("LABOR & FORMWORK", "$115,200", "Formwork erection & stripping", IconKind.TuneAdjust));
                    metricsWrap.Children.Add(BuildMetricCard("ESTIMATED TOTAL", "$543,700", "Within allowable budget", IconKind.Check));
                    metricsWrap.Children.Add(BuildMetricCard("COST VARIANCE", "-2.4%", "Below baseline estimate", IconKind.Check));
                    break;

                case "System Settings":
                    wsSubBlock.Text = "Design code selection (Eurocode 2 / ACI 318), unit systems & export targets.";
                    metricsWrap.Children.Add(BuildMetricCard("DESIGN CODE", "Eurocode 2 / ACI", "Dual standard compliance", IconKind.Check));
                    metricsWrap.Children.Add(BuildMetricCard("UNIT SYSTEM", "Metric SI", "kN, m, MPa, mm", IconKind.TuneAdjust));
                    metricsWrap.Children.Add(BuildMetricCard("AUTOSAVE INTERVAL", "5 Minutes", "Cloud synchronization on", IconKind.Check));
                    metricsWrap.Children.Add(BuildMetricCard("USER ACCESS", "Lead Engineer", "Full write & export access", IconKind.Layers));
                    break;

                default:
                    wsSubBlock.Text = $"Interactive management module: {item.Text}";
                    metricsWrap.Children.Add(BuildMetricCard("MODULE STATUS", "Ready", "All components connected", IconKind.Check));
                    break;
            }
        }

        drawerMenu.SelectionChanged += (s, e) =>
