                       Foreground=""{DynamicResource CONCOST.Brush.TextPrimary}"" />
        </StackPanel>
    </controls:DrawerMenu.Header>
    <controls:DrawerMenu.Footer>
        <TextBlock Text=""v3.0.0 Pro Enterprise"" FontSize=""11"" FontWeight=""Normal""
                   Foreground=""{DynamicResource CONCOST.Brush.TextSecondary}""
                   HorizontalAlignment=""Center"" />
    </controls:DrawerMenu.Footer>
</controls:DrawerMenu>

// ==================== C# CODE-BEHIND / VIEWMODEL ====================
// Populate Menu Items with Icons and Badges
var items = new ObservableCollection<DrawerMenuItem>
{
    new DrawerMenuItem(""Project Overview"", IconKind.Layers, ""PRO"") { IsSelected = true },
    new DrawerMenuItem(""3D Structural Model"", IconKind.Folder),
    new DrawerMenuItem(""Quantity Takeoff"", IconKind.File, ""12""),
    new DrawerMenuItem(""Cost Estimation & Pricing"", IconKind.CheckCircle),
    new DrawerMenuItem(""System Settings"", IconKind.Settings)
};
drawerMenu.ItemsSource = items;

// Listen to Selection Changes dynamically
drawerMenu.SelectionChanged += (s, e) =>
{
    if (e.NewValue != null)
    {
        SwitchActiveModule(e.NewValue.Text);
    }
};";

        AddCardSection("1. Interactive Animated DrawerMenu", sec1Sp, sec1Code);

