    private object CreateSnowCanvasDemo()
    {
        var mainSp = new StackPanel { Margin = new Thickness(0) };

        var demoContainer = new Grid { Height = 360, Margin = new Thickness(0, 10, 0, 0) };

        var bgBorder = new Border
        {
            CornerRadius = new CornerRadius(10),
            ClipToBounds = true,
            Background = new LinearGradientBrush
            {
                StartPoint = new Point(0, 0),
                EndPoint = new Point(1, 1),
                GradientStops = new GradientStopCollection
                {
                    new GradientStop((Color)ColorConverter.ConvertFromString("#0B1120"), 0.0),
                    new GradientStop((Color)ColorConverter.ConvertFromString("#1E293B"), 1.0)
                }
            }
        };

        var snowCanvas = new CONCOST.UI.Controls.Canvas.SnowCanvas
        {
            SnowflakeCount = 80,
            SnowflakeBrush = Brushes.White,
            MinSnowflakeSize = 1.5,
            MaxSnowflakeSize = 5.0,
            MinSpeed = 0.8,
            MaxSpeed = 2.4,
            Wind = 0.3
        };

        var contentSp = new StackPanel
        {
            VerticalAlignment = VerticalAlignment.Center,
            HorizontalAlignment = HorizontalAlignment.Center
        };

        var titleTxt = new TextBlock
        {
            Text = "CONCOST SnowCanvas Particle System",
            FontSize = 24,
            FontWeight = FontWeights.Normal,
            Foreground = Brushes.White,
            HorizontalAlignment = HorizontalAlignment.Center
        };

        var subTxt = new TextBlock
        {
            Text = "GPU-accelerated composition-rendered particle canvas",
            FontSize = 13,
            Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
            Margin = new Thickness(0, 8, 0, 20),
            HorizontalAlignment = HorizontalAlignment.Center
        };

        var controlsSp = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Center
        };

        var toggleBtn = new Button
        {
            Content = "Pause / Resume",
            Style = (Style)Application.Current.FindResource("CONCOST.Button.Primary"),
            Padding = new Thickness(16, 8, 16, 8)
        };
        toggleBtn.Click += (s, e) =>
        {
            snowCanvas.IsActive = !snowCanvas.IsActive;
            toggleBtn.Content = snowCanvas.IsActive ? "Pause Particle Canvas" : "Resume Particle Canvas";
        };

        controlsSp.Children.Add(toggleBtn);
        contentSp.Children.Add(titleTxt);
        contentSp.Children.Add(subTxt);
        contentSp.Children.Add(controlsSp);

        bgBorder.Child = new Grid
        {
            Children =
            {
                snowCanvas,
                contentSp
            }
        };

        demoContainer.Children.Add(bgBorder);
        mainSp.Children.Add(demoContainer);
        return mainSp;
    }

