    private object CreateMagnifierDemo()
    {
        var mainSp = new StackPanel { Margin = new Thickness(0) };

        void AddCardSection(string title, UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(20),
                Margin = new Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                var codeBox = new Border
                {
                    CornerRadius = new CornerRadius(8),
                    BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 16, 0, 0),
                    Visibility = Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = FontWeights.Normal,
                    VerticalAlignment = VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try { Clipboard.SetText(codeSnippet); copyBtn.Content = "Copied!"; } catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var tb = new TextBox
                {
                    Text = codeSnippet,
                    IsReadOnly = true,
                    FontFamily = new FontFamily("Consolas, Courier New, monospace"),
                    FontSize = 12,
                    Padding = new Thickness(12),
                    Background = Brushes.Transparent,
                    BorderThickness = new Thickness(0),
                    TextWrapping = TextWrapping.Wrap
                };
                tb.SetResourceReference(TextBox.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBoxInner.Children.Add(tb);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == Visibility.Visible ? Visibility.Collapsed : Visibility.Visible;
                };

                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
                sp.Children.Add(codeBox);
            }
            else
            {
                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
            }

            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================
        // SECTION 1: CAD Structural Detailing & Rebar Inspection
        // =========================================================================
        var sec1Sp = new StackPanel();

        // Control Toolbar
        var toolBar = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 14) };

        var lblScale = new TextBlock
        {
            Text = "Zoom Factor:",
            FontSize = 12,
            FontWeight = FontWeights.Normal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 8, 8)
        };
        lblScale.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        toolBar.Children.Add(lblScale);

        Button CreatePresetBtn(string text, Action onClick)
        {
            var btn = new Button
            {
                Content = text,
                Padding = new Thickness(10, 4, 10, 4),
                FontSize = 11.5,
                Margin = new Thickness(0, 0, 6, 8),
                Cursor = System.Windows.Input.Cursors.Hand
            };
            btn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(btn, new CornerRadius(5));
            btn.Click += (s, e) => onClick();
            return btn;
        }

        var lblRadius = new TextBlock
        {
            Text = "Lens Size:",
            FontSize = 12,
            FontWeight = FontWeights.Normal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(12, 0, 8, 8)
        };
        lblRadius.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

        var statusBadge = new Border
        {
            CornerRadius = new CornerRadius(10),
            Padding = new Thickness(10, 3, 10, 3),
            Margin = new Thickness(12, 0, 0, 8),
            VerticalAlignment = VerticalAlignment.Center
        };
        statusBadge.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        statusBadge.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
        statusBadge.BorderThickness = new Thickness(1);

        var statusTxt = new TextBlock
        {
            Text = "Scale: 2.8x | Radius: 70px | Crosshair: Active",
            FontSize = 11,
            FontWeight = FontWeights.Normal
        };
        statusTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
        statusBadge.Child = statusTxt;

        // Blueprint Canvas Container
        var canvasBorder = new Border
        {
            Height = 360,
            CornerRadius = new CornerRadius(10),
            BorderThickness = new Thickness(1),
            ClipToBounds = true,
            Cursor = System.Windows.Input.Cursors.Cross
        };
        canvasBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        canvasBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var drawingGrid = new Grid();

        // 1. Blueprint Background Grid lines
        var bgCanvas = new Canvas { IsHitTestVisible = false };
        for (int x = 20; x < 900; x += 40)
        {
            var vLine = new System.Windows.Shapes.Line
            {
                X1 = x, Y1 = 0, X2 = x, Y2 = 360,
                StrokeThickness = 0.5,
                Stroke = new SolidColorBrush(Color.FromArgb(20, 128, 128, 128))
            };
            bgCanvas.Children.Add(vLine);
        }
        for (int y = 20; y < 360; y += 40)
        {
            var hLine = new System.Windows.Shapes.Line
            {
                X1 = 0, Y1 = y, X2 = 900, Y2 = y,
                StrokeThickness = 0.5,
                Stroke = new SolidColorBrush(Color.FromArgb(20, 128, 128, 128))
            };
            bgCanvas.Children.Add(hLine);
        }
        drawingGrid.Children.Add(bgCanvas);

        // 2. CAD Vector Elements
        var cadCanvas = new Canvas();

        // Title Header inside CAD
        var cadHeader = new TextBlock
        {
            Text = "REINFORCED CONCRETE TIED COLUMN SECTION C1 (800x800mm)",
            FontSize = 12.5,
            FontWeight = FontWeights.Normal,
            Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#FF7900"))
        };
        Canvas.SetLeft(cadHeader, 30);
        Canvas.SetTop(cadHeader, 20);
        cadCanvas.Children.Add(cadHeader);

        var cadSub = new TextBlock
        {
            Text = "Design Standard: Eurocode 2 (EN 1992-1-1) & ACI 318-19 Section 10 | Hover to inspect rebar ties and cover dimensions",
            FontSize = 11,
            FontWeight = FontWeights.Normal
        };
        cadSub.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Canvas.SetLeft(cadSub, 30);
        Canvas.SetTop(cadSub, 40);
        cadCanvas.Children.Add(cadSub);

        // Outer Column Boundary Box (800x800 represented as 200x200px)
        double colX = 80, colY = 90, colSize = 200;
        var colRect = new System.Windows.Shapes.Rectangle
        {
            Width = colSize,
            Height = colSize,
            StrokeThickness = 2,
            Stroke = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#FF7900")),
            Fill = new SolidColorBrush(Color.FromArgb(18, 255, 121, 0)),
            RadiusX = 4, RadiusY = 4
        };
        Canvas.SetLeft(colRect, colX);
        Canvas.SetTop(colRect, colY);
        cadCanvas.Children.Add(colRect);

        // Inner Stirrup / Tie Outline (Clear cover 40mm represented as 16px inset)
        double cover = 16;
        var tieRect = new System.Windows.Shapes.Rectangle
        {
            Width = colSize - cover * 2,
            Height = colSize - cover * 2,
            StrokeThickness = 1.5,
            Stroke = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#2563EB")),
            StrokeDashArray = new DoubleCollection { 4, 2 },
            RadiusX = 6, RadiusY = 6
        };
        Canvas.SetLeft(tieRect, colX + cover);
        Canvas.SetTop(tieRect, colY + cover);
        cadCanvas.Children.Add(tieRect);

        // Cross Ties / Diamond Link
        var diamondPath = new System.Windows.Shapes.Polygon
        {
            Points = new PointCollection
            {
                new Point(colX + colSize / 2, colY + cover),
                new Point(colX + colSize - cover, colY + colSize / 2),
                new Point(colX + colSize / 2, colY + colSize - cover),
                new Point(colX + cover, colY + colSize / 2)
            },
            StrokeThickness = 1,
            Stroke = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#059669"))
        };
        cadCanvas.Children.Add(diamondPath);

        // Longitudinal Rebar Dots (12 bars: 4 corners + 2 on each face)
        double barRadius = 6.0;
        double[][] barPositions = new double[][]
        {
            // 4 Corners
            new double[] { colX + cover, colY + cover },
            new double[] { colX + colSize - cover, colY + cover },
            new double[] { colX + cover, colY + colSize - cover },
            new double[] { colX + colSize - cover, colY + colSize - cover },
            // Top and Bottom faces
            new double[] { colX + colSize * 0.36, colY + cover },
            new double[] { colX + colSize * 0.64, colY + cover },
            new double[] { colX + colSize * 0.36, colY + colSize - cover },
            new double[] { colX + colSize * 0.64, colY + colSize - cover },
            // Left and Right faces
            new double[] { colX + cover, colY + colSize * 0.36 },
            new double[] { colX + cover, colY + colSize * 0.64 },
            new double[] { colX + colSize - cover, colY + colSize * 0.36 },
            new double[] { colX + colSize - cover, colY + colSize * 0.64 }
        };

        foreach (var pos in barPositions)
        {
            var barCircle = new System.Windows.Shapes.Ellipse
            {
                Width = barRadius * 2,
                Height = barRadius * 2,
                Fill = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")),
                Stroke = Brushes.White,
                StrokeThickness = 1
            };
            Canvas.SetLeft(barCircle, pos[0] - barRadius);
            Canvas.SetTop(barCircle, pos[1] - barRadius);
            cadCanvas.Children.Add(barCircle);
        }

        // Leader annotations and callout lines
        var leader1 = new System.Windows.Shapes.Polyline
        {
            Points = new PointCollection
            {
                new Point(colX + colSize - cover, colY + cover),
                new Point(colX + colSize + 30, colY + cover - 20),
                new Point(colX + colSize + 90, colY + cover - 20)
            },
            Stroke = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")),
            StrokeThickness = 1
        };
        cadCanvas.Children.Add(leader1);

        var lblBarCallout = new TextBlock
        {
            Text = "12 × Ø28 mm Main Rebar (HRB500)",
            FontSize = 11,
            FontWeight = FontWeights.Normal
        };
        lblBarCallout.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        Canvas.SetLeft(lblBarCallout, colX + colSize + 95);
        Canvas.SetTop(lblBarCallout, colY + cover - 28);
        cadCanvas.Children.Add(lblBarCallout);

        var leader2 = new System.Windows.Shapes.Polyline
        {
            Points = new PointCollection
            {
                new Point(colX + colSize - cover, colY + colSize / 2),
                new Point(colX + colSize + 25, colY + colSize / 2 + 10),
                new Point(colX + colSize + 90, colY + colSize / 2 + 10)
            },
            Stroke = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#2563EB")),
            StrokeThickness = 1
        };
        cadCanvas.Children.Add(leader2);

        var lblTieCallout = new TextBlock
        {
            Text = "Ø10 @ 100 mm 4-Legged Seismic Ties",
            FontSize = 11,
            FontWeight = FontWeights.Normal
        };
        lblTieCallout.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        Canvas.SetLeft(lblTieCallout, colX + colSize + 95);
        Canvas.SetTop(lblTieCallout, colY + colSize / 2 + 2);
        cadCanvas.Children.Add(lblTieCallout);

        // Dimension text
        var dimTop = new TextBlock
        {
            Text = "◄── 800 mm ──►",
            FontSize = 10.5,
            FontWeight = FontWeights.Normal
        };
        dimTop.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Canvas.SetLeft(dimTop, colX + colSize / 2 - 40);
        Canvas.SetTop(dimTop, colY - 18);
        cadCanvas.Children.Add(dimTop);

        var dimLeft = new TextBlock
        {
            Text = "800 mm",
            FontSize = 10.5,
            FontWeight = FontWeights.Normal
        };
        dimLeft.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Canvas.SetLeft(dimLeft, colX - 52);
        Canvas.SetTop(dimLeft, colY + colSize / 2 - 8);
        cadCanvas.Children.Add(dimLeft);

        // Engineering Specification Box on Right Side
        var specBorder = new Border
        {
            Width = 260,
            CornerRadius = new CornerRadius(8),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(12)
        };
        specBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
        specBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var specSp = new StackPanel();
        var specHeader = new TextBlock
        {
            Text = "Analytical Design Capacity",
            FontSize = 12,
            FontWeight = FontWeights.Normal,
            Margin = new Thickness(0, 0, 0, 8)
        };
        specHeader.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
        specSp.Children.Add(specHeader);

        void AddSpecRow(string name, string val)
        {
            var row = new Grid { Margin = new Thickness(0, 2, 0, 2) };
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var nBlock = new TextBlock { Text = name, FontSize = 11, FontWeight = FontWeights.Normal };
            nBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            Grid.SetColumn(nBlock, 0);

            var vBlock = new TextBlock { Text = val, FontSize = 11, FontWeight = FontWeights.Normal };
            vBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(vBlock, 1);

            row.Children.Add(nBlock);
            row.Children.Add(vBlock);
            specSp.Children.Add(row);
        }

        AddSpecRow("Concrete Strength", "C35/45 (f'c = 35 MPa)");
        AddSpecRow("Steel Grade", "HRB500 (f_yk = 500 MPa)");
        AddSpecRow("Nominal Cover c_nom", "40 mm (Severe Exposure)");
        AddSpecRow("Factored Axial N_Ed", "4,820 kN (ULS Governed)");
        AddSpecRow("Bending Moment M_Ed", "320.6 kNm");
        AddSpecRow("Shear Capacity V_Rd,c", "412.5 kN (Passed)");
        AddSpecRow("D/C Interaction Ratio", "0.81 (Design Validated)");

        specBorder.Child = specSp;
        Canvas.SetRight(specBorder, 30);
        Canvas.SetTop(specBorder, 80);
        cadCanvas.Children.Add(specBorder);

        drawingGrid.Children.Add(cadCanvas);
        canvasBorder.Child = drawingGrid;

        // Magnifier Instance
        var magnifier = new CONCOST.UI.Controls.Magnifier
        {
            Target = canvasBorder,
            Radius = 70,
            Scale = 2.8,
            ShowCrosshair = true
        };

        void UpdateStatus()
        {
            statusTxt.Text = $"Scale: {magnifier.Scale:0.0}x | Radius: {magnifier.Radius:0}px | Crosshair: {(magnifier.ShowCrosshair ? "Active" : "Off")}";
        }

        toolBar.Children.Add(CreatePresetBtn("2.0x", () => { magnifier.Scale = 2.0; UpdateStatus(); }));
        toolBar.Children.Add(CreatePresetBtn("2.8x (Default)", () => { magnifier.Scale = 2.8; UpdateStatus(); }));
        toolBar.Children.Add(CreatePresetBtn("3.5x", () => { magnifier.Scale = 3.5; UpdateStatus(); }));
        toolBar.Children.Add(CreatePresetBtn("4.5x", () => { magnifier.Scale = 4.5; UpdateStatus(); }));

        toolBar.Children.Add(lblRadius);
        toolBar.Children.Add(CreatePresetBtn("Compact (50px)", () => { magnifier.Radius = 50; UpdateStatus(); }));
        toolBar.Children.Add(CreatePresetBtn("Standard (70px)", () => { magnifier.Radius = 70; UpdateStatus(); }));
        toolBar.Children.Add(CreatePresetBtn("Large (95px)", () => { magnifier.Radius = 95; UpdateStatus(); }));

        var toggleCrosshairBtn = CreatePresetBtn("Toggle Crosshair", () =>
        {
            magnifier.ShowCrosshair = !magnifier.ShowCrosshair;
            UpdateStatus();
        });
        toolBar.Children.Add(toggleCrosshairBtn);
        toolBar.Children.Add(statusBadge);

        sec1Sp.Children.Add(toolBar);

        var targetContainer = new Grid();
        targetContainer.Children.Add(canvasBorder);
        targetContainer.Children.Add(magnifier);
        sec1Sp.Children.Add(targetContainer);

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
<!-- Interactive Floating Magnifier with CAD/BIM Drawing Target -->
<Grid>
    <!-- Target Container with CAD Drawing / Detail Elements -->
    <Border x:Name=""cadCanvasBorder""
            Height=""360""
            CornerRadius=""10""
            BorderThickness=""1""
            ClipToBounds=""True""
            Cursor=""Cross""
            Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}""
            BorderBrush=""{DynamicResource CONCOST.Brush.Border}"">
        <!-- Vector CAD drawing shapes, rebar dots, and dimensions -->
    </Border>

    <!-- Floating Magnifier Lens -->
    <controls:Magnifier Target=""{Binding ElementName=cadCanvasBorder}""
                        Scale=""2.8""
                        Radius=""70""
                        ShowCrosshair=""True""
                        BorderBrush=""{DynamicResource CONCOST.Brush.Primary}"" />
</Grid>

// ==================== C# CODE-BEHIND / VIEWMODEL ====================
// Dynamically configure zoom magnification and lens aperture
magnifier.Scale = 3.5;         // Set zoom factor to 3.5x
magnifier.Radius = 80;        // Set lens radius to 80px
magnifier.ShowCrosshair = true; // Enable precision reticle crosshair";

        AddCardSection("1. CAD Structural Column Detail Inspection (Interactive High-Precision Lens)", sec1Sp, sec1Code);

        // =========================================================================
        // SECTION 2: Fine-Print Blueprint BoQ Schedule Verification
        // =========================================================================
        var sec2Sp = new StackPanel();

        var tableCard = new Border
        {
            Height = 180,
            CornerRadius = new CornerRadius(10),
            BorderThickness = new Thickness(1),
            ClipToBounds = true,
