        };
        tableCard.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        tableCard.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var tableGrid = new Grid();
        tableGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
        tableGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
        tableGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
        tableGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
        tableGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });

        tableGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(140) });
        tableGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(100) });
        tableGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(120) });
        tableGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) });
        tableGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

        void AddTableCell(string text, int row, int col, bool isHeader = false)
        {
            var cell = new TextBlock
            {
                Text = text,
                FontSize = isHeader ? 11.5 : 10.5,
                FontWeight = FontWeights.Normal,
                VerticalAlignment = VerticalAlignment.Center
            };
            if (isHeader)
            {
                cell.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
            }
            else
            {
                cell.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            }
            Grid.SetRow(cell, row);
            Grid.SetColumn(cell, col);
            tableGrid.Children.Add(cell);
        }

        AddTableCell("MEMBER ID", 0, 0, true);
        AddTableCell("CONCRETE", 0, 1, true);
        AddTableCell("REBAR SPEC", 0, 2, true);
        AddTableCell("TONNAGE", 0, 3, true);
        AddTableCell("VERIFICATION SHA-256 INTEGRITY HASH", 0, 4, true);

        AddTableCell("COL-C1-STORY1", 1, 0);
        AddTableCell("C35/45", 1, 1);
        AddTableCell("12Ø28 + Ø10@100", 1, 2);
        AddTableCell("2.48 Tons", 1, 3);
        AddTableCell("8f4a19c4d92a0e28b1735d4911ac297b819f", 1, 4);

        AddTableCell("COL-C2-STORY1", 2, 0);
        AddTableCell("C35/45", 2, 1);
        AddTableCell("12Ø28 + Ø10@100", 2, 2);
        AddTableCell("2.48 Tons", 2, 3);
        AddTableCell("c1735d4911ac297b819f8f4a19c4d92a0e28", 2, 4);

        AddTableCell("BEAM-B12-BAY3", 3, 0);
        AddTableCell("C30/37", 3, 1);
        AddTableCell("4Ø25 Top / 6Ø25 Bot", 3, 2);
        AddTableCell("1.85 Tons", 3, 3);
        AddTableCell("4d92a0e28b1735d4911ac297b819f8f4a19c", 3, 4);

        AddTableCell("SLAB-S1-LEVEL2", 4, 0);
        AddTableCell("C30/37", 4, 1);
        AddTableCell("Ø12@150 Dual Mesh", 4, 2);
        AddTableCell("4.12 Tons", 4, 3);
        AddTableCell("9ac297b819f8f4a19c4d92a0e28b1735d491", 4, 4);

        tableCard.Child = tableGrid;

        var tableMagnifier = new CONCOST.UI.Controls.Magnifier
        {
            Target = tableCard,
            Radius = 60,
            Scale = 3.0,
            ShowCrosshair = true
        };

        var sec2Container = new Grid();
        sec2Container.Children.Add(tableCard);
        sec2Container.Children.Add(tableMagnifier);
        sec2Sp.Children.Add(sec2Container);

        string sec2Code = @"<!-- Magnifier for Micro-Text and Blueprint Table Inspection -->
<controls:Magnifier Target=""{Binding ElementName=tableCard}""
                    Radius=""60""
                    Scale=""3.0""
                    ShowCrosshair=""True"" />";

        AddCardSection("2. Blueprint BoQ Schedule & Micro-Text Reader (Fine-Print Verification)", sec2Sp, sec2Code);

        return mainSp;
    }

    private object CreateRangeSliderDemo()
    {
        var mainSp = new StackPanel { Margin = new Thickness(0) };

        void AddCardSection(string title, UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(20),
                Margin = new Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                var codeBox = new Border
                {
                    CornerRadius = new CornerRadius(8),
                    BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 16, 0, 0),
                    Visibility = Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML & C# Code-Behind",
                    FontSize = 11.5,
                    FontWeight = FontWeights.Normal,
                    VerticalAlignment = VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try { Clipboard.SetText(codeSnippet); copyBtn.Content = "Copied!"; } catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var tb = new TextBox
                {
                    Text = codeSnippet,
                    IsReadOnly = true,
                    FontFamily = new FontFamily("Consolas, Courier New, monospace"),
                    FontSize = 12,
                    Padding = new Thickness(12),
                    Background = Brushes.Transparent,
                    BorderThickness = new Thickness(0),
                    TextWrapping = TextWrapping.Wrap
                };
                tb.SetResourceReference(TextBox.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeBoxInner.Children.Add(tb);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == Visibility.Visible ? Visibility.Collapsed : Visibility.Visible;
                };

                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
                sp.Children.Add(codeBox);
            }
            else
            {
                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
            }

            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================
        // SECTION 1: BIM Structural Beam Width & Depth Filter (Live Dynamic Element Highlighting)
        // =========================================================================
        var sec1Sp = new StackPanel();

        // Control Toolbar with Presets
        var toolBar = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 14) };

        var lblPresets = new TextBlock
        {
            Text = "Filter Presets:",
            FontSize = 12,
            FontWeight = FontWeights.Normal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 8, 8)
        };
        lblPresets.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        toolBar.Children.Add(lblPresets);

        Button CreatePresetBtn(string text, Action onClick)
        {
            var btn = new Button
            {
                Content = text,
                Padding = new Thickness(10, 4, 10, 4),
                FontSize = 11.5,
                Margin = new Thickness(0, 0, 6, 8),
                Cursor = System.Windows.Input.Cursors.Hand
            };
            btn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(btn, new CornerRadius(5));
            btn.Click += (s, e) => onClick();
            return btn;
        }

        var statusPill = new Border
        {
            CornerRadius = new CornerRadius(12),
            Padding = new Thickness(10, 3, 10, 3),
            Margin = new Thickness(12, 0, 0, 8),
            VerticalAlignment = VerticalAlignment.Center
        };
        statusPill.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        statusPill.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
        statusPill.BorderThickness = new Thickness(1);

        var statusTxt = new TextBlock
        {
            Text = "Range: 250 mm - 650 mm | Matching: 4 / 8 Beams",
            FontSize = 11,
            FontWeight = FontWeights.Normal
        };
        statusTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
        statusPill.Child = statusTxt;

        // Slider Box with Min/Max Indicators
        var sliderBox = new Border
        {
            CornerRadius = new CornerRadius(8),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(16, 14, 16, 14),
            Margin = new Thickness(0, 0, 0, 16)
        };
        sliderBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        sliderBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var sliderLayout = new StackPanel();

        // Top Header of Slider Box
        var sliderHeader = new Grid { Margin = new Thickness(0, 0, 0, 10) };
        sliderHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        sliderHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        var rangeTitle = new TextBlock
        {
            Text = "Beam Cross-Section Width Interval [b_w,min - b_w,max]:",
            FontSize = 12.5,
            FontWeight = FontWeights.Normal
        };
        rangeTitle.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        Grid.SetColumn(rangeTitle, 0);
        sliderHeader.Children.Add(rangeTitle);

        var rangeReadout = new TextBlock
        {
            Text = "250 mm to 650 mm (Span: 400 mm)",
            FontSize = 12.5,
            FontWeight = FontWeights.Normal
        };
        rangeReadout.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
        Grid.SetColumn(rangeReadout, 1);
        sliderHeader.Children.Add(rangeReadout);
        sliderLayout.Children.Add(sliderHeader);

        // RangeSlider Control
        var rangeSlider1 = new CONCOST.UI.Controls.RangeSlider
        {
            Minimum = 100,
            Maximum = 1500,
            StartValue = 250,
            EndValue = 650,
            SmallChange = 25,
            Unit = "mm",
            Height = 36,
            Margin = new Thickness(4, 0, 4, 8)
        };
        sliderLayout.Children.Add(rangeSlider1);

        // Axis Tick Scale Labels below Slider
        var scaleGrid = new Grid { Margin = new Thickness(4, 0, 4, 0) };
        scaleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        scaleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        scaleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        scaleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        scaleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock CreateTickLabel(string t, TextAlignment align = TextAlignment.Left)
        {
            var tb = new TextBlock { Text = t, FontSize = 10.5, FontWeight = FontWeights.Normal, TextAlignment = align };
            tb.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            return tb;
        }

        var t1 = CreateTickLabel("100 mm"); Grid.SetColumn(t1, 0); scaleGrid.Children.Add(t1);
        var t2 = CreateTickLabel("450 mm", TextAlignment.Center); Grid.SetColumn(t2, 1); scaleGrid.Children.Add(t2);
        var t3 = CreateTickLabel("800 mm", TextAlignment.Center); Grid.SetColumn(t3, 2); scaleGrid.Children.Add(t3);
        var t4 = CreateTickLabel("1,150 mm", TextAlignment.Center); Grid.SetColumn(t4, 3); scaleGrid.Children.Add(t4);
        var t5 = CreateTickLabel("1,500 mm", TextAlignment.Right); Grid.SetColumn(t5, 4); scaleGrid.Children.Add(t5);
        sliderLayout.Children.Add(scaleGrid);

        sliderBox.Child = sliderLayout;
        sec1Sp.Children.Add(sliderBox);

        // BIM Structural Beam Elements Grid (8 items)
        var elementsGrid = new WrapPanel { Orientation = Orientation.Horizontal };

        var beamData = new (string id, string desc, double width, double depth, string span)[]
        {
            ("B1", "200x400 Secondary Floor Beam", 200, 400, "5.4 m span"),
            ("B2", "250x500 Primary Bay Beam", 250, 500, "6.8 m span"),
            ("B3", "300x600 Perimeter Spandrel Beam", 300, 600, "8.0 m span"),
            ("B4", "400x700 Critical Shear Beam", 400, 700, "8.0 m span"),
            ("B5", "500x800 Core Wall Coupling Link", 500, 800, "3.6 m span"),
            ("B6", "600x1000 Atrium Span Girder", 600, 1000, "12.0 m span"),
            ("B7", "800x1200 Heavy Transfer Strut", 800, 1200, "14.5 m span"),
            ("B8", "1000x1400 Post-Tensioned Girder", 1000, 1400, "18.0 m span")
        };

        var beamCards = new List<(Border card, Border badge, TextBlock badgeTxt, double width)>();

        foreach (var b in beamData)
        {
            var c = new Border
            {
                Width = 230,
                CornerRadius = new CornerRadius(8),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(12),
                Margin = new Thickness(0, 0, 10, 10)
            };
            c.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            c.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var cLayout = new StackPanel();

            var cTop = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            cTop.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            cTop.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var idBlock = new TextBlock { Text = b.id, FontSize = 12.5, FontWeight = FontWeights.Normal };
            idBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(idBlock, 0);
            cTop.Children.Add(idBlock);

            var bBadge = new Border
            {
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(6, 1, 6, 1)
            };
            var bBadgeTxt = new TextBlock { FontSize = 10, FontWeight = FontWeights.Normal };
            bBadge.Child = bBadgeTxt;
            Grid.SetColumn(bBadge, 1);
            cTop.Children.Add(bBadge);
            cLayout.Children.Add(cTop);

            var descBlock = new TextBlock { Text = b.desc, FontSize = 11, FontWeight = FontWeights.Normal, TextTrimming = TextTrimming.CharacterEllipsis };
            descBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            cLayout.Children.Add(descBlock);

            var dimBlock = new TextBlock { Text = $"Width: {b.width:0} mm | Depth: {b.depth:0} mm ({b.span})", FontSize = 10.5, FontWeight = FontWeights.Normal, Margin = new Thickness(0, 4, 0, 0) };
            dimBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            cLayout.Children.Add(dimBlock);

            c.Child = cLayout;
            elementsGrid.Children.Add(c);
            beamCards.Add((c, bBadge, bBadgeTxt, b.width));
        }

        sec1Sp.Children.Add(elementsGrid);

        void UpdateFilter()
        {
            double min = rangeSlider1.StartValue;
            double max = rangeSlider1.EndValue;
            rangeReadout.Text = $"{min:0} mm to {max:0} mm (Span: {max - min:0} mm)";

            int matched = 0;
            foreach (var (card, badge, badgeTxt, width) in beamCards)
            {
                bool isMatch = width >= min && width <= max;
                if (isMatch)
                {
                    matched++;
                    card.Opacity = 1.0;
                    card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Primary");
                    badge.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Primary");
                    badgeTxt.Text = "Included";
                    badgeTxt.Foreground = Brushes.White;
                }
                else
                {
                    card.Opacity = 0.35;
                    card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
                    badge.Background = Brushes.Transparent;
                    badgeTxt.Text = "Out of Range";
                    badgeTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                }
            }

            statusTxt.Text = $"Range: {min:0} mm - {max:0} mm | Matching: {matched} / {beamCards.Count} Beams";
        }

        rangeSlider1.ValueChanged += (s, e) => UpdateFilter();

        toolBar.Children.Add(CreatePresetBtn("Standard Beams (200 - 500 mm)", () =>
        {
            rangeSlider1.StartValue = 200;
            rangeSlider1.EndValue = 500;
            UpdateFilter();
        }));

        toolBar.Children.Add(CreatePresetBtn("Transfer Girders (600 - 1,200 mm)", () =>
        {
            rangeSlider1.StartValue = 600;
            rangeSlider1.EndValue = 1200;
