        }));

        toolBar.Children.Add(CreatePresetBtn("Spandrels (300 - 700 mm)", () =>
        {
            rangeSlider1.StartValue = 300;
            rangeSlider1.EndValue = 700;
            UpdateFilter();
        }));

        toolBar.Children.Add(CreatePresetBtn("All Sizes (100 - 1,500 mm)", () =>
        {
            rangeSlider1.StartValue = 100;
            rangeSlider1.EndValue = 1500;
            UpdateFilter();
        }));

        toolBar.Children.Add(statusPill);
        sec1Sp.Children.Insert(0, toolBar);

        UpdateFilter();

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
<!-- Structural Member Filter RangeSlider with Live Data Binding -->
<controls:RangeSlider x:Name=""beamRangeSlider""
                      Minimum=""100""
                      Maximum=""1500""
                      StartValue=""{Binding MinBeamWidth, Mode=TwoWay}""
                      EndValue=""{Binding MaxBeamWidth, Mode=TwoWay}""
                      SmallChange=""25""
                      Unit=""mm""
                      Height=""36"" />

// ==================== C# CODE-BEHIND / VIEWMODEL ====================
// Filter ObservableCollection in real time based on dual thumbs
beamRangeSlider.ValueChanged += (s, e) =>
{
    double min = beamRangeSlider.StartValue;
    double max = beamRangeSlider.EndValue;
    FilteredBeams = AllBeams.Where(b => b.Width >= min && b.Width <= max).ToList();
};";

        AddCardSection("1. BIM Structural Beam Width & Depth Filter (Live Dynamic Element Highlighting)", sec1Sp, sec1Code);

        // =========================================================================
        // SECTION 2: Rebar Pitch & Spacing Interval Selector (Discrete Increments)
        // =========================================================================
        var sec2Sp = new StackPanel();

        var rebarBox = new Border
        {
            CornerRadius = new CornerRadius(8),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(16),
            Margin = new Thickness(0, 0, 0, 12)
        };
        rebarBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        rebarBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var rebarLayout = new StackPanel();

        var rebarHeader = new Grid { Margin = new Thickness(0, 0, 0, 10) };
