    private static Border BuildMetricCard(string title, string value, string subtitle, IconKind iconKind)
    {
        var b = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(14, 12, 14, 12),
            Margin = new System.Windows.Thickness(0, 0, 12, 12),
            MinWidth = 180
        };
        b.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var innerSp = new StackPanel();
        var topGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

        var tBlock = new TextBlock { Text = title, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal };
        tBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Grid.SetColumn(tBlock, 0);
        topGrid.Children.Add(tBlock);

        if (iconKind != IconKind.None)
        {
            var ico = new CONCOST.UI.Icons.Icon { Kind = iconKind, Width = 14, Height = 14 };
            ico.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.Primary");
            Grid.SetColumn(ico, 1);
            topGrid.Children.Add(ico);
        }
        innerSp.Children.Add(topGrid);

        var vBlock = new TextBlock { Text = value, FontSize = 16, FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 2) };
        vBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        innerSp.Children.Add(vBlock);

        var sBlock = new TextBlock { Text = subtitle, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal };
        sBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        innerSp.Children.Add(sBlock);

        b.Child = innerSp;
        return b;
    }

    private static (Border card, Action<string, string> updater) CreateLiveCard(string title, string initialValue, string initialSubtitle, IconKind iconKind)
    {
        var b = new Border
        {
            BorderThickness = new System.Windows.Thickness(1),
            CornerRadius = new System.Windows.CornerRadius(8),
            Padding = new System.Windows.Thickness(14, 12, 14, 12),
            Margin = new System.Windows.Thickness(0, 0, 12, 12),
            MinWidth = 180
        };
        b.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var innerSp = new StackPanel();
        var topGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 6) };
        topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        topGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

        var tBlock = new TextBlock { Text = title, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal };
        tBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        Grid.SetColumn(tBlock, 0);
        topGrid.Children.Add(tBlock);

        if (iconKind != IconKind.None)
        {
            var ico = new CONCOST.UI.Icons.Icon { Kind = iconKind, Width = 14, Height = 14 };
            ico.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.Primary");
            Grid.SetColumn(ico, 1);
            topGrid.Children.Add(ico);
        }
        innerSp.Children.Add(topGrid);

        var vBlock = new TextBlock { Text = initialValue, FontSize = 16, FontWeight = System.Windows.FontWeights.Normal, Margin = new System.Windows.Thickness(0, 0, 0, 2) };
        vBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        innerSp.Children.Add(vBlock);

        var sBlock = new TextBlock { Text = initialSubtitle, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal };
        sBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        innerSp.Children.Add(sBlock);

        b.Child = innerSp;
        return (b, (val, sub) =>
        {
            vBlock.Text = val;
            sBlock.Text = sub;
        });
    }

    private object CreateAutoCompleteTextBoxDemo()
