        void UpdateSpecCard(string query)
        {
            if (string.IsNullOrWhiteSpace(query))
            {
                u1("No Selection", "Type in box to search");
                u2("--", "Awaiting input");
                u3("--", "--");
                u4("--", "--");
            }
            else if (query.Contains("Rebar", StringComparison.OrdinalIgnoreCase) || query.Contains("CB", StringComparison.OrdinalIgnoreCase))
            {
                u1("Deformed Rebar", query.Length > 28 ? query.Substring(0, 28) + "..." : query);
                u2("ASTM A615 / TCVN 1651", "fy = 500 MPa, E = 200 GPa");
                u3("7,850 kg/m³", "High-yield billet steel");
                u4("$860.00 / Ton", "Cut & bent rebar delivery");
            }
            else if (query.Contains("Formwork", StringComparison.OrdinalIgnoreCase) || query.Contains("Plywood", StringComparison.OrdinalIgnoreCase))
            {
                u1("Film Formwork", "18mm Phenolic Film");
                u2("BS 5268 / EN 13986", "Waterproof WBP glue line");
                u3("10 - 15 Cycles", "Timber frame shoring");
                u4("$18.50 / m²", "Supply & erection rate");
            }
            else
            {
                u1("Concrete Structural", query.Length > 28 ? query.Substring(0, 28) + "..." : query);
                u2("ACI 318-19 / EN 206", "C35/45 characteristic");
                u3("2,400 kg/m³", "Normal weight structural");
                u4("$118.50 / m³", "Pumped on-site delivery");
            }
        }

        actb1.TextChanged += (s, e) => UpdateSpecCard(actb1.Text);

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:AutoCompleteTextBox ItemsSource=""{Binding MaterialCatalog}""
                              attached:IconElement.Kind=""Search""
                              attached:InfoElement.Placeholder=""Type to filter materials...""
                              attached:InfoElement.ShowClearButton=""True""
                              Width=""460"" HorizontalAlignment=""Left"" />

/* ==================== C# VIEWMODEL BINDING ==================== */
public class MaterialSearchViewModel : ObservableObject
{
    public ObservableCollection<string> MaterialCatalog { get; } = new()
    {
        ""Concrete Footing Grade C20/25 (20mm aggregate)"",
