        ""High-Yield Deformed Rebar D20 CB500-V"",
        ""Film-Faced Plywood Formwork 18mm""
    };

    private string _selectedMaterial = string.Empty;
    public string SelectedMaterial
    {
        get => _selectedMaterial;
        set => SetProperty(ref _selectedMaterial, value);
    }
}";
        AddCardSection("1. BIM Structural Material Specifications (Search with Quick Filter Chips & Live Spec Card)", sec1Sp, sec1Code);

        // =========================================================================
        // SECTION 2: Rich Custom ItemTemplate with Categorized Badges & Pricing
        // =========================================================================
        var sec2Sp = new StackPanel();

        var richItems = new List<MaterialSuggestionItem>
        {
            new MaterialSuggestionItem("C35/45", "High-Strength Framing Concrete", "ACI 318-19 / EN 206-1", "Concrete", "$118.50 / m", IconKind.Layers),
            new MaterialSuggestionItem("C50/60", "Post-Tensioned Silica Concrete", "Eurocode 2 Part 1", "Concrete", "$145.00 / m", IconKind.Layers),
            new MaterialSuggestionItem("D20-CB500", "Deformed Longitudinal Rebar D20", "ASTM A615 Grade 60", "Rebar", "$860.00 / Ton", IconKind.TuneAdjust),
            new MaterialSuggestionItem("D25-CB500", "Heavy Column Rebar D25", "TCVN 1651-2:2018", "Rebar", "$885.00 / Ton", IconKind.TuneAdjust),
            new MaterialSuggestionItem("PLY-18", "Film-Faced Plywood Formwork 18mm", "BS 5268 / EN 13986", "Formwork", "$18.50 / m", IconKind.Grid),
            new MaterialSuggestionItem("STL-PNL", "Modular Steel Wall Formwork Panel", "DIN 18216 Heavy Duty", "Formwork", "$42.00 / m", IconKind.Grid),
            new MaterialSuggestionItem("STR-TND", "7-Wire Low-Relaxation Strand 12.7mm", "ASTM A416 Grade 270", "Prestress", "$1,850.00 / Ton", IconKind.Check)
        };

        var actb2 = new CONCOST.UI.Controls.AutoCompleteTextBox
        {
            Width = 480,
            HorizontalAlignment = HorizontalAlignment.Left,
            ItemsSource = richItems,
            DisplayMemberPath = "Name"
        };
        actb2.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.AutoCompleteTextBox.Base");
        CONCOST.UI.AttachedProperties.IconElement.SetKind(actb2, IconKind.Search);
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(actb2, "Search materials with categorized item template...");

        // Create programmatic DataTemplate for rich item
        var itemTemplate = new DataTemplate(typeof(MaterialSuggestionItem));
        var templateFactory = new FrameworkElementFactory(typeof(Grid));
        templateFactory.SetValue(Grid.MarginProperty, new System.Windows.Thickness(2));

        var col0 = new FrameworkElementFactory(typeof(ColumnDefinition));
