        templateFactory.AppendChild(priceBadge);

        itemTemplate.VisualTree = templateFactory;
        actb2.ItemTemplate = itemTemplate;

        sec2Sp.Children.Add(actb2);

        // Live Selected Record Inspector
        var recBox = new Border
        {
            CornerRadius = new System.Windows.CornerRadius(8),
