        recBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var recStatus = new TextBlock
        {
            Text = "Selected Component: High-Strength Framing Concrete (Code: C35/45 | Price: $118.50 / m)",
