        };
        recStatus.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        recBox.Child = recStatus;
        sec2Sp.Children.Add(recBox);

        actb2.ItemSelected += (s, e) =>
        {
