            {
                recStatus.Text = $"Selected Component: {item.Name} (Code: {item.Code} | Standard: {item.Standard} | Rate: {item.Price})";
            }
        };

        string sec2Code = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:AutoCompleteTextBox ItemsSource=""{Binding Catalog}""
                              DisplayMemberPath=""Name""
                              attached:IconElement.Kind=""Search""
                              attached:InfoElement.Placeholder=""Search materials...""
                              Width=""480"" HorizontalAlignment=""Left"">
    <controls:AutoCompleteTextBox.ItemTemplate>
        <DataTemplate DataType=""{x:Type local:MaterialRecord}"">
            <Grid Margin=""2"">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width=""*"" />
                    <ColumnDefinition Width=""Auto"" />
                </Grid.ColumnDefinitions>
                <StackPanel Grid.Column=""0"">
                    <StackPanel Orientation=""Horizontal"">
                        <Border Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}""
                                CornerRadius=""4"" Padding=""6,1"" Margin=""0,0,8,0"">
                            <TextBlock Text=""{Binding Code}"" FontSize=""11""
                                       Foreground=""{DynamicResource CONCOST.Brush.Primary}"" />
                        </Border>
                        <TextBlock Text=""{Binding Name}"" FontSize=""12.5"" />
                    </StackPanel>
                    <TextBlock Text=""{Binding Standard}"" FontSize=""11"" Margin=""0,2,0,0""
                               Foreground=""{DynamicResource CONCOST.Brush.TextSecondary}"" />
                </StackPanel>
                <Border Grid.Column=""1"" CornerRadius=""6"" Padding=""8,3""
                        Background=""{DynamicResource CONCOST.Brush.SurfaceSecondary}"">
                    <TextBlock Text=""{Binding Price}"" FontSize=""11.5"" />
                </Border>
            </Grid>
        </DataTemplate>
    </controls:AutoCompleteTextBox.ItemTemplate>
</controls:AutoCompleteTextBox>";
        AddCardSection("2. Rich Custom ItemTemplate with Categorized Badges & Pricing", sec2Sp, sec2Code);

        // =========================================================================
        // SECTION 3: AISC & Eurocode Structural Steel Section Catalog Lookup
        // =========================================================================
        var sec3Sp = new StackPanel();

        var steelProfiles = new List<SteelProfileItem>
        {
            new SteelProfileItem("W14x90", "AISC 360-16 Column", 170.9, 356.1, 369.3, 2343.3, 134.0),
            new SteelProfileItem("W18x50", "AISC 360-16 Primary Beam", 94.8, 457.2, 190.5, 1458.4, 74.4),
            new SteelProfileItem("W24x84", "AISC 360-16 Transfer Girder", 159.3, 612.1, 229.1, 3211.8, 125.0),
            new SteelProfileItem("HSS 8x8x1/2", "ASTM A500 Gr. C Square Column", 89.0, 203.2, 203.2, 532.6, 69.8),
            new SteelProfileItem("HSS 10x6x3/8", "ASTM A500 Gr. C Bracing Member", 67.7, 254.0, 152.4, 450.6, 53.1),
            new SteelProfileItem("IPE 300", "EN 10025-2 Floor Beam", 53.8, 300.0, 150.0, 557.1, 42.2),
