        };
        actb3.SetResourceReference(System.Windows.FrameworkElement.StyleProperty, "CONCOST.AutoCompleteTextBox.Base");
        CONCOST.UI.AttachedProperties.IconElement.SetKind(actb3, IconKind.Layers);
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(actb3, "Search steel shapes (e.g. 'W14x90', 'W18', 'HSS', 'IPE')...");

        sec3Sp.Children.Add(actb3);

