        var steelChipsBar = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 10, 0, 14) };
        var steelChipsLabel = new TextBlock
        {
            Text = "Preset Profiles:",
            FontSize = 12,
            FontWeight = System.Windows.FontWeights.Normal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new System.Windows.Thickness(0, 0, 8, 4)
        };
        steelChipsLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        steelChipsBar.Children.Add(steelChipsLabel);

        Button CreateSteelChip(string name)
        {
            var btn = new Button
            {
                Content = name,
                Padding = new System.Windows.Thickness(10, 3, 10, 3),
                FontSize = 11.5,
                Margin = new System.Windows.Thickness(0, 0, 6, 4),
                Cursor = System.Windows.Input.Cursors.Hand
            };
            btn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(btn, new System.Windows.CornerRadius(14));
            btn.Click += (s, e) =>
            {
                actb3.Text = name;
                actb3.CaretIndex = actb3.Text.Length;
                actb3.FilterSuggestions(name);
                actb3.Focus();
            };
            return btn;
        }

        steelChipsBar.Children.Add(CreateSteelChip("W14x90"));
        steelChipsBar.Children.Add(CreateSteelChip("W18x50"));
        steelChipsBar.Children.Add(CreateSteelChip("W24x84"));
        steelChipsBar.Children.Add(CreateSteelChip("HSS 8x8x1/2"));
        steelChipsBar.Children.Add(CreateSteelChip("IPE 300"));

        sec3Sp.Children.Add(steelChipsBar);

        // Steel Engineering Properties Table Card
        var steelBox = new Border
        {
            CornerRadius = new System.Windows.CornerRadius(8),
            BorderThickness = new System.Windows.Thickness(1),
            Padding = new System.Windows.Thickness(16),
            Margin = new System.Windows.Thickness(0, 4, 0, 0)
        };
        steelBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
        steelBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

        var steelLayout = new StackPanel();
        var steelTitle = new TextBlock
        {
            Text = "Cross-Sectional Geometrical Properties",
            FontSize = 13,
            FontWeight = System.Windows.FontWeights.Normal,
            Margin = new System.Windows.Thickness(0, 0, 0, 10)
        };
        steelTitle.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
        steelLayout.Children.Add(steelTitle);

        var steelMetrics = new WrapPanel { Orientation = Orientation.Horizontal };
        var (sCard1, su1) = CreateLiveCard("SECTION DEPTH (d)", "356.1 mm", "W14x90 nominal depth", IconKind.Grid);
        var (sCard2, su2) = CreateLiveCard("FLANGE WIDTH (bf)", "369.3 mm", "Column stability ratio", IconKind.Layers);
        var (sCard3, su3) = CreateLiveCard("SECTION MODULUS (Sx)", "2,343 cm³", "Strong-axis bending capacity", IconKind.TuneAdjust);
        var (sCard4, su4) = CreateLiveCard("LINEAR WEIGHT", "134.0 kg/m", "Fabrication tonnage estimate", IconKind.File);
        steelMetrics.Children.Add(sCard1);
        steelMetrics.Children.Add(sCard2);
        steelMetrics.Children.Add(sCard3);
        steelMetrics.Children.Add(sCard4);
        steelLayout.Children.Add(steelMetrics);

        steelBox.Child = steelLayout;
        sec3Sp.Children.Add(steelBox);

        void UpdateSteelProperties(SteelProfileItem? profile)
        {
            if (profile == null) return;
            su1($"{profile.DepthMm:0.0} mm", $"{profile.Name} nominal depth");
            su2($"{profile.WidthMm:0.0} mm", $"{profile.Standard}");
            su3($"{profile.SxCm3:0.0} cm³", $"Area A = {profile.AreaCm2:0.0} cm²");
            su4($"{profile.WeightKgM:0.0} kg/m", "Fabrication tonnage rate");
        }

        actb3.ItemSelected += (s, e) =>
        {
            if (e.NewValue is SteelProfileItem p)
            {
                UpdateSteelProperties(p);
            }
        };

        actb3.TextChanged += (s, e) =>
        {
            var match = steelProfiles.FirstOrDefault(p => p.Name.Equals(actb3.Text.Trim(), StringComparison.OrdinalIgnoreCase));
            if (match != null)
            {
                UpdateSteelProperties(match);
            }
        };

        string sec3Code = @"<!-- ==================== XAML MARKUP ==================== -->
<controls:AutoCompleteTextBox ItemsSource=""{Binding SteelCatalog}""
                              DisplayMemberPath=""Name""
                              attached:IconElement.Kind=""Layers""
                              attached:InfoElement.Placeholder=""Search steel profiles...""
                              SelectedItem=""{Binding SelectedProfile, Mode=TwoWay}""
                              Width=""460"" HorizontalAlignment=""Left"" />

/* ==================== C# CODE-BEHIND ==================== */
public record SteelProfile(string Name, double DepthMm, double WidthMm, double SxCm3, double WeightKgM);";
        AddCardSection("3. AISC & Eurocode Structural Steel Section Catalog Lookup", sec3Sp, sec3Code);

        return mainSp;
    }

    // =========================================================================================
    // DRAGDROPHELPER DEMO (GongSolutions Pattern)
    // =========================================================================================
    public record BimDragElement(string Mark, string Type, string Spec, string Weight, IconKind Icon);

    public record PourScheduleItem(int Sequence, string Zone, string Volume, string Crew, IconKind Icon);

    private object CreateDragDropHelperDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? codeSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();

            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(codeSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML / C#",
                    Padding = new System.Windows.Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new System.Windows.CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();

                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new System.Windows.Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langBadge = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                var tagIcon = new CONCOST.UI.Icons.Icon
                {
                    Kind = IconKind.Edit,
                    Width = 14,
                    Height = 14,
                    Margin = new System.Windows.Thickness(0, 0, 6, 0)
                };
                tagIcon.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                var langLabel = new TextBlock
                {
                    Text = "XAML Attached Property & C# ViewModel",
                    FontSize = 11.5,
                    FontWeight = System.Windows.FontWeights.Normal,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center
                };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new System.Windows.Thickness(10, 2, 10, 2),
                    FontSize = 11,
                    Height = 24,
                    VerticalAlignment = System.Windows.VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try { Clipboard.SetText(codeSnippet); copyBtn.Content = "Copied!"; } catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);

                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border { Height = 1 };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(codeSnippet);
                codeBoxInner.Children.Add(codeText);

                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    codeBox.Visibility = codeBox.Visibility == System.Windows.Visibility.Visible ? System.Windows.Visibility.Collapsed : System.Windows.Visibility.Visible;
                };

                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
                sp.Children.Add(codeBox);
            }
            else
            {
                sp.Children.Add(headerGrid);
                sp.Children.Add(content);
            }

            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // =========================================================================
        // SECTION 1: Multi-Stage BIM Fabrication & Assembly Workflow (Kanban Transfer)
        // =========================================================================
        var sec1Sp = new StackPanel();

        var kanbanGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 10) };
        kanbanGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        kanbanGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(14) });
        kanbanGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        kanbanGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(14) });
        kanbanGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });

        var stage1Items = new System.Collections.ObjectModel.ObservableCollection<BimDragElement>
        {
            new BimDragElement("Column C1", "Square Column 400x400", "24-D25 CB500-V (C35/45)", "3.84 Tons", IconKind.Layers),
            new BimDragElement("Beam B2", "Secondary Beam 250x500", "8-D20 CB500-V (C30/37)", "1.92 Tons", IconKind.Grid),
            new BimDragElement("Wall SW1", "Shear Wall Core 300mm", "D16@150 Double Mat", "6.20 Tons", IconKind.Layers),
            new BimDragElement("Footing FT1", "Pad Footing 1.8x1.8m", "D20@120 Both Ways", "4.15 Tons", IconKind.Check)
        };

        var stage2Items = new System.Collections.ObjectModel.ObservableCollection<BimDragElement>
        {
            new BimDragElement("Girder G1", "Transfer Girder 500x900", "Post-tensioned 4x Tendons", "8.60 Tons", IconKind.TuneAdjust),
            new BimDragElement("Column C2", "Shear Column 500x500", "28-D25 CB500-V Grade 60", "5.10 Tons", IconKind.Layers),
            new BimDragElement("Slab SL1", "Two-Way Slab 150mm", "D12@150 Top & Bottom", "2.80 Tons", IconKind.Grid)
        };

        var stage3Items = new System.Collections.ObjectModel.ObservableCollection<BimDragElement>
        {
            new BimDragElement("Stair ST1", "Precast Flight Flight 1-2", "Grade C35 Monolithic", "3.10 Tons", IconKind.Layers),
            new BimDragElement("Edge Beam B3", "Perimeter Spandrel 200x400", "6-D16 Torsional Ties", "1.45 Tons", IconKind.Grid)
        };

        // DataTemplate for Kanban card item
        DataTemplate CreateKanbanItemTemplate()
        {
            var dt = new DataTemplate(typeof(BimDragElement));
            var rootBorder = new FrameworkElementFactory(typeof(Border));
            rootBorder.SetValue(Border.CornerRadiusProperty, new System.Windows.CornerRadius(6));
            rootBorder.SetValue(Border.BorderThicknessProperty, new System.Windows.Thickness(1));
            rootBorder.SetValue(Border.PaddingProperty, new System.Windows.Thickness(10, 8, 10, 8));
            rootBorder.SetValue(Border.MarginProperty, new System.Windows.Thickness(0, 0, 0, 6));
            rootBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            rootBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var gridFact = new FrameworkElementFactory(typeof(Grid));
            var colA = new FrameworkElementFactory(typeof(ColumnDefinition));
            colA.SetValue(ColumnDefinition.WidthProperty, System.Windows.GridLength.Auto);
            var colB = new FrameworkElementFactory(typeof(ColumnDefinition));
            colB.SetValue(ColumnDefinition.WidthProperty, new System.Windows.GridLength(1, System.Windows.GridUnitType.Star));
            var colC = new FrameworkElementFactory(typeof(ColumnDefinition));
            colC.SetValue(ColumnDefinition.WidthProperty, System.Windows.GridLength.Auto);
            gridFact.AppendChild(colA);
            gridFact.AppendChild(colB);
            gridFact.AppendChild(colC);

            // Icon
            var iconFact = new FrameworkElementFactory(typeof(CONCOST.UI.Icons.Icon));
            iconFact.SetBinding(CONCOST.UI.Icons.Icon.KindProperty, new System.Windows.Data.Binding("Icon"));
            iconFact.SetValue(CONCOST.UI.Icons.Icon.WidthProperty, 14.0);
            iconFact.SetValue(CONCOST.UI.Icons.Icon.HeightProperty, 14.0);
            iconFact.SetValue(FrameworkElement.MarginProperty, new System.Windows.Thickness(0, 0, 8, 0));
            iconFact.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);
            iconFact.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.Primary");
            gridFact.AppendChild(iconFact);

            // Text Stack
            var spFact = new FrameworkElementFactory(typeof(StackPanel));
            spFact.SetValue(Grid.ColumnProperty, 1);

            var topRowFact = new FrameworkElementFactory(typeof(StackPanel));
            topRowFact.SetValue(StackPanel.OrientationProperty, Orientation.Horizontal);

            var markTxt = new FrameworkElementFactory(typeof(TextBlock));
            markTxt.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("Mark"));
            markTxt.SetValue(TextBlock.FontSizeProperty, 12.0);
            markTxt.SetValue(TextBlock.FontWeightProperty, System.Windows.FontWeights.Normal);
            markTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            topRowFact.AppendChild(markTxt);

            var typeTxt = new FrameworkElementFactory(typeof(TextBlock));
            typeTxt.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("Type") { StringFormat = " - {0}" });
            typeTxt.SetValue(TextBlock.FontSizeProperty, 11.5);
            typeTxt.SetValue(TextBlock.FontWeightProperty, System.Windows.FontWeights.Normal);
            typeTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            topRowFact.AppendChild(typeTxt);
            spFact.AppendChild(topRowFact);

            var specTxt = new FrameworkElementFactory(typeof(TextBlock));
            specTxt.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("Spec"));
            specTxt.SetValue(TextBlock.FontSizeProperty, 11.0);
            specTxt.SetValue(TextBlock.FontWeightProperty, System.Windows.FontWeights.Normal);
            specTxt.SetValue(TextBlock.MarginProperty, new System.Windows.Thickness(0, 2, 0, 0));
            specTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            spFact.AppendChild(specTxt);

            gridFact.AppendChild(spFact);

            // Weight badge
            var weightBadge = new FrameworkElementFactory(typeof(Border));
            weightBadge.SetValue(Grid.ColumnProperty, 2);
            weightBadge.SetValue(Border.CornerRadiusProperty, new System.Windows.CornerRadius(4));
            weightBadge.SetValue(Border.PaddingProperty, new System.Windows.Thickness(6, 2, 6, 2));
            weightBadge.SetValue(Border.VerticalAlignmentProperty, VerticalAlignment.Center);
            weightBadge.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");

            var weightTxt = new FrameworkElementFactory(typeof(TextBlock));
            weightTxt.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("Weight"));
            weightTxt.SetValue(TextBlock.FontSizeProperty, 10.5);
            weightTxt.SetValue(TextBlock.FontWeightProperty, System.Windows.FontWeights.Normal);
            weightTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            weightBadge.AppendChild(weightTxt);
            gridFact.AppendChild(weightBadge);

            rootBorder.AppendChild(gridFact);
            dt.VisualTree = rootBorder;
            return dt;
        }

        UIElement CreateKanbanColumn(string title, string countText, System.Collections.ObjectModel.ObservableCollection<BimDragElement> items, string group, int colIndex)
        {
            var colBorder = new Border
            {
                CornerRadius = new System.Windows.CornerRadius(8),
                BorderThickness = new System.Windows.Thickness(1),
                Padding = new System.Windows.Thickness(12)
            };
            colBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            colBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var colSp = new StackPanel();

            var colHeader = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 10) };
            colHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            colHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleTxt = new TextBlock
            {
                Text = title,
                FontSize = 12.5,
                FontWeight = System.Windows.FontWeights.Normal,
                VerticalAlignment = VerticalAlignment.Center
            };
            titleTxt.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleTxt, 0);
            colHeader.Children.Add(titleTxt);

            var countBadge = new Border
            {
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(7, 1, 7, 1)
            };
            countBadge.SetResourceReference(Border.BackgroundProperty, colIndex == 0 ? "CONCOST.Brush.Primary" : colIndex == 1 ? "CONCOST.Brush.Surface" : "CONCOST.Brush.Surface");
            var countLabel = new TextBlock
            {
                Text = countText,
                FontSize = 11,
                FontWeight = System.Windows.FontWeights.Normal,
                Foreground = colIndex == 0 ? System.Windows.Media.Brushes.White : (Brush)Application.Current.FindResource("CONCOST.Brush.TextSecondary")
            };
            countBadge.Child = countLabel;
            Grid.SetColumn(countBadge, 1);
            colHeader.Children.Add(countBadge);
            colSp.Children.Add(colHeader);

            var lb = new ListBox
            {
                ItemsSource = items,
                ItemTemplate = CreateKanbanItemTemplate(),
                Height = 260,
                BorderThickness = new System.Windows.Thickness(0),
                Background = System.Windows.Media.Brushes.Transparent,
                
                
            };
            CONCOST.UI.AttachedProperties.DragDropHelper.SetIsDragSource(lb, true);
            CONCOST.UI.AttachedProperties.DragDropHelper.SetIsDropTarget(lb, true);
            CONCOST.UI.AttachedProperties.DragDropHelper.SetDragDropGroup(lb, group);

            items.CollectionChanged += (s, e) =>
            {
                countLabel.Text = $"{items.Count} items";
            };

            colSp.Children.Add(lb);
            colBorder.Child = colSp;
            Grid.SetColumn(colBorder, colIndex * 2);
            return colBorder;
        }

        kanbanGrid.Children.Add(CreateKanbanColumn("1. Detailing & Cutting", $"{stage1Items.Count} items", stage1Items, "BimKanban", 0));
        kanbanGrid.Children.Add(CreateKanbanColumn("2. Cage Tying & Assembly", $"{stage2Items.Count} items", stage2Items, "BimKanban", 1));
        kanbanGrid.Children.Add(CreateKanbanColumn("3. Crane Erection & Verified", $"{stage3Items.Count} items", stage3Items, "BimKanban", 2));

        sec1Sp.Children.Add(kanbanGrid);

        var kanbanTip = new TextBlock
        {
            Text = "Drag any structural element card horizontally between columns to advance workflow stage, or drag vertically to re-prioritize.",
            FontSize = 11.5,
            FontWeight = System.Windows.FontWeights.Normal,
            Margin = new System.Windows.Thickness(0, 4, 0, 0)
        };
        kanbanTip.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        sec1Sp.Children.Add(kanbanTip);

        string sec1Code = @"<!-- ==================== XAML MARKUP ==================== -->
<!-- Attached DragDropHelper on ListBox (Kanban Inter-List Transfer) -->
<ListBox ItemsSource=""{Binding DetailingStageElements}""
         attached:DragDropHelper.IsDragSource=""True""
         attached:DragDropHelper.IsDropTarget=""True""
         attached:DragDropHelper.DragDropGroup=""BimKanban""
         ItemTemplate=""{StaticResource BimElementTemplate}"" />

<ListBox ItemsSource=""{Binding AssemblyStageElements}""
         attached:DragDropHelper.IsDragSource=""True""
         attached:DragDropHelper.IsDropTarget=""True""
         attached:DragDropHelper.DragDropGroup=""BimKanban""
         ItemTemplate=""{StaticResource BimElementTemplate}"" />

/* ==================== C# VIEWMODEL BINDING ==================== */
