        UIElement CreateGroupList(string title, string groupName, string groupLabel, System.Collections.ObjectModel.ObservableCollection<string> items, int col)
        {
            var b = new Border
            {
                CornerRadius = new System.Windows.CornerRadius(8),
                BorderThickness = new System.Windows.Thickness(1),
                Padding = new System.Windows.Thickness(12)
            };
            b.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            b.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var hdr = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 8) };
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var t = new TextBlock { Text = title, FontSize = 12, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = VerticalAlignment.Center };
            t.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(t, 0);
            hdr.Children.Add(t);

            var gBadge = new Border { CornerRadius = new System.Windows.CornerRadius(4), Padding = new System.Windows.Thickness(6, 1, 6, 1) };
            gBadge.SetResourceReference(Border.BackgroundProperty, groupName == "GroupA" ? "CONCOST.Brush.Surface" : "CONCOST.Brush.PrimaryLight");
            var gTxt = new TextBlock { Text = groupLabel, FontSize = 10, FontWeight = System.Windows.FontWeights.Normal };
            gTxt.SetResourceReference(TextBlock.ForegroundProperty, groupName == "GroupA" ? "CONCOST.Brush.TextSecondary" : "CONCOST.Brush.Primary");
            gBadge.Child = gTxt;
            Grid.SetColumn(gBadge, 1);
            hdr.Children.Add(gBadge);
            sp.Children.Add(hdr);

            var lb = new ListBox
            {
                ItemsSource = items,
                Height = 160,
                BorderThickness = new System.Windows.Thickness(0),
                Background = System.Windows.Media.Brushes.Transparent
            };
            CONCOST.UI.AttachedProperties.DragDropHelper.SetIsDragSource(lb, true);
            CONCOST.UI.AttachedProperties.DragDropHelper.SetIsDropTarget(lb, true);
            CONCOST.UI.AttachedProperties.DragDropHelper.SetDragDropGroup(lb, groupName);
            sp.Children.Add(lb);

            b.Child = sp;
            Grid.SetColumn(b, col * 2);
            return b;
        }

        sec3Grid.Children.Add(CreateGroupList("Civil Concrete Works", "GroupA", "DragDropGroup: 'GroupA'", civilItems, 0));
        sec3Grid.Children.Add(CreateGroupList("Structural Steel Works", "GroupA", "DragDropGroup: 'GroupA'", structItems, 1));
        sec3Grid.Children.Add(CreateGroupList("MEP Electrical & Piping", "GroupB", "DragDropGroup: 'GroupB'", mepItems, 2));

        sec3Sp.Children.Add(sec3Grid);

        string sec3Code = @"<!-- ==================== XAML MARKUP ==================== -->
<!-- Compatible Transfer: Both have DragDropGroup=""GroupA"" -->
<ListBox attached:DragDropHelper.IsDragSource=""True""
         attached:DragDropHelper.IsDropTarget=""True""
         attached:DragDropHelper.DragDropGroup=""GroupA"" />

<!-- Incompatible Transfer: Blocked by DragDropGroup=""GroupB"" -->
<ListBox attached:DragDropHelper.IsDragSource=""True""
         attached:DragDropHelper.IsDropTarget=""True""
         attached:DragDropHelper.DragDropGroup=""GroupB"" />";
        AddCardSection("3. Work Package Scope Allocation (DragDropGroup Isolation & Security)", sec3Sp, sec3Code);

        return mainSp;
    }

    private object CreateSpreadsheetDemo()
    {
        var mainSp = new StackPanel { Margin = new Thickness(0) };

        void AddCardSection(string title, UIElement content, string? xamlSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(20),
                Margin = new Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrEmpty(xamlSnippet))
            {
                var codeBtn = new Button
                {
                    Content = "View XAML",
                    Padding = new Thickness(10, 4, 10, 4),
                    FontSize = 12,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                codeBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(codeBtn, IconKind.Edit);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(codeBtn, new CornerRadius(6));
                Grid.SetColumn(codeBtn, 1);
                headerGrid.Children.Add(codeBtn);

                codeBox = new Border
                {
                    CornerRadius = new CornerRadius(8),
                    BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 16, 0, 0),
                    Visibility = Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeBoxInner = new StackPanel();
                var codeTopBar = new Grid
                {
                    Height = 34,
                    Margin = new Thickness(12, 0, 8, 0)
                };
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                codeTopBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var langBadge = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                var tagIcon = new Icon { Kind = IconKind.Edit, Width = 14, Height = 14, Margin = new Thickness(0, 0, 6, 0) };
                tagIcon.SetResourceReference(Icon.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                var langLabel = new TextBlock { Text = "XAML & C# Code-Behind", FontSize = 11.5, FontWeight = FontWeights.Normal };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                langBadge.Children.Add(tagIcon);
                langBadge.Children.Add(langLabel);
                Grid.SetColumn(langBadge, 0);
                codeTopBar.Children.Add(langBadge);

                var copyBtn = new Button
                {
                    Content = "Copy",
                    Padding = new Thickness(10, 2, 10, 2),
                    FontSize = 11.5,
                    Cursor = System.Windows.Input.Cursors.Hand
                };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.IconElement.SetKind(copyBtn, IconKind.Check);
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new CornerRadius(4));
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        Clipboard.SetText(xamlSnippet.Trim());
                        copyBtn.Content = "Copied!";
                        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        timer.Tick += (ts, te) => { copyBtn.Content = "Copy"; timer.Stop(); };
                        timer.Start();
                    }
                    catch { }
                };
                Grid.SetColumn(copyBtn, 1);
                codeTopBar.Children.Add(copyBtn);
                codeBoxInner.Children.Add(codeTopBar);

                var divider = new Border { Height = 1, Margin = new Thickness(0) };
                divider.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeBoxInner.Children.Add(divider);

                var codeText = CreateXamlSyntaxHighlighter(xamlSnippet);
                codeBoxInner.Children.Add(codeText);
                codeBox.Child = codeBoxInner;

                codeBtn.Click += (s, e) =>
                {
                    if (codeBox.Visibility == Visibility.Visible)
                    {
                        codeBox.Visibility = Visibility.Collapsed;
                        codeBtn.Content = "View XAML";
                    }
                    else
                    {
                        codeBox.Visibility = Visibility.Visible;
                        codeBtn.Content = "Hide XAML";
                    }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // Section 1: Full Enterprise Engineering Spreadsheet (Bill of Quantities / BoQ Estimation)
        var spBoQ = new CONCOST.UI.Controls.Spreadsheet
        {
            Height = 620,
            Margin = new Thickness(0, 0, 0, 10)
        };

        var boqSheet = new SpreadsheetSheet { Name = "Structural BoQ Estimation", RowCount = 50, ColumnCount = 12 };
        boqSheet.SetColumnWidth(0, 45);  // No.
        boqSheet.SetColumnWidth(1, 280); // Description
        boqSheet.SetColumnWidth(2, 70);  // Unit
        boqSheet.SetColumnWidth(3, 85);  // Quantity
        boqSheet.SetColumnWidth(4, 115); // Unit Price ($)
        boqSheet.SetColumnWidth(5, 140); // Total ($)
        boqSheet.SetColumnWidth(6, 160); // Remarks

        // Header Row (Row 0)
        void SetHeader(int c, string text)
        {
            var cell = boqSheet.GetOrCreateCell(0, c);
            cell.RawValue = text;
            cell.IsBold = true;
            cell.HorizontalAlignment = HorizontalAlignment.Center;
            cell.BackgroundResourceKey = "CONCOST.Brush.SurfaceSecondary";
        }
        SetHeader(0, "No.");
        SetHeader(1, "Structural Work Description");
        SetHeader(2, "Unit");
        SetHeader(3, "Quantity");
        SetHeader(4, "Unit Price ($)");
        SetHeader(5, "Total ($)");
        SetHeader(6, "Remarks");

        // Row Data Items
        var boqItems = new (int stt, string name, string unit, double qty, double price, string note)[]
        {
            (1, "Lean concrete blinding 100mm (Grade C12/15)", "m3", 14.5, 45.0, "Thickness 100mm"),
            (2, "Reinforced pile cap concrete (Grade C30/37)", "m3", 68.2, 75.0, "Aggregate 20mm, OPC"),
            (3, "Columns & shear walls concrete (Grade C35/45)", "m3", 42.0, 85.0, "Waterproof B6"),
            (4, "Beams & slabs concrete Level 1 (Grade C30/37)", "m3", 85.6, 78.0, "Monolithic pour"),
            (5, "Foundation rebar D<=10mm (Grade CB240T)", "kg", 1850.0, 0.85, "Coiled rebar"),
            (6, "Superstructure rebar D>10mm (Grade CB400V)", "kg", 8400.0, 0.92, "Deformed bar"),
            (7, "Formwork for footings & stub columns", "m2", 120.0, 12.0, "Film-faced plywood 18mm"),
            (8, "Formwork for Level 1 suspended beams & slab", "m2", 340.0, 14.5, "Modular scaffolding system")
        };

        for (int i = 0; i < boqItems.Length; i++)
        {
            int r = i + 1;
            var item = boqItems[i];

            // Col 0: STT
            var c0 = boqSheet.GetOrCreateCell(r, 0);
            c0.RawValue = item.stt.ToString();
            c0.HorizontalAlignment = HorizontalAlignment.Center;

            // Col 1: Name
            var c1 = boqSheet.GetOrCreateCell(r, 1);
            c1.RawValue = item.name;

            // Col 2: Unit
            var c2 = boqSheet.GetOrCreateCell(r, 2);
            c2.RawValue = item.unit;
            c2.HorizontalAlignment = HorizontalAlignment.Center;

            // Col 3: Qty
            var c3 = boqSheet.GetOrCreateCell(r, 3);
            c3.RawValue = item.qty.ToString("0.##");
            c3.Format = SpreadsheetCellFormat.Number;
            c3.HorizontalAlignment = HorizontalAlignment.Right;

            // Col 4: Price
            var c4 = boqSheet.GetOrCreateCell(r, 4);
            c4.RawValue = item.price.ToString(CultureInfo.InvariantCulture);
            c4.Format = SpreadsheetCellFormat.Currency;
            c4.HorizontalAlignment = HorizontalAlignment.Right;

            // Col 5: Total = Qty * Price (=D{r+1}*E{r+1})
            var c5 = boqSheet.GetOrCreateCell(r, 5);
            c5.Formula = $"=D{r + 1}*E{r + 1}";
            c5.Format = SpreadsheetCellFormat.Currency;
            c5.HorizontalAlignment = HorizontalAlignment.Right;
            c5.IsBold = true;

            // Col 6: Note
            var c6 = boqSheet.GetOrCreateCell(r, 6);
            c6.RawValue = item.note;
        }

        // Summary Rows
        int sumRow = boqItems.Length + 2;
        var sumLabel = boqSheet.GetOrCreateCell(sumRow, 1);
        sumLabel.RawValue = "TOTAL DIRECT CONSTRUCTION COST (EXCL. TAX):";
        sumLabel.IsBold = true;
        sumLabel.ForegroundResourceKey = "CONCOST.Brush.Primary";

        var sumCell = boqSheet.GetOrCreateCell(sumRow, 5);
        sumCell.Formula = $"=SUM(F2:F{boqItems.Length + 1})";
        sumCell.Format = SpreadsheetCellFormat.Currency;
        sumCell.HorizontalAlignment = HorizontalAlignment.Right;
        sumCell.IsBold = true;
        sumCell.ForegroundResourceKey = "CONCOST.Brush.Primary";

        // Row VAT: 10%
        int vatRow = sumRow + 1;
        var vatLabel = boqSheet.GetOrCreateCell(vatRow, 1);
        vatLabel.RawValue = "Sales Tax (VAT 10%):";
        vatLabel.IsBold = true;

        var vatCell = boqSheet.GetOrCreateCell(vatRow, 5);
        vatCell.Formula = $"=F{sumRow + 1}*0.10";
        vatCell.Format = SpreadsheetCellFormat.Currency;
        vatCell.HorizontalAlignment = HorizontalAlignment.Right;

        // Row Grand Total: Sum + VAT
        int grandRow = vatRow + 1;
        var grandLabel = boqSheet.GetOrCreateCell(grandRow, 1);
        grandLabel.RawValue = "FINAL ESTIMATED PROJECT VALUE (INCL. TAX):";
        grandLabel.IsBold = true;
        grandLabel.Foreground = Brushes.Crimson;

        var grandCell = boqSheet.GetOrCreateCell(grandRow, 5);
        grandCell.Formula = $"=F{sumRow + 1}+F{vatRow + 1}";
        grandCell.Format = SpreadsheetCellFormat.Currency;
        grandCell.HorizontalAlignment = HorizontalAlignment.Right;
        grandCell.IsBold = true;
        grandCell.Foreground = Brushes.Crimson;

        // Add 2nd Sheet: Beam Rebar Schedule
        var rebarSheet = new SpreadsheetSheet { Name = "Beam Rebar Schedule", RowCount = 30, ColumnCount = 10 };
        rebarSheet.SetColumnWidth(0, 50);
        rebarSheet.SetColumnWidth(1, 160);
        rebarSheet.SetColumnWidth(2, 90);
        rebarSheet.SetColumnWidth(3, 80);
        rebarSheet.SetColumnWidth(4, 90);
        rebarSheet.SetColumnWidth(5, 120);
        rebarSheet.SetColumnWidth(6, 130);

        void SetRebarHeader(int c, string text)
        {
            var cell = rebarSheet.GetOrCreateCell(0, c);
            cell.RawValue = text;
            cell.IsBold = true;
            cell.HorizontalAlignment = HorizontalAlignment.Center;
            cell.BackgroundResourceKey = "CONCOST.Brush.SurfaceSecondary";
        }
        SetRebarHeader(0, "No.");
        SetRebarHeader(1, "Bar Mark");
        SetRebarHeader(2, "Diameter (mm)");
        SetRebarHeader(3, "Bar Count");
        SetRebarHeader(4, "Cut Length (m)");
        SetRebarHeader(5, "Total Length (m)");
        SetRebarHeader(6, "Total Weight (kg)");

        var rebarRows = new (int stt, string bar, int dia, int count, double len)[]
        {
            (1, "Top main bar T1", 20, 4, 6.2),
            (2, "Bottom main bar B1", 20, 4, 6.2),
            (3, "Side skin bar G1", 14, 2, 5.8),
            (4, "Support shear stirrups S1", 8, 28, 1.45),
            (5, "Span shear stirrups S2", 8, 16, 1.45)
        };

        for (int i = 0; i < rebarRows.Length; i++)
        {
            int r = i + 1;
            var item = rebarRows[i];

            var c0 = rebarSheet.GetOrCreateCell(r, 0); c0.RawValue = item.stt.ToString(); c0.HorizontalAlignment = HorizontalAlignment.Center;
            var c1 = rebarSheet.GetOrCreateCell(r, 1); c1.RawValue = item.bar;
            var c2 = rebarSheet.GetOrCreateCell(r, 2); c2.RawValue = item.dia.ToString(); c2.HorizontalAlignment = HorizontalAlignment.Center;
            var c3 = rebarSheet.GetOrCreateCell(r, 3); c3.RawValue = item.count.ToString(); c3.HorizontalAlignment = HorizontalAlignment.Right;
            var c4 = rebarSheet.GetOrCreateCell(r, 4); c4.RawValue = item.len.ToString("0.##"); c4.HorizontalAlignment = HorizontalAlignment.Right;

            // Total Length = Count * Len = D{r+1}*E{r+1}
            var c5 = rebarSheet.GetOrCreateCell(r, 5);
            c5.Formula = $"=D{r + 1}*E{r + 1}";
            c5.Format = SpreadsheetCellFormat.Number;
            c5.HorizontalAlignment = HorizontalAlignment.Right;

            // Weight = TotalLen * (Dia^2 / 162) = F{r+1} * (C{r+1}^2 / 162)
            var c6 = rebarSheet.GetOrCreateCell(r, 6);
            c6.Formula = $"=ROUND(F{r + 1} * (C{r + 1} * C{r + 1} / 162), 2)";
            c6.Format = SpreadsheetCellFormat.Number;
            c6.HorizontalAlignment = HorizontalAlignment.Right;
            c6.IsBold = true;
        }

        int rebarSumRow = rebarRows.Length + 2;
        var rSumLbl = rebarSheet.GetOrCreateCell(rebarSumRow, 1);
        rSumLbl.RawValue = "TOTAL REBAR WEIGHT (kg):";
        rSumLbl.IsBold = true;
        rSumLbl.ForegroundResourceKey = "CONCOST.Brush.Primary";

        var rSumVal = rebarSheet.GetOrCreateCell(rebarSumRow, 6);
        rSumVal.Formula = $"=SUM(G2:G{rebarRows.Length + 1})";
        rSumVal.Format = SpreadsheetCellFormat.Number;
        rSumVal.HorizontalAlignment = HorizontalAlignment.Right;
        rSumVal.IsBold = true;
        rSumVal.ForegroundResourceKey = "CONCOST.Brush.Primary";

        spBoQ.Sheets = new System.Collections.ObjectModel.ObservableCollection<SpreadsheetSheet> { boqSheet, rebarSheet };
        spBoQ.ActiveSheet = boqSheet;
        spBoQ.ActiveRow = 0;
        spBoQ.ActiveColumn = 0;
        spBoQ.SelectionRange = new SpreadsheetRange(0, 0);
        spBoQ.Recalculate();

        string boqXaml = @"<!-- CONCOST Spreadsheet Control: Engineering Bill of Quantities (BoQ) Template -->
<ui:Spreadsheet x:Name=""BoqSpreadsheet""
                Height=""440""
                ShowToolbar=""True""
                ShowFormulaBar=""True""
                ShowSheetTabs=""True""
                ShowStatusBar=""True""
                ActiveSheet=""{Binding ActiveBoqSheet, Mode=TwoWay}""
                Sheets=""{Binding DocumentSheets}"" />

<!-- C# Code-Behind / ViewModel Initialization -->
// 1. Initialize Sheet and Column Dimensions
var boqSheet = new SpreadsheetSheet { Name = ""Structural BoQ Estimation"", RowCount = 50, ColumnCount = 12 };
boqSheet.SetColumnWidth(1, 240); // Description
boqSheet.SetColumnWidth(5, 140); // Total Amount

// 2. Add Live Excel Formulas (Auto recalculated by Formula Engine)
var totalCell = boqSheet.GetOrCreateCell(row: 1, col: 5);
totalCell.Formula = ""=D2*E2""; // Qty * UnitPrice
totalCell.Format = SpreadsheetCellFormat.Currency;

// 3. Add Summary Formula (SUM, AVERAGE, IF, etc.)
var sumCell = boqSheet.GetOrCreateCell(row: 10, col: 5);
sumCell.Formula = ""=SUM(F2:F9)"";
sumCell.Format = SpreadsheetCellFormat.Currency;
sumCell.IsBold = true;";

        AddCardSection("1. Interactive Engineering Spreadsheet (Live Formulas, In-Place Edit, Multi-Sheet BoQ)", spBoQ, boqXaml);

        // Section 2: Standalone Formula Evaluator & Mini Calculator Playground
        var miniCard = new StackPanel();
        var miniDesc = new TextBlock
        {
            Text = "The built-in Formula Engine supports standard Excel formulas: SUM, AVERAGE, MIN, MAX, COUNT, ROUND, IF, PRODUCT, ABS, SQRT, CONCAT and arithmetic operators (+, -, *, /, ^, comparisons).",
            FontSize = 12.5,
            Margin = new Thickness(0, 0, 0, 14),
            TextWrapping = TextWrapping.Wrap
        };
        miniDesc.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
        miniCard.Children.Add(miniDesc);

        var formulaGrid = new Grid();
        formulaGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        formulaGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(12) });
        formulaGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

        var formulaInput = new TextBox
        {
            Text = "=IF(SUM(150, 250, 100) > 400, \"EXCEEDS LIMIT (\" + SUM(150, 250, 100) + \" kg)\", \"WITHIN LIMIT\")",
            FontSize = 12,
            Padding = new Thickness(8, 6, 8, 6)
        };
        CONCOST.UI.AttachedProperties.InfoElement.SetPlaceholder(formulaInput, "Enter formula e.g. =SUM(1,2,3)...");

        var formulaResult = new TextBox
        {
            IsReadOnly = true,
            FontSize = 12,
            FontWeight = FontWeights.Normal,
            Padding = new Thickness(8, 6, 8, 6)
        };
        formulaResult.SetResourceReference(TextBox.ForegroundProperty, "CONCOST.Brush.Primary");

        void EvalFormula()
        {
            try
            {
                var engine = new SpreadsheetFormulaEngine();
                var dummySheet = new SpreadsheetSheet();
                string txt = formulaInput.Text?.Trim() ?? string.Empty;
                if (!txt.StartsWith("=")) txt = "=" + txt;
                var res = engine.EvaluateExpression(dummySheet, txt.TrimStart('='));
                formulaResult.Text = res?.ToString() ?? "0";
            }
            catch (Exception ex)
            {
                formulaResult.Text = ex.Message;
            }
        }

        formulaInput.TextChanged += (s, e) => EvalFormula();
        EvalFormula();

        Grid.SetColumn(formulaInput, 0);
        Grid.SetColumn(formulaResult, 2);
        formulaGrid.Children.Add(formulaInput);
        formulaGrid.Children.Add(formulaResult);
        miniCard.Children.Add(formulaGrid);

        string formulaXaml = @"<!-- Standalone Spreadsheet Formula Engine Evaluation -->
var engine = new SpreadsheetFormulaEngine();
var result = engine.EvaluateExpression(sheet, ""SUM(A1:A10) * 1.10"");
var ifResult = engine.EvaluateExpression(sheet, ""IF(B2 > 100, B2 * 0.9, B2)"");";

        AddCardSection("2. Built-in Recursive Formula Engine (Excel Compatibility & Standalone Evaluator)", miniCard, formulaXaml);

        return mainSp;
    }

    private object CreateStackedHeaderDataGridDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };

        void AddCardSection(string title, System.Windows.UIElement content, string? xamlSnippet = null, string? csSnippet = null)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(20),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var sp = new StackPanel();
            var headerGrid = new Grid { Margin = new System.Windows.Thickness(0, 0, 0, 14) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

            var titleBlock = new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Normal,
                FontSize = 14,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
            titleBlock.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            Grid.SetColumn(titleBlock, 0);
            headerGrid.Children.Add(titleBlock);

            Border? codeBox = null;
            if (!string.IsNullOrWhiteSpace(xamlSnippet) || !string.IsNullOrWhiteSpace(csSnippet))
            {
                var btnPanel = new StackPanel { Orientation = Orientation.Horizontal };
                Grid.SetColumn(btnPanel, 1);
                headerGrid.Children.Add(btnPanel);

                bool showingXaml = true;
                codeBox = new Border
                {
                    CornerRadius = new System.Windows.CornerRadius(8),
                    BorderThickness = new System.Windows.Thickness(1),
                    Margin = new System.Windows.Thickness(0, 16, 0, 0),
                    Visibility = System.Windows.Visibility.Collapsed
                };
                codeBox.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
                codeBox.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

                var codeInner = new StackPanel();
                var topBar = new Grid { Height = 34, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
                topBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                topBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

                var langLabel = new TextBlock { Text = "XAML", FontSize = 11.5, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                langLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                Grid.SetColumn(langLabel, 0);
                topBar.Children.Add(langLabel);

                var copyBtn = new Button { Content = "Copy", Padding = new System.Windows.Thickness(10, 2, 10, 2), FontSize = 11, Height = 24, VerticalAlignment = System.Windows.VerticalAlignment.Center, Cursor = System.Windows.Input.Cursors.Hand };
                copyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(copyBtn, new System.Windows.CornerRadius(4));
                Grid.SetColumn(copyBtn, 1);
                topBar.Children.Add(copyBtn);
                codeInner.Children.Add(topBar);

                var sep = new Border { Height = 1 };
                sep.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
                codeInner.Children.Add(sep);

                var codeText = new TextBlock
                {
                    Text = (xamlSnippet ?? "").Trim(),
                    FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New"),
                    FontSize = 12,
                    LineHeight = 19,
                    Padding = new System.Windows.Thickness(14, 12, 14, 12),
                    TextWrapping = System.Windows.TextWrapping.Wrap
                };
                codeText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                codeInner.Children.Add(codeText);
                codeBox.Child = codeInner;

                if (!string.IsNullOrWhiteSpace(xamlSnippet))
                {
                    var xamlBtn = new Button { Content = "View XAML", Padding = new System.Windows.Thickness(10, 4, 10, 4), FontSize = 11, Margin = new System.Windows.Thickness(0, 0, 6, 0), Cursor = System.Windows.Input.Cursors.Hand };
                    xamlBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
                    CONCOST.UI.AttachedProperties.IconElement.SetKind(xamlBtn, IconKind.Edit);
                    CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(xamlBtn, new System.Windows.CornerRadius(6));
                    xamlBtn.Click += (s, e) =>
                    {
                        showingXaml = true;
                        langLabel.Text = "XAML";
                        codeText.Text = (xamlSnippet ?? "").Trim();
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                    };
                    btnPanel.Children.Add(xamlBtn);
                }
                if (!string.IsNullOrWhiteSpace(csSnippet))
                {
                    var csBtn = new Button { Content = "View C#", Padding = new System.Windows.Thickness(10, 4, 10, 4), FontSize = 11, Cursor = System.Windows.Input.Cursors.Hand };
                    csBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Outline");
                    CONCOST.UI.AttachedProperties.IconElement.SetKind(csBtn, IconKind.Edit);
                    CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(csBtn, new System.Windows.CornerRadius(6));
                    csBtn.Click += (s, e) =>
                    {
                        showingXaml = false;
                        langLabel.Text = "C#";
                        codeText.Text = (csSnippet ?? "").Trim();
                        codeBox.Visibility = System.Windows.Visibility.Visible;
                    };
                    btnPanel.Children.Add(csBtn);
                }
                copyBtn.Click += (s, e) =>
                {
                    try
                    {
                        var toCopy = showingXaml ? (xamlSnippet ?? "") : (csSnippet ?? "");
                        System.Windows.Clipboard.SetText(toCopy.Trim());
                        copyBtn.Content = "Copied!";
                        var t = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
                        t.Tick += (ts, te) => { copyBtn.Content = "Copy"; t.Stop(); };
                        t.Start();
                    }
                    catch { }
                };
            }

            sp.Children.Add(headerGrid);
            sp.Children.Add(content);
            if (codeBox != null) sp.Children.Add(codeBox);
            card.Child = sp;
            mainSp.Children.Add(card);
        }

        // ── Section 1: Basic Stacked Header DataGrid ──────────────────────────
        var dg1 = new CONCOST.UI.Controls.StackedHeaderDataGrid
        {
            Height = 260,
            AutoGenerateColumns = false,
            CanUserAddRows = false,
