            SelectionMode = DataGridSelectionMode.Single
        };
        dg1.SetResourceReference(DataGrid.StyleProperty, "CONCOST.DataGrid.Default");
        VirtualizingPanel.SetIsVirtualizing(dg1, true);
        VirtualizingPanel.SetVirtualizationMode(dg1, VirtualizationMode.Recycling);
        VirtualizingPanel.SetScrollUnit(dg1, ScrollUnit.Pixel);

        // Build 3-level header tree: Structural Info > [Member ID, Floor] | Section > [Width(mm), Height(mm)] | Reinforcement > [Rebar Top, Rebar Bot]
        var grpStructure = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "Structural Information" };
        grpStructure.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Member ID", BindingPath = "MemberId", Width = new DataGridLength(110), AggregateType = AggregateType.Count, AggregateFormat = "n='{0}'" });
        grpStructure.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Floor Level", BindingPath = "FloorLevel", Width = new DataGridLength(90) });
        dg1.ColumnHeaderTree.Add(grpStructure);

        var grpSection = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "Section (mm)" };
        grpSection.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Width", BindingPath = "Width", Width = new DataGridLength(80), AggregateType = AggregateType.Average, AggregateFormat = "avg={0:F0}" });
        grpSection.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Height", BindingPath = "Height", Width = new DataGridLength(80), AggregateType = AggregateType.Average, AggregateFormat = "avg={0:F0}" });
        grpSection.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Length", BindingPath = "Length", Width = new DataGridLength(80), AggregateType = AggregateType.Sum, AggregateFormat = "sum={0:F0}" });
        dg1.ColumnHeaderTree.Add(grpSection);

        var grpReinf = new CONCOST.UI.Controls.ColumnGroup { HeaderText = "Reinforcement" };
        grpReinf.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Rebar Top", BindingPath = "RebarTop", Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
        grpReinf.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Rebar Bot", BindingPath = "RebarBot", Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
        grpReinf.Children.Add(new CONCOST.UI.Controls.ColumnLeaf { HeaderText = "Weight (kg)", BindingPath = "RebarWeight", StringFormat = "N1", Width = new DataGridLength(95), AggregateType = AggregateType.Sum, AggregateFormat = "sum={0:N0} kg" });
        dg1.ColumnHeaderTree.Add(grpReinf);

        var beamData1 = new[]
        {
            new { MemberId = "D1-A/1-2", FloorLevel = "LEVEL 1", Width = 300.0, Height = 600.0, Length = 6500.0, RebarTop = "4D20", RebarBot = "2D18", RebarWeight = 850.5 },
            new { MemberId = "D2-B/2-3", FloorLevel = "LEVEL 1", Width = 250.0, Height = 500.0, Length = 5000.0, RebarTop = "3D18", RebarBot = "2D16", RebarWeight = 620.0 },
            new { MemberId = "D3-A/3-4", FloorLevel = "LEVEL 2", Width = 300.0, Height = 700.0, Length = 7200.0, RebarTop = "6D22", RebarBot = "4D20", RebarWeight = 1150.8 },
            new { MemberId = "D4-C/1-2", FloorLevel = "LEVEL 2", Width = 200.0, Height = 400.0, Length = 4800.0, RebarTop = "3D16", RebarBot = "2D14", RebarWeight = 540.2 },
            new { MemberId = "D5-D/2-3", FloorLevel = "ROOF",    Width = 250.0, Height = 500.0, Length = 6000.0, RebarTop = "4D18", RebarBot = "2D16", RebarWeight = 730.0 },
        };
        dg1.ItemsSource = beamData1;

        var xamlBasic = @"<controls:StackedHeaderDataGrid
    ItemsSource=""{Binding BeamList}""
    AutoGenerateColumns=""False""
    ShowFooterSummary=""True"">

    <controls:StackedHeaderDataGrid.ColumnHeaderTree>
        <controls:ColumnGroup HeaderText=""Structural Information"">
            <controls:ColumnLeaf HeaderText=""Member ID"" BindingPath=""MemberId""
                AggregateType=""Count"" AggregateFormat=""n='{0}'""/>
            <controls:ColumnLeaf HeaderText=""Floor Level"" BindingPath=""FloorLevel""/>
        </controls:ColumnGroup>
        <controls:ColumnGroup HeaderText=""Section (mm)"">
            <controls:ColumnLeaf HeaderText=""Width""
                BindingPath=""Width"" AggregateType=""Average""
                AggregateFormat=""avg={0:F0}""/>
            <controls:ColumnLeaf HeaderText=""Height""
                BindingPath=""Height"" AggregateType=""Average""
                AggregateFormat=""avg={0:F0}""/>
        </controls:ColumnGroup>
        <controls:ColumnGroup HeaderText=""Reinforcement"">
            <controls:ColumnLeaf HeaderText=""Rebar Top"" BindingPath=""RebarTop""/>
            <controls:ColumnLeaf HeaderText=""Weight (kg)""
                BindingPath=""RebarWeight"" StringFormat=""N1""
                AggregateType=""Sum"" AggregateFormat=""sum={0:N0} kg""/>
        </controls:ColumnGroup>
    </controls:StackedHeaderDataGrid.ColumnHeaderTree>

</controls:StackedHeaderDataGrid>";

        var csBasic = @"// ViewModel
public ObservableCollection<BeamElement> BeamList { get; } = new();

public class BeamElement
{
    public string MemberId { get; set; }
    public string FloorLevel { get; set; }
    public double Width { get; set; }
    public double Height { get; set; }
    public string RebarTop { get; set; }
    public double RebarWeight { get; set; }
}

// Code-behind: Load data
BeamList.Add(new BeamElement {
    MemberId = ""D1-A/1-2"", FloorLevel = ""LEVEL 1"",
    Width = 300, Height = 600,
    RebarTop = ""4D20"", RebarWeight = 850.5
});";

        AddCardSection("1. Stacked Column Headers — Multi-Level Grouping", dg1, xamlBasic, csBasic);

        // ── Section 2: Footer Aggregates ──────────────────────────────────────
        var footerInfoSp = new StackPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 12) };
        var aggregateTypes = new[]
        {
            ("Count", "Counts non-null values → n='5'"),
            ("Sum", "Sums numeric values → sum=33,500"),
            ("Average", "Averages numeric values → avg=280"),
            ("Min / Max", "Finds min or max value in column"),
            ("Custom", "CustomAggregateText: free-form footer text")
        };
        var infoGrid = new UniformGrid { Columns = 2, Margin = new System.Windows.Thickness(0, 8, 0, 0) };
        foreach (var (type, desc) in aggregateTypes)
        {
            var chip = new Border
            {
                CornerRadius = new System.Windows.CornerRadius(6),
                BorderThickness = new System.Windows.Thickness(1),
                Padding = new System.Windows.Thickness(12, 8, 12, 8),
                Margin = new System.Windows.Thickness(0, 0, 8, 8)
            };
            chip.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            chip.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
            var chipSp = new StackPanel();
            var typeLabel = new TextBlock { Text = type, FontWeight = System.Windows.FontWeights.Normal, FontSize = 13 };
            typeLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
            var descLabel = new TextBlock { Text = desc, FontSize = 11.5, TextWrapping = System.Windows.TextWrapping.Wrap, Margin = new System.Windows.Thickness(0, 2, 0, 0) };
            descLabel.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            chipSp.Children.Add(typeLabel);
            chipSp.Children.Add(descLabel);
            chip.Child = chipSp;
            infoGrid.Children.Add(chip);
        }

