        <controls:ColumnLeaf HeaderText=""Stress Ratio"" BindingPath=""StressRatio"" CellType=""Numeric"" StringFormat=""N2""/>
        
        <!-- Graphical Progress / Data Bar -->
        <controls:ColumnLeaf HeaderText=""Load Ratio Bar"" BindingPath=""StressPercent"" CellType=""Progress"" Width=""180""/>
        
        <!-- Safety Status Badge (APPROVED / WARNING / OVERLOAD) -->
