        var sec7Cs = @"// Engineering Validation Model:
public class ElementSafetyItem : INotifyDataErrorInfo
{
    public string ElementId { get; set; }
    public double Capacity { get; set; }
    public double AppliedLoad { get; set; }
    public double StressRatio => AppliedLoad / (Capacity > 0 ? Capacity : 1);
    public double StressPercent => Math.Min(100.0, StressRatio * 100);
    public string Status => StressRatio > 1.0 ? ""OVERLOAD"" : StressRatio > 0.85 ? ""WARNING"" : ""APPROVED"";

    // INotifyDataErrorInfo implementation for visual error glow:
    public bool HasErrors => StressRatio > 1.0;
    public IEnumerable GetErrors(string? propertyName)
    {
        if (propertyName == nameof(AppliedLoad) && StressRatio > 1.0)
            yield return ""Applied load exceeds safe structural limit!"";
    }
}";

