        var pager = new DataPager
        {
            PageSize = 5,
            TotalItems = 30,
            Margin = new System.Windows.Thickness(0, 10, 0, 0),
            HorizontalAlignment = HorizontalAlignment.Right
        };
        sec8Sp.Children.Add(pager);

        // Generate 30 sample items
        var allRecords = new System.Collections.Generic.List<BoqGroupItem>();
        var classifications = new[] { "Structural Steel", "Precast Concrete", "Cast-in-place Slab", "Facade Glazing", "Reinforced Masonry" };
        var states = new[] { "APPROVED", "IN PROGRESS", "PENDING" };
        for (int r = 1; r <= 30; r++)
        {
            allRecords.Add(new BoqGroupItem
            {
                ItemCode = $"REC-{r:D3}",
                Category = classifications[(r - 1) % classifications.Length],
                Description = $"Grade ASTM-A36 / EN 10025-2 Section HEB-{200 + (r * 10)}",
                Quantity = Math.Round(2.4 + (r * 0.85), 2),
                Status = states[(r - 1) % states.Length]
            });
        }

        void RefreshPagedGrid()
        {
            string q = searchBox.Text?.Trim() ?? "";
            var filtered = allRecords.Where(item =>
                string.IsNullOrEmpty(q) ||
                item.ItemCode.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0 ||
                item.Category.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0 ||
                item.Description.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0
            ).ToList();

            pager.TotalItems = filtered.Count;
            int page = Math.Max(1, Math.Min(pager.PageIndex, pager.TotalPages));
            int skip = (page - 1) * pager.PageSize;
            var pageItems = filtered.Skip(skip).Take(pager.PageSize).Select((x, idx) => new
            {
                No = skip + idx + 1,
                RecordId = x.ItemCode,
                Classification = x.Category,
                Specification = x.Description,
                Mass = x.Quantity,
                State = x.Status
            }).ToList();
            pagedGrid.ItemsSource = pageItems;
            pagerInfo.Text = $"Page {page} of {pager.TotalPages} — Showing {pageItems.Count} of {filtered.Count} records";
        }

        pager.PageChanged += (s, e) => RefreshPagedGrid();
        searchBox.TextChanged += (s, e) =>
        {
            pager.PageIndex = 1;
            RefreshPagedGrid();
        };

        RefreshPagedGrid();

        var sec8Xaml = @"<!-- Real-Time Auto-Filter & Integrated DataPager Control -->
<StackPanel>
    <Grid Margin=""0,0,0,10"">
        <controls:SearchBox
            Placeholder=""Filter records by ID, category, or mark...""
            Width=""280"" HorizontalAlignment=""Left""/>
    </Grid>

    <controls:StackedHeaderDataGrid
        ItemsSource=""{Binding PagedRecords}""
        ShowFooterSummary=""False"">
        <controls:StackedHeaderDataGrid.ColumnHeaderTree>
            <controls:ColumnLeaf HeaderText=""#"" BindingPath=""No"" Width=""50""/>
            <controls:ColumnLeaf HeaderText=""Record ID"" BindingPath=""RecordId"" Width=""110""/>
            <controls:ColumnLeaf HeaderText=""Classification"" BindingPath=""Classification"" Width=""150""/>
            <controls:ColumnLeaf HeaderText=""Specification"" BindingPath=""Specification"" Width=""*""/>
            <controls:ColumnLeaf HeaderText=""Total Mass (t)"" BindingPath=""Mass"" CellType=""Numeric"" StringFormat=""N2""/>
            <controls:ColumnLeaf HeaderText=""State"" BindingPath=""State"" CellType=""Badge""/>
        </controls:StackedHeaderDataGrid.ColumnHeaderTree>
    </controls:StackedHeaderDataGrid>

    <!-- DataPager Control: Page Navigation Buttons |< < 1 2 > >| -->
    <controls:DataPager
        PageIndex=""{Binding CurrentPage, Mode=TwoWay}""
        PageSize=""{Binding PageSize}""
        TotalItems=""{Binding TotalCount}""
        HorizontalAlignment=""Right""
        Margin=""0,10,0,0""/>
</StackPanel>";

        var sec8Cs = @"// ViewModel Paging:
public int CurrentPage { get; set; } = 1;
public int PageSize { get; set; } = 10;
public int TotalCount => FullList.Count;

public IEnumerable<RecordItem> PagedRecords =>
    FullList.Skip((CurrentPage - 1) * PageSize).Take(PageSize);

// Re-evaluate on PageChanged:
OnPropertyChanged(nameof(PagedRecords));";

        AddCardSection("8. Real-Time Auto-Filter & Pagination — DataPager", sec8Sp, sec8Xaml, sec8Cs);

        return mainSp;
    }

    private object CreateDocumentationDemo()
    {
        var mainSp = new StackPanel { Margin = new System.Windows.Thickness(0) };
        string T(string vietnamese, string english) =>
            LocalizationManager.Current.Culture.TwoLetterISOLanguageName.Equals("vi", StringComparison.OrdinalIgnoreCase)
                ? vietnamese
                : english;

        void AddCard(System.Windows.UIElement content)
        {
            var card = new Border
            {
                BorderThickness = new System.Windows.Thickness(1),
                CornerRadius = new System.Windows.CornerRadius(10),
                Padding = new System.Windows.Thickness(24),
                Margin = new System.Windows.Thickness(0, 0, 0, 18)
            };
            card.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Surface");
            card.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
            card.Child = content;
            mainSp.Children.Add(card);
        }

        void AddCodeCard(string title, string code, string lang = "XAML", string? description = null)
        {
            var sp = new StackPanel();
            var hdr = new TextBlock { Text = title, FontSize = 16, FontWeight = System.Windows.FontWeights.SemiBold, Margin = new System.Windows.Thickness(0, 0, 0, 6) };
            hdr.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            sp.Children.Add(hdr);
            if (!string.IsNullOrWhiteSpace(description))
            {
                var explanation = new TextBlock
                {
                    Text = description,
                    FontSize = 13,
                    LineHeight = 20,
                    TextWrapping = System.Windows.TextWrapping.Wrap,
                    Margin = new System.Windows.Thickness(0, 0, 0, 12)
                };
                explanation.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
                sp.Children.Add(explanation);
            }

            var codeBorder = new Border { CornerRadius = new System.Windows.CornerRadius(8), BorderThickness = new System.Windows.Thickness(1) };
            codeBorder.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            codeBorder.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");

            var codeInner = new StackPanel();
            var codeBar = new Grid { Height = 32, Margin = new System.Windows.Thickness(12, 0, 8, 0) };
            codeBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            codeBar.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });
            var langLbl = new TextBlock { Text = lang, FontSize = 11, FontWeight = System.Windows.FontWeights.Normal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
            langLbl.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            Grid.SetColumn(langLbl, 0);
            codeBar.Children.Add(langLbl);
            var cpyBtn = new Button { Content = T("Sao chép", "Copy"), Padding = new System.Windows.Thickness(10, 2, 10, 2), FontSize = 11, Height = 22, VerticalAlignment = System.Windows.VerticalAlignment.Center, Cursor = System.Windows.Input.Cursors.Hand };
            cpyBtn.SetResourceReference(Button.StyleProperty, "CONCOST.Button.Secondary");
            CONCOST.UI.AttachedProperties.BorderElement.SetCornerRadius(cpyBtn, new System.Windows.CornerRadius(4));
            cpyBtn.Click += (s, e) => { try { System.Windows.Clipboard.SetText(code.Trim()); cpyBtn.Content = T("Đã sao chép", "Copied!"); var t = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) }; t.Tick += (ts, te) => { cpyBtn.Content = T("Sao chép", "Copy"); t.Stop(); }; t.Start(); } catch { } };
            Grid.SetColumn(cpyBtn, 1);
            codeBar.Children.Add(cpyBtn);
            codeInner.Children.Add(codeBar);
            var divLine = new Border { Height = 1 };
            divLine.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.Border");
            codeInner.Children.Add(divLine);
            var codeText = new TextBlock
            {
                Text = code.Trim(),
                FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New"),
                FontSize = 12,
                LineHeight = 18,
                Padding = new System.Windows.Thickness(14, 10, 14, 10),
                TextWrapping = System.Windows.TextWrapping.Wrap
            };
            codeText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            codeInner.Children.Add(codeText);
            codeBorder.Child = codeInner;
            sp.Children.Add(codeBorder);
            AddCard(sp);
        }

        // ── Overview Banner ───────────────────────────────────────────────────
        var bannerGrid = new Grid();
        bannerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
        bannerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = System.Windows.GridLength.Auto });

        var bannerTextSp = new StackPanel();
        var bannerTitle = new TextBlock
        {
            Text = "CONCOST.UI",
            FontSize = 28,
            FontWeight = System.Windows.FontWeights.Normal,
            Margin = new System.Windows.Thickness(0, 0, 0, 6)
        };
        bannerTitle.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");

        var bannerSub = new TextBlock
        {
            Text = T(
                "Thư viện control WPF cho phần mềm kỹ thuật, CAD và xây dựng. Hướng dẫn này trình bày cách cài đặt, nạp tài nguyên, đổi theme và sử dụng control trong ứng dụng Desktop hoặc plugin.",
                "A WPF control library for engineering, CAD, and construction software. This guide covers installation, resource setup, runtime themes, and control usage in desktop apps and plugins."),
            FontSize = 14,
            TextWrapping = System.Windows.TextWrapping.Wrap,
            Margin = new System.Windows.Thickness(0, 0, 0, 14)
        };
        bannerSub.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");

        var statWrap = new System.Windows.Controls.WrapPanel();
        var stats = new[]
        {
            ("65+", T("Control", "Controls")),
            ("3", T("Dự án", "Projects")),
