        // ── Section 1: Installation / Quick Start ─────────────────────────────
        AddCodeCard(T("1. Cài đặt và tham chiếu thư viện", "1. Install and reference the library"),
@"<!-- In your WPF project (.csproj) -->
<ItemGroup>
  <ProjectReference Include=""..\..\src\CONCOST.UI\CONCOST.UI.csproj"" />
</ItemGroup>

<!-- Run from the Showcase project directory when using this repository -->
dotnet add reference ..\..\src\CONCOST.UI\CONCOST.UI.csproj", "XML / CLI",
            T("Ứng dụng host cần target net8.0-windows và bật UseWPF. Nếu hai project nằm trong cùng solution, dùng ProjectReference để Visual Studio build đúng thứ tự và tự đưa assembly vào output. Đường dẫn trong ví dụ áp dụng cho thư mục samples/CONCOST.UI.Showcase của repository này; hãy sửa đường dẫn tương đối nếu cấu trúc project khác.",
              "The host must target net8.0-windows with UseWPF enabled. A ProjectReference lets Visual Studio build projects in order and copy the library into the output. The path shown is relative to this repository's samples/CONCOST.UI.Showcase folder; adjust it for your solution layout."));

        // ── Section 2: App.xaml Setup ─────────────────────────────────────────
        AddCodeCard(T("2. Ứng dụng Desktop — nạp tài nguyên trong App.xaml", "2. Desktop application — load resources in App.xaml"),
@"<Application.Resources>
  <ResourceDictionary>
    <ResourceDictionary.MergedDictionaries>
      <!-- Load design tokens and the default Light theme first -->
      <ResourceDictionary
          Source=""pack://application:,,,/CONCOST.UI;component/Themes/ThemeResources.xaml"" />

      <!-- Load control templates and styles after the theme resources -->
      <ResourceDictionary
          Source=""pack://application:,,,/CONCOST.UI;component/Themes/Generic.xaml"" />
    </ResourceDictionary.MergedDictionaries>
  </ResourceDictionary>
</Application.Resources>", "XAML",
            T("Dùng cách này cho ứng dụng WPF Desktop có App.xaml. Thứ tự quan trọng: ThemeResources.xaml nạp token và theme mặc định trước, Generic.xaml nạp style/template của control sau. Không tạo Application thứ hai trong thư viện.",
              "Use this setup in a WPF desktop app with App.xaml. Dictionary order matters: ThemeResources.xaml loads tokens and the default theme first; Generic.xaml then loads control styles and templates. A class library should not create a second Application."));

        // ── Section 3: ThemeManager ───────────────────────────────────────────
        AddCodeCard(T("3. Đổi theme trong ứng dụng Desktop", "3. Switch themes in a desktop application"),
@"using System.Windows.Media;
using CONCOST.UI.Themes;

// Switch the application resources to Dark
ThemeManager.Current.Theme = AppTheme.Dark;

// Follow the Windows system preference
ThemeManager.Current.Theme = AppTheme.System;

// Change accent color
ThemeManager.Current.AccentColor = Colors.Teal;", "C#",
            T("ThemeManager.Current.Theme đổi tài nguyên toàn ứng dụng và hỗ trợ Light, Dark hoặc System. AccentColor nhận một System.Windows.Media.Color. Các control dùng DynamicResource sẽ cập nhật theo theme mới.",
              "ThemeManager.Current.Theme switches application resources and supports Light, Dark, or System. AccentColor accepts a System.Windows.Media.Color. Controls using DynamicResource update when the theme changes."));

        AddCodeCard(T("4. Plugin Revit/AutoCAD — áp dụng theme theo cửa sổ", "4. Revit/AutoCAD plugin — scope the theme to a view"),
@"using System.Windows;
using CONCOST.UI.Themes;

public static void ApplyPluginTheme(FrameworkElement pluginRoot)
{
    // The plugin host owns the process and may not expose Application resources.
    ThemeManager.Current.ApplyTheme(pluginRoot, AppTheme.Dark);
}

// Switch this plugin view at runtime:
ThemeManager.Current.ApplyTheme(pluginRoot, AppTheme.Light);", "C#",
            T("Plugin WPF thường chạy bên trong tiến trình Revit/AutoCAD nên không sở hữu Application.Current. Truyền root FrameworkElement của cửa sổ/user control vào overload ApplyTheme(root, theme) để tài nguyên được gắn trong phạm vi view, tránh thay theme của toàn host.",
              "A WPF plugin runs inside Revit/AutoCAD and usually does not own Application.Current. Pass the root FrameworkElement to ApplyTheme(root, theme) to scope resources to that view instead of changing the host application's theme."));

        // ── Section 5: Namespace Usage ────────────────────────────────────────
        AddCodeCard(T("5. Khai báo namespace và dùng control", "5. Declare namespaces and use controls"),
@"<!-- XAML namespace declaration -->
<Window
    xmlns:ui=""clr-namespace:CONCOST.UI.Controls;assembly=CONCOST.UI""
    xmlns:icons=""clr-namespace:CONCOST.UI.Icons;assembly=CONCOST.UI""
    xmlns:ap=""clr-namespace:CONCOST.UI.AttachedProperties;assembly=CONCOST.UI"">

  <!-- Using controls -->
  <ui:NumericUpDown Value=""{Binding Width}"" Minimum=""0"" Maximum=""5000"" />
  <icons:Icon Kind=""Save"" Width=""20"" Height=""20"" />

  <!-- Using AttachedProperties -->
  <TextBox ap:InfoElement.Placeholder=""Enter member name..."" />
  <Button ap:IconElement.Kind=""Save"" Content=""Save"" />

</Window>", "XAML",
            T("Khai báo namespace một lần ở root view, sau đó dùng control qua tiền tố ui và icon qua icons. Giá trị Value có thể binding hai chiều với ViewModel. Các thuộc tính mở rộng như Placeholder và IconElement được khai báo bằng namespace ap.",
              "Declare the namespaces once on the root view. Use the ui prefix for controls and icons for vector icons. Bind Value to a ViewModel; attached properties such as Placeholder and IconElement use the ap namespace."));

        AddCodeCard(T("6. Binding dữ liệu với ViewModel", "6. Bind control values to a ViewModel"),
@"using System;
using System.ComponentModel;

public sealed class BeamViewModel : INotifyPropertyChanged
{
    private double _width = 300;

    public double Width
    {
        get => _width;
        set
        {
            if (Math.Abs(_width - value) < 0.0001) return;
            _width = value;
            PropertyChanged?.Invoke(this,
                new PropertyChangedEventArgs(nameof(Width)));
        }
    }

    public event PropertyChangedEventHandler? PropertyChanged;
}

// Set the view's DataContext to a BeamViewModel instance.", "C#",
