            var hdr = new TextBlock { Text = hdrTitles[c], FontWeight = System.Windows.FontWeights.Normal, FontSize = 11.5, Padding = new System.Windows.Thickness(8, 6, 8, 6), Margin = new System.Windows.Thickness(0, 0, 0, 2) };
