                if (c == 1) cellText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.Primary");
                else cellText.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
                cell.Child = cellText;
                Grid.SetColumn(cell, c);
