            (T("Điều khiển cơ bản", "Basic Controls"), IconKind.Layers, "Button · Icon · TextBlock · Card · Badge · Tag · Divider · SplitButton"),
            (T("Điều khiển nhập liệu", "Input Controls"), IconKind.Edit, "TextBox · NumericUpDown · ComboBox · CheckBox · RadioButton · ToggleSwitch · ColorPicker · SearchBox · FilePicker · PasswordInput · AutoCompleteTextBox · CheckComboBox · RangeSlider · PinBox · OtpInput"),
            (T("Điều khiển dữ liệu", "Data Controls"), IconKind.Layers, "DataGrid · StackedHeaderDataGrid · TreeView · ListView · Pagination · Transfer · PropertyGrid · Spreadsheet"),
            (T("Điều hướng", "Navigation"), IconKind.Menu, "SideMenu · DrawerMenu · Breadcrumb · StepBar · Tabs"),
            (T("Phản hồi và lớp phủ", "Feedback & Overlay"), IconKind.Bell, "Dialog · Growl · Drawer · LoadingIndicator · Skeleton · EmptyState · Ripple · Watermark"),
            (T("Biểu đồ và Canvas", "Charts & Canvas"), IconKind.Layers, "ChartBar · ChartLine · ChartPie · ChartRadar · CompareSlider · Magnifier · ZoomableCanvas"),
            (T("Công cụ kỹ thuật", "Engineering"), IconKind.TuneAdjust, "UnitBox · RebarInput · CompassIndicator · CoordinateInput · Dashboard suite"),
        };

        var catWrap = new System.Windows.Controls.WrapPanel { Margin = new System.Windows.Thickness(0) };
        foreach (var (catName, catIcon, controls) in categories)
        {
            var catCard = new Border
            {
                CornerRadius = new System.Windows.CornerRadius(8),
                BorderThickness = new System.Windows.Thickness(1),
                Padding = new System.Windows.Thickness(14, 12, 14, 12),
                Margin = new System.Windows.Thickness(0, 0, 10, 10),
                Width = 310
            };
            catCard.SetResourceReference(Border.BackgroundProperty, "CONCOST.Brush.SurfaceSecondary");
            catCard.SetResourceReference(Border.BorderBrushProperty, "CONCOST.Brush.Border");
            var catCardSp = new StackPanel();
            var catHeaderRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new System.Windows.Thickness(0, 0, 0, 8) };
            var catIco = new CONCOST.UI.Icons.Icon { Kind = catIcon, Width = 16, Height = 16, Margin = new System.Windows.Thickness(0, 0, 8, 0) };
            catIco.SetResourceReference(CONCOST.UI.Icons.Icon.ForegroundProperty, "CONCOST.Brush.Primary");
            var catNameLbl = new TextBlock { Text = catName, FontWeight = System.Windows.FontWeights.Normal, FontSize = 13 };
            catNameLbl.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextPrimary");
            catHeaderRow.Children.Add(catIco);
            catHeaderRow.Children.Add(catNameLbl);
            var catControls = new TextBlock { Text = controls, FontSize = 11.5, TextWrapping = System.Windows.TextWrapping.Wrap, LineHeight = 18 };
            catControls.SetResourceReference(TextBlock.ForegroundProperty, "CONCOST.Brush.TextSecondary");
            catCardSp.Children.Add(catHeaderRow);
            catCardSp.Children.Add(catControls);
            catCard.Child = catCardSp;
            catWrap.Children.Add(catCard);
        }
        catSp.Children.Add(catWrap);
        AddCard(catSp);

        // ── Section 9: Naming Convention ──────────────────────────────────────
        AddCodeCard(T("9. Quy ước đặt tên resource", "9. Resource naming conventions"),
@"<!-- Styles -->
{StaticResource CONCOST.Button.Primary}
{StaticResource CONCOST.Button.Secondary}
{StaticResource CONCOST.Button.Outline}
{StaticResource CONCOST.Button.Ghost}
{StaticResource CONCOST.Button.Danger}
{StaticResource CONCOST.DataGrid.Default}
{StaticResource CONCOST.DataGrid.Compact}
{StaticResource CONCOST.DataGrid.Bordered}

<!-- Brushes -->
{DynamicResource CONCOST.Brush.Primary}
{DynamicResource CONCOST.Brush.Background}
{DynamicResource CONCOST.Brush.Surface}
{DynamicResource CONCOST.Brush.SurfaceSecondary}
{DynamicResource CONCOST.Brush.Border}
{DynamicResource CONCOST.Brush.TextPrimary}
{DynamicResource CONCOST.Brush.TextSecondary}

<!-- Typography -->
{StaticResource CONCOST.FontSize.Default}     <!-- 14 -->
{StaticResource CONCOST.FontSize.Large}        <!-- 16 -->
{StaticResource CONCOST.FontSize.Title}        <!-- 20 -->
{StaticResource CONCOST.CornerRadius.Default}  <!-- 6  -->
{StaticResource CONCOST.CornerRadius.Card}     <!-- 10 -->", "XAML",
            T("Style và token dùng tiền tố CONCOST. Dùng StaticResource cho giá trị cố định, DynamicResource cho tài nguyên cần cập nhật khi đổi theme hoặc màu nhấn.",
              "Styles and tokens use the CONCOST prefix. Use StaticResource for fixed values and DynamicResource for resources that should update with the runtime theme or accent."));

        // ── Section 10: Attached Properties ──────────────────────────────────
        AddCodeCard(T("10. Attached Property — mở rộng control WPF", "10. Attached properties — extend WPF controls"),
@"<!-- InfoElement: placeholder text, required indicator, label -->
<TextBox
    ap:InfoElement.Placeholder=""Enter member name...""
    ap:InfoElement.Required=""True"" />

<!-- IconElement: icon on buttons/textboxes -->
<Button
    ap:IconElement.Kind=""Save""
    Content=""Save Element"" />

<!-- BorderElement: per-control corner radius override -->
<Button
    ap:BorderElement.CornerRadius=""20"" />

<!-- DataGridElement: row numbers, striped rows -->
<DataGrid
    ap:DataGridElement.ShowRowNumber=""True""
    ap:DataGridElement.EnableStripedRows=""True"" />", "XAML",
            T("Attached Property cho phép thêm placeholder, icon hoặc tùy chọn DataGrid mà không cần tạo control kế thừa. Dùng namespace ap đã khai báo trên root view.",
              "Attached properties add placeholders, icons, or DataGrid options without subclassing a control. Use the ap namespace declared on the root view."));

        AddCodeCard(T("11. Triển khai và xử lý lỗi tích hợp", "11. Deployment and integration checks"),
@"<!-- Verify the host project configuration -->
<PropertyGroup>
  <TargetFramework>net8.0-windows</TargetFramework>
  <UseWPF>true</UseWPF>
</PropertyGroup>

<!-- Use a project reference during development -->
<ItemGroup>
  <ProjectReference Include=""..\..\src\CONCOST.UI\CONCOST.UI.csproj"" />
</ItemGroup>", "XML",
            T("Kiểm tra host target đúng net8.0-windows, bật UseWPF và tham chiếu đúng assembly CONCOST.UI. Ứng dụng Desktop nạp hai dictionary ở App.xaml; plugin không có App.xaml thì áp dụng theme theo root view. Khi đóng gói, giữ các runtime/dependency mà host yêu cầu và kiểm tra đúng phiên bản .NET/WPF của Revit hoặc AutoCAD. Nếu control hiện nhưng thiếu style, kiểm tra ThemeResources.xaml được nạp trước Generic.xaml.",
              "Confirm the host targets net8.0-windows, enables UseWPF, and references the intended CONCOST.UI assembly. Desktop apps merge both dictionaries in App.xaml; plugins without App.xaml apply a scoped theme to the root view. Keep the runtime and dependencies required by the host, and verify against the .NET/WPF version used by Revit or AutoCAD. If controls appear without styling, check that ThemeResources.xaml loads before Generic.xaml."));

        return mainSp;
    }
}
